const i=[{id:"CASE-08",ue:"1.6",title:"Main de bénédiction après fracture du coude",neutralTitle:"Difficulté à fermer le poing après fracture du coude chez un homme de 28 ans",priority:"A",vignette:"Homme 28 ans, chute à vélo, fracture supracondylienne du coude traitée orthopédiquement. À 2 semaines, il ne parvient plus à fermer complètement le poing : l'index et le majeur restent en extension partielle. Il ne signale aucun trouble de sensibilité.",objective:"Localiser le niveau d'une atteinte du nerf médian après un traumatisme du coude et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quel élément anamnestique demandes-tu en priorité ?",options:[{id:"a",label:"Délai d'apparition du déficit par rapport au traumatisme et à son traitement, et son évolution",correct:!0,critical:!0},{id:"b",label:"Présence ou absence de fourmillements ou d'engourdissement associés",correct:!0,critical:!0},{id:"c",label:"Habitudes alimentaires récentes"}],reveal:"Déficit apparu progressivement après l'immobilisation, sans aucun trouble sensitif rapporté."},{kind:"exam",prompt:"Quel test clinique permet de confirmer une atteinte du nerf interosseux antérieur ?",options:[{id:"a",label:"Test du signe « OK » (pince pouce-index)",correct:!0,critical:!0},{id:"b",label:"Signe de Tinel au poignet"},{id:"c",label:"Force d'abduction du pouce (muscle abducteur court)"}],reveal:"Le patient ne peut pas former un « O » avec le pouce et l'index : le pouce fléchit en interphalangienne et l'index reste en extension à ce niveau, signant une atteinte motrice du nerf interosseux antérieur."},{kind:"decision",prompt:"Quelle est la conduite appropriée à ce stade ?",options:[{id:"a",label:"Surveiller seul, sans avis médical, et poursuivre un suivi ostéopathique isolé",critical:!0},{id:"b",label:"Orienter vers l'équipe traitante (orthopédiste) pour évaluation de cette complication neurologique post-traumatique",correct:!0,critical:!0},{id:"c",label:"Traiter par manipulation du rachis cervical",critical:!0},{id:"d",label:"Prescrire des antalgiques sans réévaluation"}],reveal:"Un déficit neurologique nouveau après un traumatisme récent et une immobilisation nécessite un avis médical/chirurgical rapide, avant toute prise en charge manuelle isolée."}],discriminators:["Déficit purement moteur, sans aucun trouble sensitif : oriente vers le nerf interosseux antérieur, branche uniquement motrice.","Contexte post-traumatique récent (fracture supracondylienne, immobilisation) : cause classique de souffrance du nerf interosseux antérieur.","Incapacité à former le signe « OK » : discriminant clé du syndrome du nerf interosseux antérieur."],redFlags:["Déficit neurologique nouveau après un traumatisme ou une immobilisation récente : nécessite un avis médical/chirurgical, pas une prise en charge ostéopathique isolée."],differential:["Syndrome du rond pronateur (mais implique typiquement des paresthésies, absentes ici).","Atteinte du nerf ulnaire (territoire moteur et sensitif différent, griffe cubitale).","Radiculopathie cervicale C8-T1."],pitfalls:["Conclure à une atteinte sensitive alors que le nerf interosseux antérieur est un rameau purement moteur.","Débuter ou poursuivre un traitement manuel isolé devant un déficit neurologique post-traumatique récent sans avis médical."],reasoning:"Un déficit moteur pur (incapacité à former le signe « OK ») apparu après une fracture supracondylienne du coude oriente vers une atteinte du nerf interosseux antérieur, branche profonde et purement motrice du nerf médian. L'absence de trouble sensitif exclut une atteinte plus proximale du tronc du nerf médian, et le contexte post-traumatique impose une orientation médicale avant toute prise en charge ostéopathique isolée.",relatedIds:["1.6-KN-01","1.6-DX-01"],sources:["NCBI-MEDIANNERVE"]},{id:"CASE-01",ue:"2.5",title:"Lombalgie à drapeaux rouges",neutralTitle:"Lombalgie nouvelle chez un homme de 61 ans",priority:"A",vignette:"Homme 61 ans, lombalgie nouvelle progressive depuis 5 semaines.",objective:"Reconnaître un profil de lombalgie évoquant une cause spécifique et décider de l'orientation plutôt que du traitement.",steps:[{kind:"anamnesis",prompt:"Quelles informations demandes-tu en priorité ?",options:[{id:"a",label:"Évolution, horaire de la douleur et réveils nocturnes",correct:!0,critical:!0},{id:"b",label:"Poids et symptômes généraux récents",correct:!0,critical:!0},{id:"c",label:"Antécédents oncologiques",correct:!0,critical:!0},{id:"d",label:"Uniquement la position antalgique préférée"}],reveal:"Anamnèse : réveils nocturnes fréquents, perte de poids involontaire et antécédent de cancer."},{kind:"exam",prompt:"Que cherches-tu à l'examen ?",options:[{id:"a",label:"Déficit neurologique (force, sensibilité, réflexes)",correct:!0,critical:!0},{id:"b",label:"Douleur osseuse focale et état général",correct:!0,critical:!0},{id:"c",label:"Uniquement la mobilité lombaire"}],reveal:"L'examen ne sert pas à confirmer une « mécanique » : il complète l'évaluation du risque de cause spécifique."},{kind:"decision",prompt:"Quelle priorité ?",options:[{id:"a",label:"Manipulation lombaire",critical:!0},{id:"b",label:"Exercices seuls",critical:!0},{id:"c",label:"Compléter l'évaluation et organiser une investigation médicale appropriée",correct:!0,critical:!0},{id:"d",label:"Imagerie systématique pour tout le monde"}],reveal:"Réponse : C."}],discriminators:["Douleur progressive depuis 5 semaines, sans facteur mécanique déclenchant.","Réveils nocturnes fréquents.","Perte de poids involontaire.","Antécédent oncologique."],redFlags:["Antécédent ou suspicion de cancer.","Perte pondérale inexpliquée.","Douleur inhabituelle et progressive avec contexte systémique."],differential:["Lombalgie non spécifique.","Cause tumorale ou métastatique.","Cause infectieuse.","Fracture de fragilité.","Spondyloarthrite axiale."],pitfalls:["Conclure « lombalgie mécanique » parce que la douleur varie avec le mouvement.","Traiter la région douloureuse avant d'avoir clarifié le risque de cause spécifique.","Croire qu'un red flag isolé suffit : c'est l'accumulation des signaux qui oriente."],reasoning:"Le profil justifie de rechercher une cause spécifique et de ne pas conclure à une lombalgie mécanique non spécifique.",relatedIds:["2.5-RF-01","2.5-RF-02","2.5-RF-19","5.11-KN-01"],sources:["CORPUS-V1","NICE-NG59"]},{id:"CASE-02",ue:"2.5",title:"Queue de cheval",neutralTitle:"Lombosciatalgie bilatérale chez une femme de 44 ans",priority:"A+",vignette:"Femme 44 ans, lombosciatalgie bilatérale.",objective:"Identifier une urgence neurologique dès l'interrogatoire et orienter sans délai.",steps:[{kind:"anamnesis",prompt:"Quelles questions ne peux-tu pas omettre ?",options:[{id:"a",label:"Sensibilité périnéale",correct:!0,critical:!0},{id:"b",label:"Fonctions urinaires et fécales",correct:!0,critical:!0},{id:"c",label:"Préférence de matelas"}],reveal:"Anamnèse : engourdissement périnéal et apparition de difficultés urinaires."},{kind:"decision",prompt:"Quelle est ta conduite ?",options:[{id:"a",label:"Urgence médicale immédiate",correct:!0,critical:!0},{id:"b",label:"Traitement manuel puis réévaluation dans une semaine",critical:!0},{id:"c",label:"Conseils d'exercices et suivi téléphonique",critical:!0}],reveal:"🔴 Urgence médicale immédiate."}],discriminators:["Symptômes bilatéraux.","Engourdissement périnéal (anesthésie en selle).","Difficultés urinaires d'apparition récente."],redFlags:["Anesthésie en selle.","Dysfonction vésico-sphinctérienne nouvelle.","Déficit moteur progressif.","Symptômes bilatéraux sévères selon contexte."],differential:["Radiculopathie lombaire sans compression sévère.","Sténose lombaire.","Autre cause de compression neurologique."],pitfalls:["Ne demander que « avez-vous mal ? » sans interroger explicitement les fonctions urinaires et fécales et la sensibilité périnéale.","Proposer un traitement manuel « en attendant » l'avis médical."],reasoning:"Ne pas retarder l'évaluation par un traitement manuel.",relatedIds:["2.5-RF-03","2.5-RF-07"],sources:["CORPUS-V1"]},{id:"CASE-03",ue:"2.5",title:"Épaule non locale",neutralTitle:"Douleur d'épaule chez un homme de 58 ans, apparue à l'effort",priority:"A+",vignette:"Homme 58 ans, douleur d'épaule gauche apparue à l'effort.",objective:"Ne pas attribuer une douleur d'épaule à l'épaule avant d'avoir écarté une cause non musculo-squelettique.",steps:[{kind:"anamnesis",prompt:"Que recherches-tu autour de cette douleur d'effort ?",options:[{id:"a",label:"Symptômes thoraciques associés",correct:!0,critical:!0},{id:"b",label:"Sueurs, malaise, dyspnée",correct:!0,critical:!0},{id:"c",label:"Uniquement les amplitudes articulaires"}],reveal:"Anamnèse : oppression thoracique et sueurs."},{kind:"decision",prompt:"Quelle est ta conduite ?",options:[{id:"a",label:"Exclure en urgence une cause cardiaque",correct:!0,critical:!0},{id:"b",label:"Tests de coiffe puis traitement de l'épaule",critical:!0},{id:"c",label:"Traitement cervical de première intention",critical:!0}],reveal:"🔴 Cause cardiaque à exclure en urgence selon le tableau clinique."}],discriminators:["Douleur apparue à l'effort.","Oppression thoracique associée.","Sueurs, malaise, dyspnée."],redFlags:["Douleur d'effort accompagnée de symptômes thoraciques.","Malaise, sueurs, dyspnée.","Facteurs de risque cardiovasculaires."],differential:["Cause cardiaque.","Cause thoracique ou respiratoire.","Douleur cervicale ou radiculaire projetée.","Cause locale de l'épaule (coiffe, capsulite, arthrose).","Cause diaphragmatique ou viscérale."],pitfalls:["Enchaîner les tests de coiffe parce que la plainte porte sur « une épaule ».","Se rassurer parce qu'un test orthopédique reproduit la douleur."],reasoning:"Une douleur d'épaule ne prouve pas que l'épaule est la source.",relatedIds:["2.5-RF-09","2.5-RF-20"],sources:["CORPUS-V1"]},{id:"CASE-04",ue:"2.5",title:"Genou chaud",neutralTitle:"Genou aigu rouge et gonflé",priority:"A+",vignette:"Patient avec genou aigu, rouge, chaud, gonflé et très douloureux.",objective:"Reconnaître une monoarthrite aiguë et orienter avant tout traitement local.",steps:[{kind:"exam",prompt:"Quel élément change ton niveau d'alerte ?",options:[{id:"a",label:"Température élevée",correct:!0,critical:!0},{id:"b",label:"Chaleur et gonflement articulaires",correct:!0,critical:!0},{id:"c",label:"Craquement indolore à la flexion"}],reveal:"Examen : température élevée, articulation chaude, gonflée et très douloureuse."},{kind:"decision",prompt:"Quelle est ta conduite ?",options:[{id:"a",label:"Exclure rapidement une arthrite septique",correct:!0,critical:!0},{id:"b",label:"Considérer une poussée d'arthrose et rassurer",critical:!0},{id:"c",label:"Drainage manuel et glace",critical:!0}],reveal:"🔴 Arthrite septique à exclure rapidement."}],discriminators:["Début brutal.","Articulation chaude, gonflée et très douloureuse.","Température élevée et altération de l'état général."],redFlags:["Articulation chaude, gonflée et très douloureuse.","Fièvre ou altération de l'état général."],differential:["Arthrite septique.","Crise microcristalline (goutte, pseudogoutte).","Arthrite inflammatoire.","Traumatisme."],pitfalls:["Présumer d'une simple surcharge ou d'une poussée d'arthrose.","Conclure « goutte » et rassurer : goutte et infection articulaire peuvent se ressembler.","Considérer que l'absence de fièvre exclut une infection."],reasoning:"Goutte, pseudogoutte et arthrite septique peuvent se présenter de façon proche ; l'absence de fièvre n'exclut pas une infection.",relatedIds:["2.5-RF-16","2.5-RF-11"],sources:["CORPUS-V1"]},{id:"CASE-05",ue:"2.5",title:"Lombalgie mécanique probable",neutralTitle:"Lombalgie après jardinage chez un patient de 48 ans",priority:"A",vignette:"48 ans, lombalgie depuis 10 jours après jardinage, pas de fièvre, de cancer, de déficit ni de trouble sphinctérien ; douleur liée au mouvement.",objective:"Conduire une démarche d'exclusion complète, puis assumer une prise en charge conservatrice proportionnée avec réévaluation.",steps:[{kind:"anamnesis",prompt:"Par quoi commences-tu ?",options:[{id:"a",label:"Anamnèse complète puis recherche des red flags",correct:!0},{id:"b",label:"Imagerie lombaire immédiate"},{id:"c",label:"Manipulation d’emblée"}],reveal:"Anamnèse complète → red flags avant toute conclusion mécanique."},{kind:"exam",prompt:"Quel examen ?",options:[{id:"a",label:"Examen musculo-squelettique ± neurologique selon indication",correct:!0},{id:"b",label:"Examen neurologique complet systématique"}],reveal:"Examen MSK ± neurologique selon indication."},{kind:"decision",prompt:"Quelle décision ?",options:[{id:"a",label:"Prise en charge conservatrice adaptée et réévaluation",correct:!0},{id:"b",label:"Imagerie automatique sans indication"},{id:"c",label:"Orientation en urgence"}],reveal:"Hypothèse non spécifique si le tableau est cohérent : pas d’imagerie automatique sans indication, prise en charge conservatrice adaptée et réévaluation."}],discriminators:["Facteur déclenchant mécanique identifié.","Douleur liée au mouvement.","Absence de fièvre, de cancer, de déficit et de trouble sphinctérien."],redFlags:["Aucun red flag retrouvé : c'est le résultat d'une recherche explicite, pas une absence de recherche."],differential:["Lombalgie non spécifique.","Radiculopathie lombaire.","Cause spécifique (fracture, infection, tumeur, inflammatoire) écartée par l'anamnèse."],pitfalls:["Demander une imagerie « pour être sûr », sans question clinique à résoudre.","Sauter la recherche de red flags parce que l'histoire paraît banale.","Omettre la réévaluation."],reasoning:"Anamnèse complète → red flags → examen MSK ± neuro selon indication → hypothèse non spécifique si cohérente → pas d’imagerie automatique sans indication → prise en charge conservatrice adaptée et réévaluation.",relatedIds:["2.5-RF-02","2.5-RF-01","2.5-RF-27","5.11-KN-01"],sources:["UE25-PACK-V2"]},{id:"CASE-06",ue:"2.5",title:"Épaule progressive sans traumatisme",neutralTitle:"Douleur d'épaule progressive chez un patient de 62 ans, sans traumatisme",priority:"A",vignette:"62 ans, douleur d’épaule progressive, limitation active et passive, surtout en rotation externe, sans traumatisme.",objective:"Formuler une hypothèse à partir de la comparaison actif/passif sans la transformer en certitude diagnostique.",steps:[{kind:"exam",prompt:"Que t’apporte la comparaison actif/passif ?",options:[{id:"a",label:"Une limitation active ET passive oriente vers un profil capsulaire",correct:!0},{id:"b",label:"Elle tranche à elle seule le diagnostic"}],reveal:"Profil : douleur puis limitation progressive, limitation active ET passive, restriction marquée de la rotation externe."},{kind:"decision",prompt:"Quelle hypothèse retiens-tu ?",options:[{id:"a",label:"Capsulite possible, sans exclure les autres différentiels",correct:!0},{id:"b",label:"Capsulite certaine"},{id:"c",label:"Tendinopathie de coiffe certaine"}],reveal:"Hypothèse : capsulite possible. Mais intégrer le cervical, l’arthrose, les autres différentiels et le contexte systémique."}],discriminators:["Limitation active ET passive.","Restriction marquée de la rotation externe.","Évolution progressive sans traumatisme."],redFlags:["Rechercher un contexte systémique (fièvre, altération générale, antécédent oncologique) avant de retenir une cause purement locale."],differential:["Capsulite adhésive.","Pathologie de la coiffe ou douleur subacromiale.","Arthrose gléno-humérale.","Douleur cervicale ou radiculaire projetée.","Contexte systémique."],pitfalls:["Transformer une classification clinique en diagnostic certain.","Oublier que les tableaux réels se chevauchent."],reasoning:"Capsulite possible au vu du profil capsulaire, sans transformer une classification clinique en diagnostic certain : intégrer cervical, arthrose, autres différentiels et contexte systémique.",relatedIds:["2.5-RF-10","2.5-RF-09"],sources:["UE25-PACK-V2"]},{id:"CASE-07",ue:"2.4",title:"Céphalée brutale",neutralTitle:"Céphalée brutale chez une femme de 39 ans",priority:"A+",vignette:"Femme 39 ans, céphalée apparue brutalement il y a 30 minutes, décrite comme la pire de sa vie, atteignant son intensité maximale en quelques secondes.",objective:"Reconnaître une céphalée à risque secondaire grave et orienter sans délai plutôt que d'engager une prise en charge ostéopathique.",steps:[{kind:"anamnesis",prompt:"Quelles informations recherches-tu en priorité ?",options:[{id:"a",label:"Mode d'installation exact et rapidité d'apparition",correct:!0,critical:!0},{id:"b",label:"Antécédents de céphalées similaires et facteurs déclenchants habituels",correct:!0},{id:"c",label:"Signes associés : raideur de nuque, trouble de conscience, déficit neurologique",correct:!0,critical:!0},{id:"d",label:"Uniquement l'intensité sur une échelle de douleur"}],reveal:"Céphalée totalement inhabituelle, maximale en moins d'une minute, sans antécédent similaire ; pas de fièvre ni de déficit rapporté par la patiente."},{kind:"exam",prompt:"Que cherches-tu à l'examen ?",options:[{id:"a",label:"Signes neurologiques focaux, état de conscience, raideur de nuque",correct:!0,critical:!0},{id:"b",label:"Uniquement la mobilité cervicale"},{id:"c",label:"Signes vitaux et recherche de fièvre",correct:!0}],reveal:"Examen neurologique et signes vitaux normaux à ce stade ; cela ne suffit pas à exclure une cause vasculaire grave après un début en coup de tonnerre."},{kind:"decision",prompt:"Quelle est la priorité ?",options:[{id:"a",label:"Traitement manuel cervical pour soulager la céphalée",critical:!0},{id:"b",label:"Orientation médicale en urgence pour exclure une cause secondaire grave",correct:!0,critical:!0},{id:"c",label:"Antalgique simple et réévaluation dans une semaine",critical:!0},{id:"d",label:"Rassurer car l'examen neurologique est normal",critical:!0}],reveal:"Réponse : B. Une céphalée en coup de tonnerre impose une orientation urgente indépendamment d'un examen initial normal."}],discriminators:["Début brutal, intensité maximale en quelques secondes.","Absence d'antécédent de céphalée similaire.","Caractère inhabituel signalé explicitement par la patiente."],redFlags:["Céphalée en coup de tonnerre.","Céphalée décrite comme la pire jamais ressentie."],differential:["Hémorragie sous-arachnoïdienne ou autre cause vasculaire.","Céphalée primaire (migraine, tension, cluster).","Céphalée secondaire à une autre cause (infectieuse, hypertensive)."],pitfalls:["Se rassurer sur un examen neurologique initial normal.","Traiter la céphalée comme cervicogène sans avoir écarté un « coup de tonnerre »."],reasoning:"Une céphalée brutale atteignant son intensité maximale en quelques secondes est un signe d'alerte majeur qui impose d'exclure une cause secondaire grave avant toute autre prise en charge, même si l'examen initial est rassurant.",relatedIds:["2.4-RF-01","2.5-RF-08"],sources:["NICE-CG150"]},{id:"CASE-09",ue:"1.6",title:"Sciatalgie avec déficit moteur : localiser le niveau radiculaire",neutralTitle:"Sciatalgie avec difficulté à se mettre sur la pointe des pieds chez un homme de 52 ans",priority:"A",vignette:"Homme 52 ans, lombalgie depuis 3 semaines irradiant en éclair dans la face postérieure de la cuisse et de la jambe jusqu'au bord latéral du pied. Depuis 2 jours, il rapporte une difficulté à se mettre sur la pointe des pieds du côté douloureux.",objective:"Localiser cliniquement le niveau radiculaire probable et décider de la conduite à tenir face à un déficit moteur associé à une radiculopathie.",steps:[{kind:"anamnesis",prompt:"Quels éléments anamnestiques recherches-tu en priorité pour évaluer la gravité ?",options:[{id:"a",label:"Troubles sphinctériens (rétention urinaire, incontinence) ou anesthésie en selle",correct:!0,critical:!0},{id:"b",label:"Douleur bilatérale et progressive touchant les deux membres inférieurs",correct:!0,critical:!0},{id:"c",label:"Couleur des vêtements portés lors de l'apparition de la douleur",correct:!1}],reveal:"Absence de trouble sphinctérien, d'anesthésie en selle et de bilatéralité : pas d'argument pour un syndrome de la queue de cheval à ce stade."},{kind:"exam",prompt:"Quel test complète utilement l'examen neurologique du membre inférieur ici ?",options:[{id:"a",label:"Réflexe achilléen et force de flexion plantaire (mise sur pointe de pied), comparés au côté sain",correct:!0,critical:!0},{id:"b",label:"Manœuvre de Lasègue (SLR)",correct:!0,critical:!0},{id:"c",label:"Palpation abdominale profonde",correct:!1}],reveal:"Réflexe achilléen diminué à droite, force de flexion plantaire cotée à 4/5 à droite, Lasègue positif à 40° à droite."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée à cette étape ?",options:[{id:"a",label:"Orienter pour avis médical devant un déficit moteur radiculaire objectivé",correct:!0,critical:!0},{id:"b",label:"Traiter uniquement par manipulation, sans réévaluation ni orientation"},{id:"c",label:"Rassurer et revoir dans un mois sans réévaluation"}],reveal:"Un déficit moteur objectif (réflexe diminué, force à 4/5, Lasègue positif) associé à une radiculopathie évolutive justifie un avis médical pour bilan et décision de prise en charge, au-delà d'une simple prise en charge symptomatique."}],discriminators:["Présence d'un déficit moteur objectif (force à 4/5, réflexe diminué) au-delà de la seule douleur","Absence de signe sphinctérien excluant une urgence chirurgicale immédiate, sans exclure la nécessité d'un bilan"],redFlags:["Trouble sphinctérien ou anesthésie en selle évoquant un syndrome de la queue de cheval","Déficit moteur progressif ou sévère"],differential:["Radiculopathie S1 par hernie discale","Sténose spinale lombaire","Syndrome de la queue de cheval, à exclure en priorité"],pitfalls:["Se limiter à la douleur sans quantifier objectivement la force et les réflexes","Traiter uniquement en manipulation un déficit moteur radiculaire sans orientation médicale"],reasoning:"Le niveau S1 est évoqué par l'association réflexe achilléen diminué, faiblesse de flexion plantaire et trajet douloureux postérieur jusqu'au bord latéral du pied. La présence d'un déficit moteur objectif, même modéré, distingue une radiculopathie nécessitant un avis médical d'une simple lombosciatalgie sans déficit, justifiant l'orientation plutôt qu'une prise en charge isolée.",relatedIds:["1.6-EX-01","1.6-DX-02"],sources:["NCBI-LUMBOSACRAL-RADIC"]},{id:"CASE-10",ue:"2.7",title:"Douleur en fosse iliaque droite : reconnaître une urgence chirurgicale",neutralTitle:"Douleur en fosse iliaque droite chez une femme de 24 ans",priority:"A+",vignette:"Femme 24 ans, douleur abdominale débutée la veille autour de l'ombilic, migrée depuis quelques heures en fosse iliaque droite, avec nausées et fièvre à 38,2 °C. La douleur augmente à la marche.",objective:"Reconnaître les signes évocateurs d'une urgence chirurgicale abdominale et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité pour évaluer la gravité ?",options:[{id:"a",label:"Migration de la douleur, fièvre, anorexie, nausées",correct:!0,critical:!0},{id:"b",label:"Dernières règles et possibilité de grossesse",correct:!0,critical:!0},{id:"c",label:"Type de chaussures portées habituellement",correct:!1}],reveal:"Douleur migrée de la région péri-ombilicale vers la fosse iliaque droite en quelques heures, fièvre à 38,2 °C, anorexie ; dernières règles normales, test de grossesse non fait."},{kind:"exam",prompt:"Quels signes recherches-tu à l'examen abdominal ?",options:[{id:"a",label:"Douleur et défense au point de McBurney",correct:!0,critical:!0},{id:"b",label:"Signe de Blumberg (douleur au relâchement)",correct:!0,critical:!0},{id:"c",label:"Réflexe cutané abdominal bilatéral symétrique",correct:!1}],reveal:"Douleur vive et défense au point de McBurney, signe de Blumberg positif, bruits intestinaux diminués."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vers un service médico-chirurgical pour suspicion d'appendicite",correct:!0,critical:!0},{id:"b",label:"Traiter par des techniques ostéopathiques viscérales avant réévaluation"},{id:"c",label:"Prescrire un antalgique et revoir en fin de semaine"}],reveal:"Le tableau (migration douloureuse, fièvre, défense et Blumberg positif au point de McBurney) est fortement évocateur d'une appendicite aiguë : une orientation médico-chirurgicale en urgence est nécessaire, sans prise en charge symptomatique isolée."}],discriminators:["Migration typique de la douleur péri-ombilicale vers la fosse iliaque droite en quelques heures","Association fièvre, défense et signe de Blumberg positif au point de McBurney"],redFlags:["Défense et signe de Blumberg positifs évocateurs de péritonisme","Fièvre associée à une douleur abdominale localisée et progressive"],differential:["Appendicite aiguë","Grossesse extra-utérine, à exclure systématiquement chez la femme en âge de procréer","Kyste ovarien compliqué","Gastro-entérite aiguë, sans signe de péritonisme"],pitfalls:["Omettre de rechercher une grossesse chez une femme en âge de procréer présentant une douleur en fosse iliaque","Attribuer la douleur à une origine musculo-squelettique sans avoir recherché de signe de péritonisme"],reasoning:"La migration caractéristique de la douleur, la fièvre, la défense et le signe de Blumberg positif au point de McBurney forment un tableau fortement évocateur d'une appendicite aiguë, une urgence chirurgicale. Chez une femme en âge de procréer, une grossesse extra-utérine doit systématiquement être exclue avant toute autre hypothèse. Ces éléments imposent une orientation médico-chirurgicale immédiate plutôt qu'une prise en charge symptomatique.",relatedIds:["2.7-RF-01","2.7-EX-01"],sources:["NCBI-ACUTE-ABDOMEN","NCBI-ABDOMINAL-EXAM"]},{id:"CASE-11",ue:"1.7",title:"Faiblesse progressive des ceintures : myogène ou neurogène ?",neutralTitle:"Faiblesse progressive des ceintures chez une femme de 45 ans",priority:"A",vignette:"Femme 45 ans consulte pour une faiblesse progressive depuis 3 mois pour monter les escaliers et lever les bras au-dessus de la tête, sans douleur ni trouble sensitif. Pas de fasciculation visible.",objective:"Distinguer cliniquement une faiblesse d'origine myogène d'une origine neurogène et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu pour orienter le mécanisme de la faiblesse ?",options:[{id:"a",label:"Distribution de la faiblesse (proximale vs distale) et son évolution",correct:!0,critical:!0},{id:"b",label:"Présence de fasciculations ou de crampes",correct:!0,critical:!0},{id:"c",label:"Couleur des aliments consommés récemment",correct:!1}],reveal:"Faiblesse proximale et symétrique (ceintures scapulaire et pelvienne), progressive sur 3 mois, sans fasciculation ni crampe rapportée."},{kind:"exam",prompt:"Quels éléments d'examen complètent utilement le tableau ?",options:[{id:"a",label:"Cotation MRC de la force proximale et distale, comparée des deux côtés",correct:!0,critical:!0},{id:"b",label:"Réflexes ostéotendineux (bicipital, rotulien)",correct:!0,critical:!0},{id:"c",label:"Palpation abdominale profonde",correct:!1}],reveal:"Force cotée à 4/5 en proximal (deltoïdes, quadriceps), 5/5 en distal ; réflexes ostéotendineux présents et symétriques."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter pour un bilan biologique (CK) et un avis médical devant une faiblesse proximale progressive évocatrice d'une atteinte myogène",correct:!0,critical:!0},{id:"b",label:"Prise en charge ostéopathique isolée sans bilan, en expliquant la faiblesse par un déconditionnement"},{id:"c",label:"Rassurer sans réévaluation programmée"}],reveal:"Une faiblesse proximale symétrique et progressive, avec réflexes préservés et sans trouble sensitif, est évocatrice d'une atteinte myogène : un bilan (CK) et un avis médical sont nécessaires avant toute autre décision."}],discriminators:["Distribution proximale et symétrique de la faiblesse, sans trouble sensitif","Réflexes ostéotendineux préservés malgré la faiblesse motrice"],redFlags:["Faiblesse motrice progressive sur plusieurs mois sans stabilisation"],differential:["Myopathie (atteinte myogène)","Atteinte neurogène périphérique, à écarter par l'absence de fasciculation et la préservation des réflexes","Déconditionnement physique simple : diagnostic d'élimination, jamais de première intention devant une faiblesse progressive symétrique"],pitfalls:["Attribuer d'emblée une faiblesse progressive à un déconditionnement sans bilan complémentaire"],reasoning:"La distribution proximale et symétrique de la faiblesse, l'absence de trouble sensitif et de fasciculation et la préservation des réflexes orientent vers une atteinte myogène plutôt que neurogène. Ce tableau impose un bilan biologique (CK) et un avis médical avant toute prise en charge isolée, car une myopathie progressive non investiguée peut évoluer.",relatedIds:["1.7-DX-01","1.7-EX-01"],sources:["NCBI-MYOPATHY","NCBI-MRC-SCALE"]},{id:"CASE-12",ue:"2.6",title:"Douleur thoracique et dyspnée à l'effort : ne pas manquer l'urgence cardiovasculaire",neutralTitle:"Douleur thoracique à l'effort chez un homme de 58 ans",priority:"A+",vignette:"Homme 58 ans, hypertendu et fumeur, consulte pour une douleur thoracique oppressive apparue à l'effort il y a 30 minutes, irradiant vers le bras gauche, associée à des sueurs et une dyspnée. La douleur persiste au repos depuis son arrivée.",objective:"Reconnaître un tableau évocateur de syndrome coronarien aigu et décider de la conduite appropriée sans délai.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité ?",options:[{id:"a",label:"Facteurs de risque cardiovasculaire et antécédents cardiaques",correct:!0,critical:!0},{id:"b",label:"Caractère de la douleur (oppressive, irradiation, facteurs déclenchants ou soulageants) et symptômes associés (sueurs, nausées, dyspnée)",correct:!0,critical:!0},{id:"c",label:"Type d'activité professionnelle exercée",correct:!1}],reveal:"Hypertension artérielle connue, tabagisme actif, pas d'antécédent cardiaque connu ; douleur oppressive persistante depuis 30 minutes malgré le repos, sueurs profuses, dyspnée associée."},{kind:"exam",prompt:"Quels éléments d'examen recherches-tu, en plus des paramètres vitaux ?",options:[{id:"a",label:"Fréquence cardiaque, tension artérielle, saturation en oxygène, fréquence respiratoire",correct:!0,critical:!0},{id:"b",label:"Reproductibilité de la douleur à la palpation ou à la mobilisation thoracique",correct:!0,critical:!0},{id:"c",label:"Amplitude de flexion lombaire",correct:!1}],reveal:"Douleur non reproduite ni modifiée par la palpation ou la mobilisation ; tension artérielle 152/94, fréquence cardiaque 102/min, SpO2 94 %, sueurs visibles."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Orienter en urgence immédiate (appel des secours), sans traitement ostéopathique",correct:!0,critical:!0},{id:"b",label:"Traiter la douleur thoracique par des techniques ostéopathiques ciblées sur le rachis dorsal"},{id:"c",label:"Rassurer en expliquant qu'une douleur non reproduite à la palpation exclut une cause cardiaque"}],reveal:"Douleur oppressive persistante avec irradiation, sueurs, dyspnée et facteurs de risque cardiovasculaire chez un patient non soulagé au repos : ce tableau impose une orientation en urgence immédiate, sans attendre ni traiter localement."}],discriminators:["Douleur oppressive persistante, non modifiée par la palpation ou la mobilisation, chez un patient à risque cardiovasculaire","Dyspnée et sueurs associées à la douleur thoracique"],redFlags:["Douleur thoracique oppressive avec irradiation, sueurs, dyspnée, non soulagée au repos","Facteurs de risque cardiovasculaire majeurs (tabac, hypertension)"],differential:["Syndrome coronarien aigu","Douleur pariétale musculo-squelettique, exclue ici par l'absence de reproductibilité à la palpation","Embolie pulmonaire : dyspnée associée, à garder en tête"],pitfalls:["Croire qu'une douleur thoracique non reproduite à la palpation exclut une cause cardiaque, alors qu'une douleur reproductible n'exclut pas non plus totalement une cause cardiaque"],reasoning:"La combinaison douleur oppressive persistante, irradiation, sueurs, dyspnée et facteurs de risque cardiovasculaire chez un patient non soulagé au repos constitue un tableau à haut risque de syndrome coronarien aigu. Aucune manœuvre clinique ne permet d'exclure cette hypothèse en cabinet : l'orientation en urgence immédiate prime sur toute autre prise en charge.",relatedIds:["2.6-RF-01","2.6-RF-02"],sources:["NICE-CG95","NCBI-DYSPNEA"]},{id:"CASE-13",ue:"1.8",title:"Dyspnée d'effort avec galop B3 : reconnaître une décompensation cardiaque",neutralTitle:"Essoufflement progressif à l'effort chez un homme de 74 ans",priority:"A",vignette:"Homme 74 ans, essoufflement progressif à l'effort depuis trois semaines, orthopnée sur deux oreillers, œdèmes des chevilles et prise de poids de 3 kg en une semaine.",objective:"Reconnaître à l'auscultation et à l'examen les signes d'une décompensation cardiaque et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Orthopnée, dyspnée paroxystique nocturne, prise de poids récente",correct:!0,critical:!0},{id:"b",label:"Habitudes alimentaires et tolérance au lactose",correct:!1},{id:"c",label:"Nombre d'oreillers nécessaires pour dormir et toux en décubitus",correct:!0,critical:!0}],reveal:"Orthopnée sur deux oreillers, toux en position allongée, prise de poids de 3 kg en une semaine par rétention hydrique ; pas de dyspnée paroxystique nocturne rapportée à ce stade."},{kind:"exam",prompt:"Quels signes recherches-tu à l'auscultation et à l'examen ?",options:[{id:"a",label:"Galop B3 au foyer mitral, en décubitus latéral gauche avec le pavillon en cloche",correct:!0,critical:!0},{id:"b",label:"Turgescence jugulaire et crépitants bibasaux",correct:!0,critical:!0},{id:"c",label:"Souffle systolique doux, banal et sans irradiation",correct:!1}],reveal:"Galop B3 perçu au foyer mitral en décubitus latéral gauche, turgescence jugulaire, crépitants bibasaux aux bases et œdèmes des chevilles prenant le godet."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vers une évaluation médicale pour suspicion de décompensation cardiaque",correct:!0,critical:!0},{id:"b",label:"Rassurer et revoir dans un mois pour surveiller l'évolution des œdèmes"},{id:"c",label:"Débuter des techniques ostéopathiques de drainage avant réévaluation"}],reveal:"Le galop B3 est le signe le plus précoce et le plus significatif de décompensation cardiaque ; associé à la turgescence jugulaire et aux crépitants, il impose une orientation médicale urgente plutôt qu'une prise en charge symptomatique ou manuelle."}],discriminators:["Galop B3 : signe précoce et significatif de surcharge volémique ventriculaire, à rechercher au pavillon en cloche du stéthoscope, patient en décubitus latéral gauche.","Association orthopnée, prise de poids rapide, turgescence jugulaire et crépitants bibasaux."],redFlags:["Galop B3 associé à une turgescence jugulaire et des crépitants bibasaux.","Prise de poids rapide (plusieurs kilogrammes en une semaine) par rétention hydrosodée."],differential:["Décompensation cardiaque","Exacerbation de bronchopneumopathie chronique obstructive","Pneumonie","Embolie pulmonaire"],pitfalls:["Attribuer la dyspnée d'effort à un simple déconditionnement sans réaliser d'auscultation cardiaque ciblée.","Manquer le galop B3, son intensité étant faible et basse fréquence : nécessite le pavillon en cloche et un patient en décubitus latéral gauche."],reasoning:"L'association d'une orthopnée, d'une prise de poids rapide, d'un galop B3, d'une turgescence jugulaire et de crépitants bibasaux forme un tableau évocateur d'une décompensation cardiaque. Le galop B3 est décrit comme le signe le plus précoce et le plus significatif de ce tableau : sa présence impose une orientation médicale urgente plutôt qu'une prise en charge symptomatique isolée.",relatedIds:["1.8-KN-01","1.8-EX-01","1.8-KN-02","2.6-DX-04"],sources:["NCBI-HEART-SOUNDS","NCBI-HF"]},{id:"CASE-14",ue:"2.8",title:"Douleur de flanc chez un patient âgé : ne pas manquer un anévrisme de l'aorte rompu",neutralTitle:"Douleur brutale du flanc chez un homme de 68 ans",priority:"A+",vignette:"Homme 68 ans, tabagique et hypertendu, douleur brutale du flanc gauche irradiant dans le dos depuis une heure, associée à un malaise ; tension artérielle 92/58 mmHg, pouls 112/min.",objective:"Distinguer une présentation d'anévrisme de l'aorte abdominale rompu d'une colique néphrétique et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Terrain vasculaire : âge, sexe masculin, tabagisme, hypertension artérielle",correct:!0,critical:!0},{id:"b",label:"Antécédent de lithiase urinaire connue",correct:!1},{id:"c",label:"Malaise ou sensation de tête vide associée à la douleur",correct:!0,critical:!0}],reveal:"Homme de 68 ans, tabagique de longue date, hypertendu ; pas d'antécédent de lithiase urinaire ; malaise associé à la douleur, sans perte de connaissance franche."},{kind:"exam",prompt:"Quels signes recherches-tu à l'examen ?",options:[{id:"a",label:"Masse abdominale pulsatile et signes d'instabilité hémodynamique",correct:!0,critical:!0},{id:"b",label:"Sensibilité costo-vertébrale isolée, sans autre anomalie",correct:!1},{id:"c",label:"Tension artérielle, fréquence cardiaque et recherche de pâleur",correct:!0,critical:!0}],reveal:"Masse abdominale pulsatile mal définie, tension artérielle à 92/58 mmHg, pouls à 112/min, pâleur cutanéo-muqueuse ; pas de sensibilité costo-vertébrale franche."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vitale vers un service médico-chirurgical pour suspicion d'anévrisme de l'aorte rompu",correct:!0,critical:!0},{id:"b",label:"Traiter comme une colique néphrétique simple avec un antalgique et un bilan urologique programmé"},{id:"c",label:"Réaliser des techniques ostéopathiques viscérales avant réévaluation"}],reveal:"Le terrain vasculaire, la masse pulsatile et l'instabilité hémodynamique (hypotension, tachycardie, pâleur) sont fortement évocateurs d'un anévrisme de l'aorte abdominale rompu ou fissuré, une urgence vitale imposant une orientation immédiate, sans prise en charge symptomatique isolée."}],discriminators:["Terrain vasculaire (âge supérieur à 60 ans, sexe masculin, tabagisme, hypertension) plutôt qu'un antécédent lithiasique.","Masse abdominale pulsatile et instabilité hémodynamique, absentes dans une colique néphrétique non compliquée."],redFlags:["Instabilité hémodynamique (hypotension, tachycardie, pâleur, malaise) associée à une douleur de flanc.","Masse abdominale pulsatile, même mal définie ou peu sensible."],differential:["Anévrisme de l'aorte abdominale rompu ou fissuré","Colique néphrétique","Pyélonéphrite","Ischémie mésentérique"],pitfalls:["Attribuer systématiquement une douleur de flanc chez la personne âgée à une colique néphrétique sans évaluer le terrain vasculaire et l'état hémodynamique.","Se rassurer sur l'absence de masse pulsatile franche : la présentation peut rester discrète avant la décompensation hémodynamique."],reasoning:"Chez un homme de plus de 60 ans au profil vasculaire à risque, une douleur de flanc brutale associée à une instabilité hémodynamique et une masse pulsatile impose d'exclure en priorité un anévrisme de l'aorte abdominale rompu, dont plus de la moitié des patients ne survivent pas jusqu'à l'arrivée aux urgences ; ce diagnostic prime sur la colique néphrétique tant qu'il n'est pas écarté.",relatedIds:["2.8-RF-02","2.8-RF-03"],sources:["NCBI-RENAL-COLIC","NCBI-AAA"]},{id:"CASE-15",ue:"2.4",title:"Vertige aigu avec ataxie : ne pas manquer un AVC de la fosse postérieure",neutralTitle:"Vertige rotatoire brutal chez une femme de 58 ans",priority:"A",vignette:"Femme 58 ans, hypertendue, vertige rotatoire brutal et continu depuis deux heures, sans déclenchement par les changements de position, avec une sensation d'instabilité marquée à la marche et un épisode bref de vision double.",objective:"Distinguer un vertige d'origine centrale d'un vertige positionnel bénin et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Caractère continu ou déclenché par la position, et durée de l'épisode",correct:!0,critical:!0},{id:"b",label:"Horaire du dernier repas",correct:!1},{id:"c",label:"Facteurs de risque vasculaire et symptômes neurologiques associés (diplopie, dysarthrie)",correct:!0,critical:!0}],reveal:"Vertige continu depuis deux heures, non déclenché par les changements de position, hypertension artérielle connue, épisode bref de diplopie associé."},{kind:"exam",prompt:"Quels signes recherches-tu à l'examen ?",options:[{id:"a",label:"Capacité à tenir debout et à marcher sans aide",correct:!0,critical:!0},{id:"b",label:"Nystagmus horizontal fatigable typique en decubitus latéral, reproduit par le test de provocation positionnelle",correct:!1},{id:"c",label:"Dysarthrie, ataxie des membres ou autre signe neurologique focal",correct:!0,critical:!0}],reveal:"La patiente ne tient pas debout sans appui, marche élargie et instable ; pas de nystagmus positionnel fatigable reproductible ; discrète dysarthrie retrouvée à l'examen."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vers une filière neurovasculaire pour suspicion d'AVC de la fosse postérieure",correct:!0,critical:!0},{id:"b",label:"Rassurer en évoquant un vertige positionnel paroxystique bénin et proposer des manœuvres de repositionnement"},{id:"c",label:"Réaliser une manipulation cervicale pour soulager le vertige avant réévaluation"}],reveal:"Un vertige continu et non positionnel, associé à une ataxie marquée et à des signes neurologiques focaux (dysarthrie, diplopie) chez une patiente à risque vasculaire, impose d'exclure en urgence une cause centrale plutôt que d'évoquer d'emblée une cause périphérique bénigne."}],discriminators:["Caractère continu et non positionnel du vertige, à l'inverse des épisodes brefs déclenchés par le mouvement du VPPB.","Ataxie marquée à la marche et signes neurologiques focaux associés (dysarthrie, diplopie)."],redFlags:["Incapacité à tenir debout sans aide.","Signes neurologiques focaux associés : dysarthrie, diplopie, faiblesse.","Facteurs de risque vasculaire chez un patient présentant un vertige aigu."],differential:["AVC ou AIT de la fosse postérieure","Vertige positionnel paroxystique bénin","Névrite vestibulaire","Migraine vestibulaire"],pitfalls:["Se rassurer parce que la patiente reste consciente et cohérente : un tableau central peut coexister avec un état de conscience normal.","Réaliser une manipulation cervicale avant d'avoir exclu une cause centrale devant un vertige aigu à risque."],reasoning:"Le caractère continu et non positionnel du vertige, associé à une ataxie marquée et à des signes neurologiques focaux chez une patiente au profil vasculaire à risque, forme un tableau évocateur d'un accident vasculaire de la fosse postérieure. Ce diagnostic doit être exclu en urgence avant d'envisager une cause périphérique bénigne ou tout geste manuel.",relatedIds:["2.4-RF-01","2.4-RF-02","2.9-EX-02","2.9-DX-03","2.9-KN-02"],sources:["GRACE3-DIZZ"]},{id:"CASE-16",ue:"2.15",title:"Lombalgie avec antécédent oncologique : ne pas manquer une métastase vertébrale",neutralTitle:"Douleur dorsale progressive chez un homme de 67 ans aux antécédents de cancer",priority:"A",vignette:"Homme 67 ans, antécédent de cancer de la prostate traité il y a cinq ans, douleur dorsale progressive depuis deux mois, réveils nocturnes fréquents non soulagés par le repos, perte de poids de 4 kg non expliquée.",objective:"Reconnaître les signes d'alerte oncologiques devant une lombalgie et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Antécédent de cancer, perte de poids involontaire, douleur nocturne non soulagée par le repos",correct:!0,critical:!0},{id:"b",label:"Notion de traumatisme mineur récent du dos",correct:!1},{id:"c",label:"Symptômes neurologiques associés : faiblesse des membres inférieurs, troubles sphinctériens",correct:!0,critical:!0}],reveal:"Antécédent de cancer de la prostate, perte de poids de 4 kg non expliquée, douleur nocturne non soulagée par le repos ; pas de traumatisme rapporté ; pas de trouble sphinctérien à ce stade, mais une gêne à la marche est signalée."},{kind:"exam",prompt:"Quels signes recherches-tu à l'examen ?",options:[{id:"a",label:"Déficit neurologique focal des membres inférieurs et niveau sensitif",correct:!0,critical:!0},{id:"b",label:"Sensibilité localisée à la palpation d'un niveau vertébral précis",correct:!0,critical:!0},{id:"c",label:"Simple limitation de la flexion lombaire, sans autre anomalie",correct:!1}],reveal:"Discrète faiblesse du releveur du pied gauche, sensibilité localisée à la palpation d'une vertèbre dorsale basse ; pas de niveau sensitif net ni de trouble sphinctérien franc à ce stade."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vers une évaluation médicale pour suspicion de métastase vertébrale avec atteinte neurologique débutante",correct:!0,critical:!0},{id:"b",label:"Traiter comme une lombalgie mécanique commune avec maintien de l'activité et réévaluation à quatre semaines"},{id:"c",label:"Débuter un traitement ostéopathique et revoir l'évolution avant tout avis médical"}],reveal:"L'antécédent de cancer, la perte de poids, la douleur nocturne non soulagée par le repos et le déficit neurologique débutant sont des signes d'alerte imposant d'exclure en urgence une métastase vertébrale avec possible compression médullaire, à l'inverse d'une lombalgie mécanique commune qui s'améliore avec le maintien de l'activité."}],discriminators:["Antécédent de cancer et douleur nocturne non soulagée par le repos, à l'inverse d'une lombalgie mécanique qui s'améliore typiquement avec le mouvement.","Apparition d'un déficit neurologique focal, même discret, chez un patient aux antécédents oncologiques."],redFlags:["Antécédent de cancer associé à une douleur rachidienne nouvelle ou progressive.","Perte de poids involontaire et douleur nocturne non soulagée par le repos.","Déficit neurologique focal, même discret, ou trouble sphinctérien débutant."],differential:["Métastase vertébrale avec compression médullaire débutante","Tassement vertébral ostéoporotique","Lombalgie mécanique commune","Spondylodiscite infectieuse"],pitfalls:["Traiter d'emblée comme une lombalgie mécanique commune sans interroger sur l'antécédent oncologique.","Attendre l'apparition d'un déficit neurologique franc ou d'un trouble sphinctérien avant d'orienter, alors qu'un déficit discret est déjà un signe d'alerte suffisant."],reasoning:"L'association d'un antécédent de cancer, d'une perte de poids involontaire, d'une douleur nocturne non soulagée par le repos et d'un déficit neurologique débutant impose d'exclure en urgence une métastase vertébrale avec possible compression médullaire, à distinguer d'une lombalgie mécanique commune dont l'évolution attendue est l'amélioration avec le maintien de l'activité.",relatedIds:["2.15-RF-01","2.15-RF-02"],sources:["NICE-NG12","NICE-NG59"]},{id:"CASE-17",ue:"2.10",title:"Fièvre avec purpura ne s'effaçant pas au verre : ne pas manquer une méningococcémie",neutralTitle:"Fièvre et taches cutanées chez un homme de 22 ans",priority:"A+",vignette:"Homme 22 ans, fièvre à 39,5 °C depuis quelques heures, céphalée intense, quelques taches purpuriques sur les jambes ne s'effaçant pas à la pression d'un verre, discrète raideur de nuque.",objective:"Reconnaître les signes d'un purpura fébrile évocateur d'une infection méningococcique et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Association fièvre, céphalée et raideur de nuque",correct:!0,critical:!0},{id:"b",label:"Notion de voyage récent en zone tropicale",correct:!1},{id:"c",label:"Rapidité d'apparition et d'extension des taches cutanées",correct:!0,critical:!0}],reveal:"Fièvre depuis quelques heures, céphalée intense, raideur de nuque discrète mais présente ; les taches sont apparues il y a moins d'une heure et semblent s'étendre."},{kind:"exam",prompt:"Quels éléments recherches-tu à l'examen cutané ?",options:[{id:"a",label:"Test de la vitropression sur les lésions cutanées",correct:!0,critical:!0},{id:"b",label:"Recherche de pétéchies aux conjonctives, paumes et plantes",correct:!0,critical:!0},{id:"c",label:"Palpation abdominale approfondie en priorité",correct:!1}],reveal:"Les lésions ne s'effacent pas à la vitropression ; quelques pétéchies supplémentaires sont retrouvées aux conjonctives et aux paumes."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vitale vers une structure hospitalière pour suspicion de méningococcémie",correct:!0,critical:!0},{id:"b",label:"Surveiller à domicile 24 heures avec un antipyrétique"},{id:"c",label:"Attendre un résultat biologique avant toute orientation"}],reveal:"Un purpura non blanchissant à la vitropression, associé à une fièvre, une céphalée et une raideur de nuque, impose une orientation hospitalière en urgence vitale pour suspicion de méningococcémie, sans attendre de confirmation biologique."}],discriminators:["Purpura non blanchissant à la vitropression, avec des lésions de plus de 2 mm, associé à une fièvre.","Extension rapide de l'éruption en quelques heures.","Association à des signes méningés (céphalée, raideur de nuque)."],redFlags:["Purpura ne s'effaçant pas à la vitropression.","Extension rapide de l'éruption cutanée.","Association fièvre, céphalée, raideur de nuque et altération de la conscience."],differential:["Méningococcémie","Méningite bactérienne sans purpura","Purpura d'autre origine (vascularite, thrombopénie), habituellement non fébrile","Réaction allergique cutanée"],pitfalls:["Attendre un résultat biologique avant d'orienter en urgence, alors que la clinique suffit à motiver la décision.","Sous-estimer quelques lésions punctiformes isolées sans réaliser le test de la vitropression."],reasoning:"L'association d'un purpura non blanchissant à la vitropression, d'une extension rapide, d'une fièvre et de signes méningés impose une orientation hospitalière immédiate pour suspicion de méningococcémie : cette urgence infectieuse potentiellement fatale ne doit jamais être écartée sur la seule absence d'éruption franche ni attendre une confirmation biologique.",relatedIds:["2.10-RF-01","1.2-KN-09"],sources:["NICE-NG240"]},{id:"CASE-18",ue:"2.6",title:"Dyspnée brutale avec douleur pleurale : ne pas manquer une embolie pulmonaire",neutralTitle:"Dyspnée brutale avec douleur thoracique chez une femme de 45 ans, opérée récemment",priority:"A+",vignette:"Femme 45 ans, opérée d'une prothèse de hanche il y a dix jours, dyspnée d'apparition brutale depuis deux heures avec douleur thoracique augmentée à l'inspiration profonde, mollet gauche discrètement tuméfié et sensible.",objective:"Reconnaître un tableau évocateur d'embolie pulmonaire et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Chirurgie ou immobilisation récente, antécédent de thrombose veineuse",correct:!0,critical:!0},{id:"b",label:"Caractère brutal de la dyspnée et douleur augmentée à l'inspiration profonde",correct:!0,critical:!0},{id:"c",label:"Consommation récente de produits laitiers",correct:!1}],reveal:"Chirurgie orthopédique il y a dix jours, pas d'antécédent thrombotique connu ; dyspnée brutale depuis deux heures, douleur pleurale augmentée à l'inspiration profonde."},{kind:"exam",prompt:"Quels éléments recherches-tu à l'examen ?",options:[{id:"a",label:"Fréquence cardiaque, fréquence respiratoire, saturation en oxygène",correct:!0,critical:!0},{id:"b",label:"Tuméfaction, rougeur ou sensibilité unilatérale du mollet",correct:!0,critical:!0},{id:"c",label:"Amplitude de rotation externe de hanche opérée",correct:!1}],reveal:"Fréquence cardiaque 118/min, fréquence respiratoire 26/min, SpO2 91 % en air ambiant ; mollet gauche tuméfié, sensible et discrètement érythémateux, sans autre anomalie."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vers une évaluation médicale pour suspicion d'embolie pulmonaire",correct:!0,critical:!0},{id:"b",label:"Rassurer en évoquant une contracture musculaire pleurale post-chirurgicale"},{id:"c",label:"Réaliser des techniques ostéopathiques respiratoires avant réévaluation"}],reveal:"Le terrain à risque (chirurgie récente), la dyspnée brutale, la douleur pleurale, l'hypoxémie et les signes évocateurs de thrombose veineuse du mollet forment un tableau à haut risque d'embolie pulmonaire, imposant une orientation médicale urgente sans délai."}],discriminators:["Terrain à risque de maladie thromboembolique : chirurgie ou immobilisation récente, cancer, antécédent de thrombose veineuse.","Dyspnée brutale associée à une douleur pleurale et des signes évocateurs de thrombose veineuse profonde (mollet tuméfié, sensible, érythémateux)."],redFlags:["Hypoxémie (SpO2 < 94 %) associée à une dyspnée brutale.","Signes cliniques de thrombose veineuse profonde associés à la dyspnée.","Tachycardie et tachypnée chez un patient à risque thromboembolique."],differential:["Embolie pulmonaire","Pneumothorax","Douleur pariétale post-chirurgicale","Pneumonie"],pitfalls:["Attribuer la douleur pleurale à une origine musculo-squelettique post-chirurgicale sans rechercher de signe de thrombose veineuse associée.","Sous-estimer une dyspnée brutale chez un patient encore capable de parler normalement."],reasoning:"Chez une patiente récemment opérée, l'association d'une dyspnée brutale, d'une douleur pleurale, d'une hypoxémie et de signes évocateurs de thrombose veineuse du mollet constitue un tableau à haut risque d'embolie pulmonaire. Ce diagnostic impose une orientation médicale urgente, la défaillance ventriculaire droite étant la principale cause de décès dans les formes sévères.",relatedIds:["2.6-RF-01","2.6-RF-02"],sources:["NCBI-PE","NCBI-DYSPNEA"]},{id:"CASE-19",ue:"2.4",title:"Cervicalgie avec paresthésies de la main : radiculopathie C6 ou canal carpien ?",neutralTitle:"Cervicalgie avec paresthésies de la main chez un homme de 47 ans",priority:"A",vignette:"Homme 47 ans, menuisier, cervicalgie depuis 3 semaines irradiant vers le pouce droit, avec paresthésies occasionnelles de la main.",objective:"Distinguer une radiculopathie cervicale C6 d'un syndrome du canal carpien par un raisonnement structuré (interrogatoire, myotome/dermatome/réflexe, tests de provocation) avant toute prise en charge.",steps:[{kind:"anamnesis",prompt:"Quelles informations recherches-tu en priorité pour orienter l'origine ?",options:[{id:"a",label:"Trajet exact des paresthésies et présence d'une douleur cervicale associée",correct:!0},{id:"b",label:"Facteurs aggravants : position du cou, activité manuelle répétitive, réveil nocturne",correct:!0},{id:"c",label:"Présence de faiblesse ou de maladresse de la main",correct:!0},{id:"d",label:"Uniquement l'intensité de la douleur sur une échelle"}],reveal:"Douleur cervicale associée à l'irradiation, aggravée par l'extension/rotation du cou vers la droite ; pas de réveil nocturne systématique ; légère maladresse rapportée en fin de journée."},{kind:"exam",prompt:"Quels éléments d'examen permettent de trancher entre C6 et canal carpien ?",options:[{id:"a",label:"Force d'extension du poignet et réflexe brachio-radial",correct:!0,critical:!0},{id:"b",label:"Test de Spurling et test de distraction cervicale",correct:!0},{id:"c",label:"Signe de Tinel/Phalen au poignet",correct:!0},{id:"d",label:"Uniquement la sensibilité du pouce"}],reveal:"Extension du poignet légèrement diminuée à droite, réflexe brachio-radial diminué ; Spurling reproduit les paresthésies du pouce ; Tinel/Phalen négatifs au poignet."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter d'emblée en urgence pour IRM cervicale",critical:!0},{id:"b",label:"Retenir une radiculopathie C6 probable, absence de red flag : prise en charge conservatrice et réévaluation",correct:!0,critical:!0},{id:"c",label:"Traiter comme un canal carpien isolé (attelle de poignet)",critical:!0},{id:"d",label:"Rassurer sans réévaluation prévue",critical:!0}],reveal:"Réponse : B. Le niveau moteur/réflexe (C6) et le test de Spurling positif orientent vers une radiculopathie cervicale plutôt qu'un canal carpien isolé ; sans red flag, prise en charge conservatrice avec réévaluation de la progression motrice."}],discriminators:["Réflexe brachio-radial et force d'extension du poignet diminués (myotome/réflexe C6).","Spurling positif reproduisant les paresthésies du pouce.","Tinel/Phalen négatifs au poignet, peu en faveur d'un canal carpien isolé."],redFlags:["Absence de red flag ici : pas de progression motrice sévère, pas de signe pyramidal ni sphinctérien associé."],differential:["Radiculopathie cervicale C6.","Syndrome du canal carpien.","Syndrome du rond pronateur."],pitfalls:["Attribuer d'emblée des paresthésies du pouce à un canal carpien sans vérifier le niveau moteur/réflexe.","Ignorer la douleur cervicale associée et le facteur positionnel qui orientent vers une origine radiculaire."],reasoning:"La cohérence entre le trajet dermatomal C6, le déficit moteur et réflexe du même niveau, et un test de provocation cervical positif oriente vers une radiculopathie C6 plutôt qu'un canal carpien isolé ; en l'absence de red flag, la prise en charge reste conservatrice avec réévaluation de la progression.",relatedIds:["2.4-KN-01","2.4-EX-01","2.4-DX-01","1.6-DX-01","1.6-EX-01","2.5-RF-36"],sources:["NCBI-CERVICAL-RADIC","NCBI-MEDIANNERVE"]},{id:"CASE-20",ue:"2.6",title:"Dyspnée d'effort progressive chez une patiente âgée : insuffisance cardiaque ou déconditionnement ?",neutralTitle:"Dyspnée d'effort progressive chez une femme de 74 ans",priority:"A",vignette:"Femme 74 ans, dyspnée d'effort progressive depuis 6 semaines, désormais gênante pour monter un étage. Elle rapporte une prise de poids récente et des chevilles gonflées en fin de journée.",objective:"Distinguer une décompensation cardiaque d'un déconditionnement ou d'un problème veineux isolé par un interrogatoire et un examen orientés, avant toute décision d'orientation.",steps:[{kind:"anamnesis",prompt:"Quelles informations recherches-tu en priorité devant cette dyspnée d'effort progressive ?",options:[{id:"a",label:"Présence d'une orthopnée (nombre d'oreillers) ou de réveils nocturnes avec sensation d'étouffement",correct:!0},{id:"b",label:"Rythme et ampleur de la prise de poids, caractère bilatéral ou non des œdèmes",correct:!0},{id:"c",label:"Antécédents cardiovasculaires et traitements en cours",correct:!0},{id:"d",label:"Uniquement la distance de marche avant l'essoufflement"}],reveal:"Elle dort désormais avec deux oreillers depuis 2 semaines, s'est réveillée une fois en étouffement, a pris 3 kg en 10 jours, œdèmes bilatéraux et symétriques ; antécédent d'infarctus du myocarde il y a 5 ans."},{kind:"exam",prompt:"Quels éléments d'examen permettent de distinguer une décompensation cardiaque d'une cause veineuse isolée ?",options:[{id:"a",label:"Auscultation pulmonaire (crépitants bibasaux) et cardiaque (B3)",correct:!0,critical:!0},{id:"b",label:"Turgescence jugulaire et reflux hépato-jugulaire",correct:!0},{id:"c",label:"Caractère symétrique et déclive des œdèmes, prise du godet",correct:!0},{id:"d",label:"Uniquement la couleur de la peau des chevilles"}],reveal:"Crépitants bibasaux ne remontant pas à la toux, B3 audible au foyer mitral, turgescence jugulaire présente, œdèmes bilatéraux symétriques prenant le godet."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Rassurer et proposer un reconditionnement à l'effort",critical:!0},{id:"b",label:"Orienter en avis médical rapide (jour même) pour suspicion de décompensation cardiaque",correct:!0,critical:!0},{id:"c",label:"Traiter les œdèmes par drainage manuel et réévaluer dans un mois",critical:!0},{id:"d",label:"Attendre l'aggravation d'un signe de gravité avant d'orienter",critical:!0}],reveal:"Réponse : B. L'orthopénie récente, la dyspnée paroxystique nocturne, la prise de poids rapide et les œdèmes bilatéraux, confirmés par les crépitants, le B3 et la turgescence jugulaire, orientent vers une décompensation cardiaque justifiant un avis médical rapide, pas un traitement manuel ni une simple surveillance."}],discriminators:["Orthopnée et dyspnée paroxystique nocturne récentes, absentes d'un simple déconditionnement.","Prise de poids rapide et œdèmes bilatéraux symétriques, plutôt qu'unilatéraux comme dans une cause veineuse localisée.","Crépitants bibasaux, B3 et turgescence jugulaire objectivant la congestion."],redFlags:["Orthopnée nouvelle, dyspnée paroxystique nocturne, prise de poids rapide et œdèmes bilatéraux progressifs chez une patiente aux antécédents cardiaques."],differential:["Décompensation cardiaque gauche et droite.","Déconditionnement à l'effort.","Insuffisance veineuse chronique isolée.","Exacerbation de bronchopneumopathie chronique obstructive."],pitfalls:["Attribuer la dyspnée d'effort progressive au seul âge ou déconditionnement sans interroger l'orthopnée et la prise de poids.","Traiter les œdèmes bilatéraux comme un problème purement mécanique sans dépister une congestion cardiaque."],reasoning:"La cohérence entre l'orthopnée récente, la dyspnée paroxystique nocturne, la prise de poids rapide, les œdèmes bilatéraux symétriques et les signes de congestion à l'examen (crépitants, B3, turgescence jugulaire) oriente vers une décompensation cardiaque chez une patiente à antécédent d'infarctus, justifiant un avis médical rapide plutôt qu'un reconditionnement ou un traitement manuel des œdèmes.",relatedIds:["2.6-KN-02","2.6-RF-03","2.6-EX-01","1.8-KN-01","1.8-EX-01"],sources:["NCBI-HF","NCBI-CARDIAC-CYCLE"]},{id:"CASE-21",ue:"2.10",title:"Lombalgie et fatigue chez une patiente sous chimiothérapie : ne pas manquer une neutropénie fébrile",neutralTitle:"Lombalgie et fatigue chez une femme de 58 ans sous chimiothérapie",priority:"A+",vignette:"Femme 58 ans, suivie pour un cancer du sein, chimiothérapie reçue il y a 8 jours. Consulte en cabinet d'ostéopathie pour une lombalgie basse et une fatigue inhabituelle depuis 2 jours, avec un léger frisson signalé depuis la veille.",objective:"Reconnaître qu'une fièvre chez une patiente sous chimiothérapie récente impose une orientation urgente pour suspicion de neutropénie fébrile, indépendamment du motif de consultation musculo-squelettique.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Date de la dernière séance de chimiothérapie",correct:!0,critical:!0},{id:"b",label:"Type d'assurance maladie de la patiente",correct:!1},{id:"c",label:"Présence de frissons, de fièvre ressentie ou de malaise général",correct:!0,critical:!0},{id:"d",label:"Antécédents familiaux de lombalgie",correct:!1}],reveal:"Chimiothérapie reçue il y a 8 jours. Léger frisson depuis la veille au soir, sensation de fatigue inhabituelle, absence de fièvre mesurée à domicile."},{kind:"exam",prompt:"Quels éléments recherches-tu à l'examen ?",options:[{id:"a",label:"Prise de la température corporelle",correct:!0,critical:!0},{id:"b",label:"Palpation des aires ganglionnaires et recherche de splénomégalie",correct:!0,critical:!0},{id:"c",label:"Recherche de pétéchies ou d'ecchymoses cutanées",correct:!0},{id:"d",label:"Testing de force musculaire des membres inférieurs uniquement",correct:!1}],reveal:"Température mesurée à 38,6 °C. Pas d'adénopathie ni de splénomégalie palpable. Pas de purpura ni d'ecchymose visible. Lombalgie reproductible mais non spécifique à la palpation."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence vers une structure hospitalière pour suspicion de neutropénie fébrile",correct:!0,critical:!0},{id:"b",label:"Réaliser une séance de manipulation ostéopathique pour soulager la lombalgie avant d'orienter",correct:!1},{id:"c",label:"Renvoyer à domicile avec un antipyrétique et revoir dans 48 heures",correct:!1},{id:"d",label:"Rassurer car l'examen clinique ne retrouve aucun foyer infectieux",correct:!1}],reveal:"Une fièvre ≥ 38,3 °C chez une patiente sous chimiothérapie récente est une urgence de neutropénie fébrile jusqu'à preuve du contraire, même en l'absence de foyer infectieux, de purpura ou de signe de choc : l'orientation hospitalière immédiate prime sur toute prise en charge de la lombalgie."}],discriminators:["Fièvre ≥ 38,3 °C chez un patient sous chimiothérapie récente, indépendamment de la présence d'un foyer infectieux visible.","Absence de signes locaux d'infection malgré un contexte à haut risque (neutropénie).","Symptôme musculo-squelettique bénin en apparence (lombalgie, fatigue) ne devant pas détourner l'attention du terrain à risque."],redFlags:["Fièvre chez un patient sous chimiothérapie dans les 3 semaines précédentes.","Frissons ou sensation de malaise général associés à la fièvre chez un patient à risque de neutropénie.","Absence de foyer infectieux visible n'excluant pas une infection sévère chez un patient neutropénique."],differential:["Neutropénie fébrile (urgence)","Lombalgie mécanique banale liée à la fatigue et à la posture","Fièvre liée à la chimiothérapie elle-même (diagnostic d'élimination)","Métastase osseuse vertébrale (à évoquer si douleur nocturne ou résistante, mais non prioritaire ici devant la fièvre)"],pitfalls:["Traiter la lombalgie en première intention parce qu'elle est le motif de consultation exprimé, en reléguant au second plan le contexte de chimiothérapie récente.","Ne pas prendre la température parce que la plainte semble purement musculo-squelettique.","Rassurer la patiente parce qu'aucun foyer infectieux n'est retrouvé à l'examen."],reasoning:"Chez une patiente sous chimiothérapie récente, une fièvre ≥ 38,3 °C constitue une urgence de neutropénie fébrile jusqu'à preuve du contraire, y compris lorsque le motif de consultation est un symptôme musculo-squelettique banal et que l'examen ne retrouve aucun foyer infectieux, purpura ou signe de choc. La reconnaissance de ce terrain prime sur le traitement du symptôme exprimé et impose une orientation hospitalière immédiate.",relatedIds:["2.10-RF-02","2.10-MG-01"],sources:["NCBI-FEBRILE-NEUTROPENIA","NICE-CG151"]},{id:"CASE-22",ue:"2.9",title:"Jambe rouge et fébrile : cellulite ou fasciite nécrosante ?",neutralTitle:"Rougeur et douleur du mollet fébriles chez un homme de 58 ans diabétique",priority:"A+",vignette:"Homme 58 ans, diabétique de type 2, consulte pour une douleur et une rougeur du mollet gauche apparues depuis 12 heures, fébrile à 38,9 °C. Il décrit une douleur qu'il juge disproportionnée par rapport à ce qu'il voit sur sa peau.",objective:"Reconnaître les signes distinguant une fasciite nécrosante d'une cellulite simple et décider de l'orientation appropriée sans délai.",steps:[{kind:"anamnesis",prompt:"Quel élément anamnestique recherches-tu en priorité ?",options:[{id:"a",label:"Rapidité d'installation et vitesse d'aggravation sur les dernières heures",correct:!0,critical:!0},{id:"b",label:"Antécédents (diabète, immunodépression) et porte d'entrée cutanée récente",correct:!0,critical:!0},{id:"c",label:"Habitudes alimentaires récentes"}],reveal:"Douleur apparue il y a 12 heures et s'aggravant rapidement d'heure en heure ; diabète connu ; petite plaie de rasage sur le mollet trois jours plus tôt."},{kind:"exam",prompt:"Quel signe à l'examen oriente le plus vers une fasciite nécrosante plutôt qu'une cellulite simple ?",options:[{id:"a",label:"Douleur intense hors de proportion avec l'aspect cutané, avec crépitation sous-cutanée à la palpation",correct:!0,critical:!0},{id:"b",label:"Érythème bien délimité et chaleur locale, sans autre anomalie"},{id:"c",label:"Adénopathie inguinale sensible isolée"}],reveal:"Douleur jugée disproportionnée par rapport à l'aspect initial modeste de la peau, crépitation sous-cutanée perçue à la palpation et début de bulles hémorragiques : signes évocateurs de fasciite nécrosante."},{kind:"decision",prompt:"Quelle est la conduite appropriée à ce stade ?",options:[{id:"a",label:"Orienter en urgence vers les urgences chirurgicales pour évaluation et débridement",correct:!0,critical:!0},{id:"b",label:"Prescrire un traitement antibiotique oral et revoir dans 48 heures",critical:!0},{id:"c",label:"Débuter un drainage lymphatique manuel et l'application de glace",critical:!0},{id:"d",label:"Rassurer et proposer une simple surveillance à domicile"}],reveal:"Douleur disproportionnée, crépitation et progression rapide sur un terrain diabétique imposent une orientation chirurgicale immédiate, sans délai ni prise en charge manuelle préalable."}],discriminators:["Douleur disproportionnée par rapport à l'aspect cutané visible.","Crépitation sous-cutanée ou bulles hémorragiques à l'examen.","Progression très rapide, en quelques heures.","Terrain à risque : diabète, immunodépression, porte d'entrée cutanée récente."],redFlags:["Douleur disproportionnée avec progression rapide et crépitation : suspicion de fasciite nécrosante, urgence chirurgicale absolue."],differential:["Cellulite simple : érythème bien délimité, douleur proportionnée à l'aspect cutané, évolution plus lente.","Érysipèle : bordure nette et surélevée, fièvre, sans crépitation ni nécrose.","Thrombose veineuse profonde : œdème et douleur du mollet, mais sans crépitation ni signe cutané nécrotique.","Dermohypodermite bactérienne non nécrosante sans critère de gravité."],pitfalls:["Sous-estimer une douleur disproportionnée en l'attribuant à l'anxiété du patient.","Attendre une aggravation visible de la peau (bulles, nécrose) avant d'orienter, alors que la nécrose sous-jacente précède souvent les signes cutanés visibles."],reasoning:"Une douleur de jambe disproportionnée par rapport à l'aspect cutané, associée à une progression rapide sur quelques heures et à une crépitation sous-cutanée, chez un patient diabétique avec porte d'entrée cutanée, signe une fasciite nécrosante jusqu'à preuve du contraire. Ce tableau se distingue d'une cellulite simple par la disproportion douleur/aspect et la rapidité d'évolution, deux discriminants cliniques précoces qui précèdent les signes cutanés tardifs (bulles, nécrose). L'urgence est chirurgicale : orienter sans délai prime sur toute tentative de traitement conservateur ou manuel.",relatedIds:["2.9-RF-03","2.9-EX-01","2.9-MG-01"],sources:["NCBI-NEC-FASCIITIS","NCBI-CELLULITIS"]},{id:"CASE-23",ue:"2.15",title:"Douleur diffuse chronique sans red flag : reconnaître le pattern nociplastique",neutralTitle:"Douleurs diffuses chroniques chez une femme de 42 ans",priority:"A",vignette:"Femme 42 ans, douleurs diffuses touchant le rachis et les quatre membres depuis 8 mois, fatigue marquée, sommeil non réparateur. Pas de gonflement articulaire rapporté, bilan biologique antérieur normal, pas de perte de poids ni de fièvre.",objective:"Reconnaître un pattern de douleur nociplastique compatible avec une fibromyalgie après avoir formellement écarté les red flags, et proposer une conduite proportionnée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Red flags généraux : perte de poids, douleur nocturne non soulagée, fièvre, antécédent de cancer",correct:!0,critical:!0},{id:"b",label:"Étendue de la douleur (nombre de régions touchées), durée d'évolution, retentissement sur le sommeil et la fatigue",correct:!0,critical:!0},{id:"c",label:"Recherche d'un traumatisme isolé et récent à l'origine de la douleur"}],reveal:"Aucun red flag identifié ; douleur diffuse depuis 8 mois touchant 4 des 5 régions corporelles, sommeil non réparateur, fatigue marquée, sans facteur traumatique déclenchant."},{kind:"exam",prompt:"Quel élément d'examen orientes-tu en priorité ?",options:[{id:"a",label:"Recherche d'une sensibilité diffuse à la palpation et d'un examen articulaire normal, sans synovite",correct:!0,critical:!0},{id:"b",label:"Questionnaire DN4 pour dépister une composante neuropathique associée",correct:!0},{id:"c",label:"Prescription d'emblée d'une IRM du rachis et des articulations périphériques"}],reveal:"Sensibilité diffuse à la palpation sans synovite ni déficit neurologique ; DN4 négatif (1/10), excluant une composante neuropathique dominante."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter vers une prise en charge biopsychosociale multimodale (activité physique graduée, sommeil, gestion du stress), sans multiplier les examens complémentaires",correct:!0,critical:!0},{id:"b",label:"Demander un bilan d'imagerie complet du rachis et des articulations avant toute prise en charge",critical:!0},{id:"c",label:"Affirmer qu'il s'agit d'un problème « purement psychologique » et ne proposer aucune prise en charge",critical:!0},{id:"d",label:"Débuter d'emblée un traitement ostéopathique isolé sans expliquer le mécanisme au patient"}],reveal:"L'absence de red flag associée à un pattern compatible avec les critères 2016 de la fibromyalgie justifie une approche biopsychosociale proportionnée, sans surinvestigation ni réduction psychologisante du tableau."}],discriminators:["Absence de red flag malgré une douleur diffuse évoluant depuis plusieurs mois.","Douleur touchant au moins 4 des 5 régions corporelles depuis au moins 3 mois.","Sensibilité diffuse à la palpation sans synovite ni déficit neurologique.","DN4 négatif, excluant une composante neuropathique dominante."],redFlags:["Aucun red flag ici, mais toute apparition secondaire d'un red flag (perte de poids, douleur nocturne nouvelle, déficit neurologique) impose de reconsidérer le diagnostic."],differential:["Douleur nociplastique compatible avec une fibromyalgie (critères ACR 2016).","Polyarthrite ou connectivite débutante, à écarter par l'absence de synovite.","Hypothyroïdie (fatigue et myalgies diffuses).","Douleur neuropathique diffuse, peu probable ici devant un DN4 négatif."],pitfalls:["Multiplier les examens complémentaires devant un tableau typique et sans red flag, ce qui peut renforcer la kinésiophobie et la chronicisation.","Qualifier la douleur de « psychologique » sans reconnaître la nociplasticité comme un mécanisme physiopathologique à part entière."],reasoning:"Une douleur diffuse touchant au moins 4 des 5 régions corporelles depuis plus de 3 mois, associée à une fatigue et un sommeil non réparateur, sans red flag ni synovite ni composante neuropathique (DN4 négatif), correspond à un pattern de douleur nociplastique compatible avec les critères 2016 de la fibromyalgie. La reconnaissance de ce pattern typique permet de proposer une prise en charge biopsychosociale proportionnée plutôt que de multiplier les examens complémentaires, tout en restant vigilant à l'apparition secondaire d'un red flag.",relatedIds:["2.15-KN-01","2.15-DX-01","2.15-RF-03"],sources:["PUBMED-FM-ACR2016","PUBMED-DN4"]},{id:"CASE-24",ue:"2.15",title:"Lombalgie chronique : douleur mécanique ou inflammatoire ?",neutralTitle:"Lombalgie évoluant depuis 4 mois chez un homme de 28 ans",priority:"A",vignette:"Homme 28 ans, lombalgie basse évoluant depuis 4 mois, début progressif sans traumatisme, dérouillage matinal de plus de 30 minutes, amélioration nette à l'activité, aggravation au repos avec réveils nocturnes en deuxième partie de nuit.",objective:"Appliquer les critères ASAS de douleur inflammatoire pour distinguer une lombalgie inflammatoire d'une lombalgie mécanique commune, et décider de l'orientation appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu systématiquement à l'interrogatoire ?",options:[{id:"a",label:"Les 5 critères ASAS de douleur inflammatoire (âge de début, mode de début, effet de l'exercice, effet du repos, horaire du réveil nocturne)",correct:!0,critical:!0},{id:"b",label:"Durée de la raideur matinale",correct:!0,critical:!0},{id:"c",label:"Notion de traumatisme direct récent du rachis"}],reveal:"4 des 5 critères ASAS présents : âge 28 ans, début insidieux, amélioration à l'effort, absence d'amélioration au repos, réveil nocturne en deuxième partie de nuit ; raideur matinale de 45 minutes ; pas de traumatisme rapporté."},{kind:"exam",prompt:"Quel élément d'examen recherches-tu en priorité ?",options:[{id:"a",label:"Mobilité rachidienne globale et douleur sacro-iliaque à la palpation et aux manœuvres de provocation",correct:!0,critical:!0},{id:"b",label:"Recherche d'un déficit neurologique radiculaire associé",correct:!0},{id:"c",label:"Mesure isolée de l'amplitude de flexion de hanche, sans autre exploration"}],reveal:"Limitation de la mobilité rachidienne, douleur sacro-iliaque bilatérale à la palpation, absence de déficit neurologique radiculaire."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter vers un avis rhumatologique pour bilan de spondyloarthrite axiale",correct:!0,critical:!0},{id:"b",label:"Traiter comme une lombalgie mécanique commune avec maintien de l'activité seul, sans avis complémentaire",critical:!0},{id:"c",label:"Prescrire un repos strict prolongé",critical:!0}],reveal:"4 critères ASAS positifs sur 5, associés à une atteinte sacro-iliaque bilatérale, évoquent une lombalgie inflammatoire : cette douleur secondaire justifie un avis rhumatologique pour bilan de spondyloarthrite axiale, plutôt qu'une prise en charge de lombalgie mécanique commune isolée."}],discriminators:["4 critères ASAS de douleur inflammatoire sur 5 présents.","Raideur matinale prolongée, supérieure à 30 minutes.","Amélioration nette à l'exercice et non au repos.","Douleur sacro-iliaque bilatérale à l'examen."],redFlags:["Lombalgie répondant aux critères ASAS de douleur inflammatoire chez un patient jeune : douleur secondaire potentielle nécessitant un bilan rhumatologique, pas seulement une prise en charge mécanique."],differential:["Spondyloarthrite axiale (lombalgie inflammatoire).","Lombalgie mécanique commune.","Sacro-iliite infectieuse, à écarter en présence de fièvre associée.","Fibromyalgie, mais critères ASAS non typiques dans ce tableau localisé."],pitfalls:["Traiter une lombalgie inflammatoire comme une lombalgie mécanique commune sans avoir recherché systématiquement les critères ASAS.","Négliger la durée de la raideur matinale, discriminant clé souvent sous-interrogé."],reasoning:"Une lombalgie débutant avant 40 ans, d'installation insidieuse, améliorée par l'exercice et non par le repos, avec réveil nocturne en deuxième partie de nuit, répond à 4 des 5 critères ASAS de douleur inflammatoire. Associée à une raideur matinale prolongée et une atteinte sacro-iliaque bilatérale, elle évoque une spondyloarthrite axiale : une douleur secondaire qui justifie un avis rhumatologique, à distinguer d'une lombalgie mécanique commune dont la prise en charge et le pronostic diffèrent.",relatedIds:["2.15-DX-02","2.15-RF-03"],sources:["PUBMED-ASAS-IBP"]},{id:"CASE-25",ue:"2.8",title:"Douleur scrotale aiguë chez un adolescent : ne pas manquer une torsion testiculaire",neutralTitle:"Douleur testiculaire brutale chez un adolescent de 14 ans",priority:"A+",vignette:"Garçon 14 ans, douleur testiculaire droite brutale depuis 2 heures, l'ayant réveillé en pleine nuit, associée à des nausées et un épisode de vomissement. Pas de fièvre ni de brûlure mictionnelle rapportées.",objective:"Reconnaître les signes cliniques de torsion testiculaire et décider d'une orientation en urgence absolue sans attendre de confirmation par imagerie.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'interrogatoire ?",options:[{id:"a",label:"Mode d'installation de la douleur : brutal ou progressif",correct:!0,critical:!0},{id:"b",label:"Présence de nausées ou de vomissements associés",correct:!0,critical:!0},{id:"c",label:"Habitudes alimentaires récentes"}],reveal:"Douleur brutale apparue il y a 2 heures, réveil nocturne, nausées et un épisode de vomissement ; pas de fièvre, pas de brûlure mictionnelle."},{kind:"exam",prompt:"Quels signes recherches-tu à l'examen scrotal ?",options:[{id:"a",label:"Réflexe crémastérien et position du testicule (ascension, horizontalisation)",correct:!0,critical:!0},{id:"b",label:"Signe de Prehn (soulagement ou non à l'élévation du testicule)",correct:!0},{id:"c",label:"Recherche isolée d'une masse abdominale pulsatile"}],reveal:"Réflexe crémastérien aboli à droite, testicule ascensionné et en position horizontale, sensibilité diffuse ; signe de Prehn négatif (pas de soulagement à l'élévation)."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence absolue vers les urgences chirurgicales/urologiques, sans attendre une échographie",correct:!0,critical:!0},{id:"b",label:"Demander une échographie doppler scrotale en externe avant toute décision",critical:!0},{id:"c",label:"Traiter par antalgiques et revoir en consultation dans 48 heures",critical:!0},{id:"d",label:"Rassurer, car le signe de Prehn négatif élimine une torsion testiculaire",critical:!0}],reveal:"L'abolition du réflexe crémastérien et l'ascension/horizontalisation testiculaire chez un adolescent avec douleur brutale sont hautement évocatrices d'une torsion testiculaire. Le sauvetage testiculaire dépend directement du délai avant détorsion : l'orientation est une urgence absolue, sans attendre de confirmation échographique."}],discriminators:["Douleur scrotale brutale de moins de 6 heures avec réflexe crémastérien aboli.","Testicule ascensionné et horizontalisé à l'examen.","Absence de fièvre et de signes urinaires, âge péripubertaire.","Signe de Prehn négatif, insuffisant pour éliminer une torsion."],redFlags:["Douleur scrotale brutale avec réflexe crémastérien aboli chez un adolescent : torsion testiculaire jusqu'à preuve du contraire, urgence chirurgicale absolue."],differential:["Torsion testiculaire.","Torsion d'une annexe testiculaire (hydatide de Morgagni), douleur souvent moins intense, « blue dot sign » possible.","Épididymite aiguë, installation plus progressive, réflexe crémastérien conservé.","Hernie inguino-scrotale étranglée."],pitfalls:["Se fier au signe de Prehn négatif pour éliminer une torsion, alors qu'il n'est pas assez fiable.","Attendre une confirmation échographique avant d'orienter devant une suspicion clinique forte, alors que chaque heure de retard réduit les chances de sauvetage testiculaire."],reasoning:"Une douleur scrotale brutale et nocturne chez un adolescent, associée à des nausées, un réflexe crémastérien aboli et un testicule ascensionné et horizontalisé, est hautement évocatrice d'une torsion testiculaire, même en présence d'un signe de Prehn négatif qui n'a pas de valeur d'élimination fiable. Le pronostic de sauvetage testiculaire dépasse 90 % si la détorsion chirurgicale intervient dans les 6 heures suivant le début de la douleur, ce qui impose une orientation chirurgicale en urgence absolue sans attendre de confirmation échographique.",relatedIds:["2.8-RF-04","2.8-DX-01","2.8-EX-01"],sources:["NCBI-TESTICULAR-TORSION","NCBI-ACUTE-SCROTUM"]},{id:"CASE-26",ue:"2.5",title:"Dorsalgie progressive après bactériémie : suspecter une infection vertébrale",neutralTitle:"Dorsalgie progressive chez un homme de 62 ans, hospitalisé récemment",priority:"A+",vignette:"Homme 62 ans, diabétique, hospitalisé six semaines auparavant pour une bactériémie à Staphylococcus aureus. Il consulte pour une dorsalgie focale progressive depuis trois semaines, désormais nocturne et peu soulagée par le repos. Température 37,4 °C.",objective:"Identifier une suspicion de spondylodiscite malgré l'absence de fièvre franche, rechercher une complication neurologique et organiser l'orientation.",steps:[{kind:"anamnesis",prompt:"Quels éléments renforcent en priorité la suspicion d'infection vertébrale ?",options:[{id:"a",label:"Bactériémie récente à Staphylococcus aureus et douleur rachidienne nouvelle progressive",correct:!0,critical:!0},{id:"b",label:"Absence de fièvre supérieure à 38 °C",critical:!0},{id:"c",label:"Diabète et douleur nocturne peu soulagée par le repos",correct:!0}],reveal:"Une bactériémie récente à Staphylococcus aureus associée à une douleur rachidienne nouvelle est un signal majeur. L'absence de fièvre franche n'exclut pas une spondylodiscite."},{kind:"exam",prompt:"Quel examen orienté réalises-tu avant l'orientation ?",options:[{id:"a",label:"Signes vitaux, état général et examen neurologique moteur, sensitif et sphinctérien",correct:!0,critical:!0},{id:"b",label:"Palpation prudente à la recherche d'une douleur vertébrale focale",correct:!0},{id:"c",label:"Tests répétés de mise en charge pour confirmer une origine mécanique",critical:!0}],reveal:"La douleur est focale en D9-D10. Il n'existe pas de déficit neurologique ni de trouble sphinctérien, mais ces résultats n'annulent pas le risque infectieux."},{kind:"decision",prompt:"Quelle conduite tiens-tu ?",options:[{id:"a",label:"Orienter rapidement pour bilan médical, marqueurs inflammatoires, hémocultures et IRM selon l'évaluation",correct:!0,critical:!0},{id:"b",label:"Commencer un traitement manuel et réévaluer après plusieurs séances",critical:!0},{id:"c",label:"Rassurer car le patient est apyrétique et sans déficit neurologique",critical:!0}],reveal:"La combinaison bactériémie récente et douleur rachidienne progressive impose d'exclure une infection vertébrale. Un déficit neurologique ou un sepsis ferait basculer vers une orientation hospitalière immédiate."}],discriminators:["Bactériémie récente à Staphylococcus aureus.","Douleur rachidienne focale, progressive et peu soulagée par le repos.","Absence de fièvre franche compatible avec une infection vertébrale."],redFlags:["Déficit neurologique, troubles sphinctériens ou signes de compression médullaire.","Sepsis ou instabilité hémodynamique.","Bactériémie récente associée à une douleur rachidienne nouvelle."],differential:["Spondylodiscite ou ostéomyélite vertébrale.","Métastase vertébrale.","Fracture vertébrale.","Douleur mécanique commune."],pitfalls:["Écarter l'infection parce que le patient est apyrétique.","Attribuer la douleur au diabète ou à une cause mécanique sans intégrer la bactériémie récente.","Réaliser un traitement manuel avant clarification diagnostique."],reasoning:"Une infection vertébrale peut se présenter par une douleur rachidienne progressive sans fièvre. Une bactériémie récente à Staphylococcus aureus augmente fortement la suspicion et justifie une évaluation médicale rapide. L'examen neurologique recherche une complication compressive qui impose une orientation hospitalière immédiate.",relatedIds:["2.5-RF-18","2.3-RF-01","2.10-MG-01"],sources:["IDSA-NVO-2015"]},{id:"CASE-27",ue:"2.3",title:"Mollet gonflé après un vol long-courrier : penser à la thrombose veineuse profonde",neutralTitle:"Mollet gonflé après un vol long-courrier chez une femme de 62 ans",priority:"A+",vignette:"Femme de 62 ans, retour d'un vol long-courrier il y a 3 jours, consulte pour un gonflement et une douleur du mollet droit apparus progressivement depuis 48 heures. Le mollet est chaud, légèrement sensible à la palpation. Pas de fièvre, état général conservé. Elle prend une contraception œstroprogestative.",objective:"Reconnaître une suspicion de thrombose veineuse profonde chez un patient consultant pour une jambe douloureuse et chaude, et adapter la conduite en excluant tout traitement manuel local avant orientation.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité ?",options:[{id:"a",label:"Facteurs de risque thromboemboliques : immobilisation récente, antécédent de TVP/embolie pulmonaire, contraception œstroprogestative, chirurgie récente, cancer actif",correct:!0,critical:!0},{id:"b",label:"Caractère uni- ou bilatéral du gonflement et mode d'installation (progressif ou brutal)",correct:!0,critical:!0},{id:"c",label:"Type de chaussures portées pendant le vol",correct:!1}],reveal:"Gonflement unilatéral progressif du mollet droit depuis 48 heures, sans porte d'entrée cutanée visible ; vol long-courrier de 11 heures il y a 3 jours ; pas d'antécédent personnel de TVP mais contraception œstroprogestative en cours."},{kind:"exam",prompt:"Quels signes recherches-tu à l'examen ?",options:[{id:"a",label:"Asymétrie de circonférence du mollet, chaleur, sensibilité à la palpation profonde",correct:!0,critical:!0},{id:"b",label:"Aspect de la peau (érythème diffus ou bien délimité), veines superficielles dilatées",correct:!0,critical:!0},{id:"c",label:"Utiliser le signe de Homans isolé comme critère décisif pour écarter le diagnostic",correct:!1}],reveal:"Asymétrie de circonférence de 3 cm par rapport au mollet controlatéral, chaleur et sensibilité profonde à la palpation, pas d'érythème net ni de porte d'entrée cutanée, absence de fièvre."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter vers une évaluation médicale pour suspicion de thrombose veineuse profonde avant tout traitement manuel local",correct:!0,critical:!0},{id:"b",label:"Réaliser un drainage lymphatique manuel du membre pour réduire l'œdème"},{id:"c",label:"Rassurer et proposer des étirements du mollet"}],reveal:"Le gonflement unilatéral progressif après immobilisation prolongée (vol long-courrier), associé à une contraception œstroprogestative, constitue un tableau évocateur de thrombose veineuse profonde. Un traitement manuel local (massage, drainage) est contre-indiqué tant que ce diagnostic n'est pas écarté, en raison du risque de mobilisation d'un thrombus et d'embolie pulmonaire."}],discriminators:["Gonflement unilatéral progressif sur plusieurs jours, sans porte d'entrée cutanée ni fièvre","Terrain à risque thromboembolique (immobilisation prolongée, contraception œstroprogestative)","Absence des signes typiques de cellulite (érythème bien délimité, fièvre) ou de fasciite nécrosante (douleur disproportionnée, progression très rapide)"],redFlags:["Gonflement unilatéral d'un membre inférieur sur terrain à risque thromboembolique","Absence de fièvre qui ne rassure pas sur la bénignité","Traitement manuel local d'un membre gonflé sans avoir écarté une thrombose veineuse profonde"],differential:["Thrombose veineuse profonde","Cellulite","Fasciite nécrosante"],pitfalls:["Se fier au signe de Homans pour écarter une thrombose veineuse profonde","Traiter par massage ou drainage lymphatique un membre gonflé sans avoir écarté une thrombose veineuse profonde, avec risque d'embolie pulmonaire","Attendre une fièvre pour évoquer une cause vasculaire ou infectieuse grave"],reasoning:"Un gonflement unilatéral progressif du mollet après immobilisation prolongée, chez une patiente sous contraception œstroprogestative, est un tableau évocateur de thrombose veineuse profonde qui doit être distingué d'une cellulite (érythème mieux délimité, porte d'entrée cutanée) et d'une fasciite nécrosante (douleur disproportionnée, progression très rapide, crépitation). Le signe de Homans n'a pas de valeur discriminante suffisante. Le traitement manuel local du membre est contre-indiqué avant d'avoir écarté une thrombose veineuse profonde, en raison du risque de mobilisation d'un thrombus et d'embolie pulmonaire.",relatedIds:["2.3-DX-01"],sources:["NCBI-DVT"]},{id:"CASE-28",ue:"2.7",title:"Douleur dorsale « en barre » : reconnaître une pancréatite aiguë",neutralTitle:"Douleur dorsale « en barre » chez un homme de 50 ans",priority:"A+",vignette:"Homme de 50 ans, consommation d'alcool régulière, consulte en ostéopathie pour une douleur dorsale médiane apparue brutalement il y a 6 heures après un repas arrosé, avec nausées et vomissements. La douleur est peu modifiée par les mouvements du rachis.",objective:"Différencier une origine viscérale (pancréatite, cholécystite) d'une douleur dorsale mécanique et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité ?",options:[{id:"a",label:"Caractéristiques de la douleur (irradiation en barre, brutalité), facteurs déclenchants (repas, alcool), symptômes digestifs associés",correct:!0,critical:!0},{id:"b",label:"Antécédents de lithiase biliaire, consommation d'alcool habituelle, traitements en cours",correct:!0,critical:!0},{id:"c",label:"Type d'activité sportive pratiquée habituellement",correct:!1}],reveal:"Douleur épigastrique irradiant en barre vers le dos, apparue après un repas copieux et une consommation d'alcool importante, avec nausées et vomissements répétés ; pas d'antécédent de lithiase connu."},{kind:"exam",prompt:"Quels éléments recherches-tu à l'examen ?",options:[{id:"a",label:"Sensibilité épigastrique, effet de la mobilisation active du rachis dorsal sur la douleur",correct:!0,critical:!0},{id:"b",label:"Position antalgique (antéflexion du tronc), signes de choc (tachycardie, hypotension)",correct:!0,critical:!0},{id:"c",label:"Amplitude de rotation cervicale passive",correct:!1}],reveal:"Douleur épigastrique peu modifiée par la mobilisation du rachis dorsal, position antalgique en antéflexion du tronc, tachycardie à 110/min, sensibilité épigastrique marquée sans défense franche."},{kind:"decision",prompt:"Quelle est la conduite la plus appropriée ?",options:[{id:"a",label:"Orienter en urgence médicale pour suspicion de pancréatite aiguë (bilan biologique, lipase)",correct:!0,critical:!0},{id:"b",label:"Traiter par techniques ostéopathiques myofasciales dorsales avant réévaluation"},{id:"c",label:"Rassurer et revoir en fin de semaine si la douleur persiste"}],reveal:"Douleur en barre peu modifiée par la mobilisation rachidienne, contexte de repas alcoolisé, nausées/vomissements et tachycardie évoquent une pancréatite aiguë : une orientation médicale urgente est nécessaire, sans traitement manuel du rachis dorsal qui ne modifierait pas une douleur d'origine viscérale."}],discriminators:["Douleur peu modifiée par la mobilisation active du rachis","Irradiation typique en barre vers le dos après repas/alcool","Signes digestifs et hémodynamiques associés"],redFlags:["Douleur épigastrique transfixiante brutale","Tachycardie et signes de choc","Vomissements répétés associés à une douleur dorsale"],differential:["Pancréatite aiguë","Colique biliaire ou cholécystite aiguë","Douleur dorsale mécanique ou musculo-squelettique"],pitfalls:["Traiter une douleur dorsale « en barre » comme une douleur mécanique sans interroger le contexte digestif","Se rassurer parce que la mobilisation du rachis reproduit partiellement la douleur"],reasoning:"Une douleur dorsale « en barre » d'apparition brutale, peu modifiée par la mobilisation active du rachis et associée à des signes digestifs (nausées, vomissements) dans un contexte évocateur (repas, alcool), doit faire évoquer une pancréatite aiguë avant une origine mécanique. La tachycardie et la position antalgique en antéflexion renforcent la suspicion et imposent une orientation médicale urgente sans traitement manuel préalable.",relatedIds:["2.7-RF-03","2.7-RF-02"],sources:["NCBI-PANCREATITIS"]},{id:"CASE-29",ue:"2.2",title:"Lombalgie chronique avec bilan biologique évocateur : reconnaître le changement de plan",neutralTitle:"Lombalgie chronique chez une femme de 52 ans, bilan biologique en main",priority:"A",vignette:"Une femme de 52 ans consulte pour une lombalgie basse évoluant depuis 4 mois, avec une raideur matinale qu'elle dit durer « plus d'une heure » et qui s'améliore avec l'activité. Elle a vu son médecin traitant il y a 10 jours, qui a demandé une prise de sang dont elle apporte les résultats : CRP à 28 mg/L (N < 10), VS à 42 mm/h. Aucun traitement n'a encore été instauré ; le médecin lui a dit de « voir avec son ostéopathe en attendant le rendez-vous de rhumatologie ».",objective:"Reconnaître que des marqueurs inflammatoires élevés associés à un tableau clinique évocateur de douleur inflammatoire (critères ASAS) changent la probabilité diagnostique et doivent réorienter la prise en charge, sans attendre la confirmation rhumatologique pour ajuster son discours et sa vigilance.",steps:[{kind:"anamnesis",prompt:"Quels éléments de l'anamnèse recherchez-vous en priorité pour préciser le caractère mécanique ou inflammatoire de cette lombalgie ?",options:[{id:"a",label:"Durée de la raideur matinale et effet de l'activité sur la douleur",correct:!0},{id:"b",label:"Antécédents familiaux de spondyloarthrite ou de psoriasis",correct:!0},{id:"c",label:"Type de matelas utilisé actuellement"},{id:"d",label:"Douleur fessière alternante (d'un côté puis de l'autre)",correct:!0}],reveal:"La raideur matinale prolongée améliorée par l'activité, les antécédents familiaux de spondyloarthrite/psoriasis et la douleur fessière alternante sont trois des éléments des critères ASAS de douleur inflammatoire ; le type de matelas n'a pas de valeur discriminante ici."},{kind:"exam",prompt:"Quels éléments d'examen, associés aux résultats biologiques, renforceraient la suspicion d'une atteinte inflammatoire sacro-iliaque ?",options:[{id:"a",label:"Douleur à la palpation des articulations sacro-iliaques, bilatérale",correct:!0},{id:"b",label:"Douleur reproduite par les manœuvres de mise en tension sacro-iliaque (FABER, compression)",correct:!0},{id:"c",label:"Amélioration franche de la douleur en position assise prolongée"},{id:"d",label:"Absence totale de douleur nocturne"}],reveal:"Une douleur sacro-iliaque bilatérale à la palpation et reproduite par les manœuvres de mise en tension renforce l'hypothèse inflammatoire ; à l'inverse, une amélioration en position assise prolongée et l'absence de douleur nocturne orientent plutôt vers une origine mécanique."},{kind:"decision",prompt:"Compte tenu du tableau (CRP 28 mg/L, VS 42 mm/h, critères ASAS présents), quelle est la conduite la plus appropriée aujourd'hui ?",options:[{id:"a",label:"Débuter un traitement manuel lombaire standard en attendant le rendez-vous de rhumatologie, comme pour une lombalgie mécanique",critical:!0},{id:"b",label:"Expliquer à la patiente l'importance de maintenir le rendez-vous de rhumatologie, adapter la prise en charge au contexte inflammatoire suspecté et éviter toute manœuvre agressive non justifiée",correct:!0},{id:"c",label:"Considérer que la prise de sang n'est pas pertinente pour une lombalgie et ne pas en tenir compte",critical:!0},{id:"d",label:"Annuler toute prise en charge ostéopathique dans l'attente du rendez-vous, sans aucune explication à la patiente"}],reveal:"Le tableau (marqueurs inflammatoires élevés, critères ASAS positifs) doit faire reconsidérer la lombalgie comme potentiellement secondaire à une spondyloarthrite axiale : la priorité est d'informer la patiente, de maintenir le suivi rhumatologique déjà engagé et d'adapter prudemment la prise en charge, sans la traiter comme une lombalgie mécanique commune ni l'abandonner sans explication."}],discriminators:["CRP et VS élevées associées à des critères ASAS positifs, orientant vers une lombalgie inflammatoire (douleur secondaire) plutôt que mécanique.","Raideur matinale prolongée au-delà de 30 à 60 minutes, améliorée par l'activité et non par le repos.","Douleur fessière alternante, évocatrice d'une atteinte sacro-iliaque bilatérale."],redFlags:["Douleur répondant aux critères ASAS, associée à des marqueurs biologiques élevés, orientant vers une spondyloarthrite axiale à confirmer.","Nécessité de ne pas retarder ni interrompre le suivi rhumatologique déjà engagé par le médecin traitant."],differential:["Lombalgie mécanique commune","Spondyloarthrite axiale","Autre cause inflammatoire ou infectieuse à explorer si le bilan rhumatologique ne confirme pas ce diagnostic"],pitfalls:["Traiter cette lombalgie comme une lombalgie mécanique commune sans tenir compte des résultats biologiques et des critères ASAS.","Considérer qu'une prise de sang « n'est pas du ressort » de l'ostéopathe et l'ignorer complètement dans le raisonnement clinique."],reasoning:"Cette patiente présente une lombalgie chronique dont l'anamnèse (raideur matinale prolongée améliorée par l'activité, douleur fessière alternante) et la biologie (CRP et VS nettement élevées) convergent vers une douleur inflammatoire selon les critères ASAS, potentiellement secondaire à une spondyloarthrite axiale. Ce n'est pas à l'ostéopathe de poser ce diagnostic, mais il doit reconnaître que ce faisceau d'arguments change la probabilité diagnostique par rapport à une lombalgie mécanique commune. La conduite appropriée consiste à maintenir la patiente engagée dans son suivi rhumatologique déjà programmé, à adapter le discours et la prise en charge manuelle à ce contexte inflammatoire suspecté, et à ne pas ignorer un résultat biologique rapporté spontanément sous prétexte qu'il sortirait du champ ostéopathique.",relatedIds:["2.2-KN-01","2.2-IM-01","2.15-DX-02","2.5-RF-27"],sources:["NICE-NG59","PUBMED-ASAS-IBP","NCBI-CRP"]},{id:"CASE-30",ue:"2.12",title:"Boiterie fébrile chez un enfant de 5 ans",neutralTitle:"Boiterie fébrile chez un enfant de 5 ans",priority:"A+",vignette:"Garçon de 5 ans amené par ses parents pour une boiterie apparue depuis hier, avec refus progressif de poser le pied droit ce matin. Température mesurée à domicile : 38,4 °C. Pas de traumatisme rapporté.",objective:"Différencier une synovite transitoire d'une arthrite septique de hanche chez un enfant fébrile et boiteux, et décider de la conduite appropriée.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'anamnèse ?",options:[{id:"a",label:"Présence de fièvre et son évolution depuis le début des symptômes",correct:!0,critical:!0},{id:"b",label:"Capacité ou non à poser le pied et à marcher",correct:!0,critical:!0},{id:"c",label:"Type d'aliments consommés dans la journée"},{id:"d",label:"Notion de traumatisme, d'infection récente (ORL, cutanée) ou de contexte d'immunodépression",correct:!0}],reveal:"Fièvre présente depuis hier, refus total de mise en charge ce matin, pas de traumatisme rapporté ; une angine a été traitée il y a 10 jours."},{kind:"exam",prompt:"Quel élément d'examen recherches-tu pour orienter ton diagnostic ?",options:[{id:"a",label:"Mobilisation passive de la hanche, en particulier en rotation interne et abduction",correct:!0,critical:!0},{id:"b",label:"Mesure de la température et recherche de signes généraux",correct:!0,critical:!0},{id:"c",label:"Test de Lasègue"},{id:"d",label:"Palpation isolée du genou, sans examiner la hanche"}],reveal:"Douleur vive à la mobilisation passive de la hanche, en particulier en rotation interne et abduction ; fébrile à 38,6 °C à l'examen ; pas de porte d'entrée cutanée visible."},{kind:"decision",prompt:"Quelle est la conduite appropriée à ce stade ?",options:[{id:"a",label:"Rassurer les parents et revoir dans une semaine si la boiterie persiste",critical:!0},{id:"b",label:"Orienter en urgence vers les urgences pédiatriques pour bilan (biologie, imagerie, avis orthopédique) devant une suspicion d'arthrite septique",correct:!0,critical:!0},{id:"c",label:"Débuter un traitement ostéopathique du bassin pour soulager la boiterie",critical:!0},{id:"d",label:"Prescrire des antipyrétiques seuls et revoir en cas de persistance"}],reveal:"La combinaison fièvre et refus de mise en charge correspond à deux des quatre critères de Kocher déjà présents avant même la biologie, ce qui impose une orientation urgente pour éliminer une arthrite septique, urgence orthopédique engageant le pronostic articulaire."}],discriminators:["Fièvre associée à un refus de mise en charge : deux des quatre critères de Kocher déjà présents avant même la biologie, ce qui élève significativement la probabilité d'arthrite septique.","Douleur vive à la mobilisation passive de la hanche, en particulier en rotation interne : signe évocateur d'un épanchement articulaire.","Absence de traumatisme rapporté, contexte infectieux récent (angine) : profil compatible avec une diffusion hématogène vers l'articulation."],redFlags:["Boiterie fébrile avec refus de mise en charge chez l'enfant : à considérer comme une arthrite septique jusqu'à preuve du contraire.","Douleur à la mobilisation passive de la hanche associée à une fièvre : nécessite un bilan urgent (biologie, imagerie, avis orthopédique) avant toute prise en charge manuelle."],differential:["Synovite transitoire de hanche (plus fréquente, mais fébricule modérée et mise en charge souvent partiellement conservée).","Maladie de Legg-Calvé-Perthes (installation plus progressive, pas de fièvre).","Ostéomyélite du fémur proximal (peut coexister avec une arthrite septique par contiguïté)."],pitfalls:["Attribuer par défaut une boiterie fébrile à une synovite transitoire sans bilan devant deux critères de Kocher déjà présents.","Débuter une prise en charge manuelle du bassin ou de la hanche devant une suspicion d'arthrite septique non écartée."],reasoning:"La présence simultanée d'une fièvre et d'un refus de mise en charge chez un enfant boiteux correspond à deux des quatre critères de Kocher, ce qui élève significativement la probabilité d'arthrite septique de hanche par rapport à une synovite transitoire. L'arthrite septique étant une urgence orthopédique pouvant détruire le cartilage articulaire en quelques heures à quelques jours, la conduite appropriée est une orientation urgente vers un bilan biologique, une imagerie et un avis orthopédique, sans tenter de traitement manuel local avant d'avoir écarté ce diagnostic.",relatedIds:["2.12-DX-01","2.12-RF-02"],sources:["KOCHER-1999-SEPTIC-HIP","AAFP-LIMP-CHILD-2023"]},{id:"CASE-31",ue:"2.13",title:"Céphalée nouvelle chez une patiente de 76 ans",neutralTitle:"Céphalée nouvelle chez une femme de 76 ans",priority:"A+",vignette:"Femme de 76 ans consulte pour une céphalée temporale droite apparue progressivement depuis 2 semaines, inhabituelle pour elle. Elle signale une gêne à la mastication prolongée et une fatigue générale. Pas d'antécédent migraineux.",objective:"Reconnaître un tableau évocateur d'artérite à cellules géantes chez une personne âgée et décider d'une orientation adaptée à l'urgence du risque visuel.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité à l'anamnèse ?",options:[{id:"a",label:"Caractère nouveau de la céphalée par rapport aux céphalées habituelles de la patiente",correct:!0,critical:!0},{id:"b",label:"Présence d'une claudication de la mâchoire ou de la langue à la mastication prolongée",correct:!0,critical:!0},{id:"c",label:"Habitudes de sommeil récentes"},{id:"d",label:"Présence de troubles visuels associés (vision trouble, diplopie, amaurose transitoire)",correct:!0,critical:!0}],reveal:"Céphalée bien nouvelle et différente de ses maux de tête habituels ; gêne franche à la mastication prolongée confirmée ; pas de trouble visuel rapporté à ce stade, mais la patiente n'y avait pas prêté attention."},{kind:"exam",prompt:"Quel élément d'examen recherches-tu pour orienter ton diagnostic ?",options:[{id:"a",label:"Sensibilité ou induration à la palpation du trajet de l'artère temporale",correct:!0,critical:!0},{id:"b",label:"Recherche de douleurs et raideur des ceintures scapulaire et pelvienne (pseudo-polyarthrite rhizomélique)",correct:!0},{id:"c",label:"Test de Spurling"},{id:"d",label:"Mobilité active isolée du rachis cervical"}],reveal:"Artère temporale droite sensible et légèrement indurée à la palpation ; la patiente rapporte également une raideur des épaules le matin depuis un mois."},{kind:"decision",prompt:"Quelle est la conduite appropriée à ce stade ?",options:[{id:"a",label:"Traiter la céphalée par relâchement myofascial cervico-crânien et réévaluer dans 2 semaines",critical:!0},{id:"b",label:"Orienter en urgence, le jour même, vers une évaluation médicale ou rhumatologique en évoquant une artérite à cellules géantes",correct:!0,critical:!0},{id:"c",label:"Prescrire un antalgique simple et attendre l'évolution",critical:!0},{id:"d",label:"Programmer une biologie de contrôle dans 2 semaines avant toute décision"}],reveal:"Le tableau (âge, céphalée nouvelle, claudication de la mâchoire, artère temporale sensible, syndrome rhizomélique associé) est hautement évocateur d'une artérite à cellules géantes : urgence médicale par risque de cécité irréversible, nécessitant une évaluation et une corticothérapie sans délai."}],discriminators:["Céphalée nouvelle et différente des céphalées habituelles chez une patiente de plus de 50 ans : élément clé qui distingue ce tableau d'une céphalée primaire connue.","Claudication de la mâchoire à la mastication prolongée : signe hautement spécifique d'artérite à cellules géantes.","Sensibilité et induration de l'artère temporale à la palpation, associées à un syndrome rhizomélique : renforcent fortement la suspicion clinique avant même la biologie."],redFlags:["Céphalée nouvelle après 50 ans associée à une claudication de la mâchoire ou des troubles visuels : artérite à cellules géantes à évoquer en urgence par risque de cécité irréversible.","Toute suspicion de ce diagnostic impose un avis spécialisé le jour même, sans attendre un bilan biologique programmé."],differential:["Céphalée cervicogène ou tensionnelle (mais pas de caractère nouveau ni de claudication de la mâchoire).","Névralgie du trijumeau (douleur paroxystique en éclair, différente d'une céphalée progressive).","Pathologie dentaire ou temporo-mandibulaire (mais n'explique ni la sensibilité de l'artère temporale ni le syndrome rhizomélique)."],pitfalls:["Traiter une céphalée temporale du sujet âgé par une technique manuelle locale avant d'avoir écarté une artérite à cellules géantes.","Attendre un bilan biologique programmé alors que le tableau impose un avis en urgence par le risque de cécité irréversible."],reasoning:"L'association d'une céphalée nouvelle après 50 ans, d'une claudication de la mâchoire, d'une artère temporale sensible et d'un syndrome rhizomélique associé constitue un tableau hautement évocateur d'artérite à cellules géantes selon les critères cliniques de la guideline BSR 2020. Il s'agit d'une urgence médicale : le risque de perte de vision irréversible par atteinte ischémique du nerf optique impose une évaluation spécialisée et une corticothérapie à haute dose sans délai, idéalement le jour même et au plus tard dans les 3 jours ouvrés.",relatedIds:["2.13-RF-06"],sources:["BSR-GCA-2020"]},{id:"CASE-32",ue:"2.11",title:"Idées noires exprimées en séance : jusqu'où aller ?",neutralTitle:"Propos inquiétants exprimés en séance par une femme de 34 ans",priority:"A+",vignette:"Femme 34 ans, suivie depuis plusieurs mois pour lombalgie chronique. En fin de séance, elle dit sur un ton neutre : « De toute façon, plus rien n'a d'importance, j'ai déjà tout organisé pour que ce soit simple pour mes proches après. » Elle n'a jamais évoqué ce type de propos auparavant.",objective:"Repérer un risque suicidaire exprimé en consultation ostéopathique et adopter la conduite appropriée avant la fin de la séance.",steps:[{kind:"anamnesis",prompt:"Quelle est la première question à poser directement à la patiente ?",options:[{id:"a",label:"Lui demander explicitement si elle pense à mettre fin à ses jours et si elle a un plan précis",correct:!0,critical:!0},{id:"b",label:"Changer de sujet pour ne pas la mettre mal à l'aise"},{id:"c",label:"Lui demander si elle a bien pris ses médicaments habituels"}],reveal:"Elle confirme y penser depuis plusieurs semaines et avoir déjà choisi le moyen ; elle dit avoir mis de l'ordre dans ses affaires récemment."},{kind:"anamnesis",prompt:"Quel autre élément faut-il explorer avant de décider de la conduite à tenir ?",options:[{id:"a",label:"L'accès effectif au moyen évoqué et la présence d'un antécédent de tentative",correct:!0,critical:!0},{id:"b",label:"Ses habitudes de sommeil des sept derniers jours"},{id:"c",label:"Son alimentation de la semaine"}],reveal:"Elle confirme avoir accès direct au moyen évoqué et n'a jamais fait de tentative auparavant, mais le plan est précis et récent."},{kind:"decision",prompt:"Quelle est la conduite appropriée à la fin de la séance ?",options:[{id:"a",label:"La laisser rentrer seule en lui donnant les coordonnées d'un psychologue pour plus tard",critical:!0},{id:"b",label:"L'orienter en urgence vers une structure médicale/psychiatrique et ne pas la laisser seule avant la prise en charge",correct:!0,critical:!0},{id:"c",label:"Lui faire promettre de ne rien faire et prévoir un suivi ostéopathique rapproché",critical:!0},{id:"d",label:"Minimiser ses propos pour ne pas l'alarmer inutilement"}],reveal:"Une idéation suicidaire active avec plan précis, moyen accessible et récent constitue un risque imminent : orientation en urgence immédiate, sans laisser la patiente seule dans l'intervalle."}],discriminators:["Plan précis + moyen accessible + mise en ordre des affaires personnelles : trois éléments concordants signant un risque imminent.","L'absence d'antécédent de tentative ne réduit pas le niveau d'urgence face à un plan actuel précis et récent."],redFlags:["Idéation suicidaire active avec plan et moyen accessibles, exprimée pour la première fois en consultation."],differential:["Réaction de deuil ou d'épuisement chronique sans idéation active, à différencier par l'absence de plan et de moyen."],pitfalls:["Se rassurer sur l'absence d'antécédent de tentative pour minimiser le risque actuel.","Laisser la patiente repartir seule sans relais organisé."],reasoning:"L'association d'une idéation suicidaire active, d'un plan précis, d'un moyen accessible et de comportements évocateurs (mise en ordre des affaires) signe un risque suicidaire imminent, indépendamment de l'absence d'antécédent de tentative ; la conduite impose une orientation en urgence immédiate et une présence continue jusqu'à la prise en charge.",relatedIds:["2.11-RF-01"],sources:["NICE-NG225","NIMH-ASQ"]},{id:"CASE-33",ue:"2.14",title:"Choc à la tête pendant un match : peut-il continuer ?",neutralTitle:"Choc à la tête pendant un match chez un joueur de 22 ans",priority:"A+",vignette:"Joueur de rugby 22 ans, choc tête contre tête lors d'un plaquage. Il se relève seul, semble « secoué » quelques secondes puis dit vouloir continuer le match. L'entraîneur te demande ton avis en tant qu'ostéopathe accompagnant l'équipe.",objective:"Reconnaître une suspicion de commotion cérébrale sur le terrain et appliquer la règle du retrait immédiat.",steps:[{kind:"exam",prompt:"Quels éléments recherches-tu en priorité sur le terrain ?",options:[{id:"a",label:"Perte de connaissance, confusion, trouble de l'équilibre ou de la mémoire immédiate",correct:!0,critical:!0},{id:"b",label:"Douleur au niveau du genou controlatéral"},{id:"c",label:"Fréquence cardiaque de récupération après l'effort"}],reveal:"Le joueur ne se souvient pas précisément des secondes qui ont précédé le choc et met plus de temps que d'habitude à répondre aux questions simples."},{kind:"decision",prompt:"Quelle est la décision appropriée immédiatement ?",options:[{id:"a",label:"Le laisser reprendre le jeu puisqu'il n'y a pas eu de perte de connaissance",critical:!0},{id:"b",label:"Le retirer immédiatement du jeu pour le reste de la rencontre, sans retour possible le jour même",correct:!0,critical:!0},{id:"c",label:"Le laisser reprendre après quelques minutes de repos sur le banc s'il se sent mieux",critical:!0}],reveal:"Toute suspicion de commotion impose un retrait immédiat et définitif pour la rencontre en cours, y compris en l'absence de perte de connaissance."},{kind:"decision",prompt:"Que dis-tu à l'entraîneur et au joueur pour la suite ?",options:[{id:"a",label:"Qu'il pourra revenir en deuxième mi-temps si les symptômes disparaissent",critical:!0},{id:"b",label:"Qu'une surveillance médicale est nécessaire dans les heures suivantes et qu'un protocole de retour au sport progressif et encadré devra être respecté avant toute reprise",correct:!0,critical:!0},{id:"c",label:"Qu'il peut reprendre l'entraînement dès le lendemain s'il n'a plus mal à la tête",critical:!0}],reveal:"Le retour au sport suit un protocole progressif et encadré médicalement ; il ne repose jamais sur la seule disparition des symptômes au repos ni sur un délai fixe arbitraire."}],discriminators:["L'absence de perte de connaissance n'exclut pas une commotion : la confusion et le ralentissement des réponses suffisent à la suspecter.","Règle du jour même : aucun retour au jeu n'est autorisé le jour du choc en cas de suspicion."],redFlags:["Aggravation progressive des symptômes dans les heures suivant le choc (céphalée croissante, vomissements répétés, somnolence) : imposerait un transfert en urgence."],differential:["Simple sidération sans atteinte cognitive, à réévaluer strictement selon les signes objectifs, jamais présumée sans évaluation."],pitfalls:["Se fier à l'absence de perte de connaissance pour autoriser un retour au jeu.","Autoriser une reprise sur simple demande du joueur motivé à continuer."],reasoning:"Une confusion et un ralentissement des réponses après un choc à la tête suffisent à suspecter une commotion cérébrale, même sans perte de connaissance : la règle est le retrait immédiat et définitif pour la rencontre, suivi d'une surveillance et d'un protocole de retour au sport progressif encadré médicalement.",relatedIds:["2.14-RF-01"],sources:["BJSPORTS-CONCUSSION23"]},{id:"CASE-34",ue:"4.3",title:"Lombalgie aiguë avec troubles sphinctériens débutants",neutralTitle:"Lombalgie aiguë avec troubles urinaires débutants chez une femme de 47 ans",priority:"A+",vignette:"Femme 47 ans, lombalgie basse depuis 3 jours suite à un port de charge. Elle décrit aussi, depuis hier, une difficulté à uriner et une sensation d'engourdissement inhabituelle entre les cuisses.",objective:"Réviser l'hypothèse initiale de lombalgie mécanique dès l'apparition d'un signe de gravité, et déclencher l'orientation adaptée sans délai.",steps:[{kind:"anamnesis",prompt:"Quelles questions complètent en priorité l'anamnèse ?",options:[{id:"a",label:"Caractère bilatéral ou unilatéral des troubles sensitifs périnéaux et leur évolution",correct:!0,critical:!0},{id:"b",label:"Présence de troubles du contrôle sphinctérien (urinaire/anal) ou de la fonction sexuelle",correct:!0,critical:!0},{id:"c",label:"Type d'activité sportive pratiquée habituellement"}],reveal:"Anesthésie en selle bilatérale et rétention urinaire débutante, apparues en moins de 24 heures."},{kind:"exam",prompt:"Quel élément d'examen recherches-tu en priorité ?",options:[{id:"a",label:"Sensibilité périnéale (territoire S2-S5) et tonus du sphincter anal",correct:!0,critical:!0},{id:"b",label:"Réflexes achilléens et signe de Babinski",correct:!0},{id:"c",label:"Amplitude de flexion lombaire"}],reveal:"Hypoesthésie en selle bilatérale confirmée, tonus sphinctérien anal diminué."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Traiter par techniques myotensives et revoir dans une semaine",critical:!0},{id:"b",label:"Orienter en urgence vers un service d'urgences pour IRM et avis neurochirurgical",correct:!0,critical:!0},{id:"c",label:"Prescrire du repos et réévaluer dans 48h",critical:!0},{id:"d",label:"Rassurer, un red flag isolé n'impose pas d'action"}],reveal:"Anesthésie en selle bilatérale et troubles sphinctériens débutants = syndrome de la queue de cheval jusqu'à preuve du contraire ; urgence chirurgicale, transfert immédiat aux urgences."}],discriminators:["Anesthésie en selle bilatérale (et non unilatérale) : signe la souffrance des racines sacrées basses S2-S5.","Apparition ou aggravation des troubles sphinctériens en moins de 48h : fenêtre thérapeutique chirurgicale à respecter."],redFlags:["Anesthésie en selle bilatérale.","Trouble sphinctérien (rétention ou incontinence) d'apparition récente.","Déficit moteur bilatéral des membres inférieurs associé."],differential:["Lombalgie mécanique commune, sans déficit neurologique.","Radiculopathie unilatérale simple (L5-S1) sans atteinte sphinctérienne.","Sténose canalaire dégénérative chronique, évolution lente et non aiguë."],pitfalls:["Ancrage sur le diagnostic initial de « lombalgie mécanique » et sous-évaluation d'un red flag apparu en cours d'évolution (biais d'ancrage).","Attendre une aggravation franche avant d'orienter, alors que la fenêtre chirurgicale se compte en heures."],reasoning:"Le tableau initial évoque une lombalgie mécanique post-effort, mais l'apparition secondaire de troubles sphinctériens et d'une anesthésie en selle bilatérale impose de réviser l'hypothèse : syndrome de la queue de cheval, urgence neurochirurgicale. Le raisonnement hypothético-déductif exige de retester activement les hypothèses de gravité à chaque changement clinique, plutôt que de s'ancrer sur l'hypothèse initiale la plus fréquente.",relatedIds:["4.3-KN-01","4.3-MG-01","5.3-MG-01"],sources:["NICE-NG59","NCBI-CAUDA-EQUINA"]},{id:"CASE-35",ue:"4.3",title:"Douleur thoracique partiellement reproduite à la palpation",neutralTitle:"Douleur thoracique partiellement reproduite à la palpation chez un homme de 58 ans",priority:"A+",vignette:"Homme 58 ans, tabagique, douleur thoracique gauche depuis 2 jours qu'il attribue à un faux mouvement en jardinant. La douleur augmente parfois à la mobilisation du tronc, mais aussi à la marche, avec un essoufflement inhabituel.",objective:"Ne pas conclure à une origine pariétale du seul fait d'une reproduction partielle de la douleur à la mobilisation, et dépister une origine cardiaque.",steps:[{kind:"anamnesis",prompt:"Quels éléments recherches-tu en priorité ?",options:[{id:"a",label:"Facteurs de risque cardiovasculaires (tabac, HTA, diabète, antécédents familiaux)",correct:!0,critical:!0},{id:"b",label:"Caractère reproductible à la fois par la palpation ET par l'effort",correct:!0,critical:!0},{id:"c",label:"Type de literie utilisée"}],reveal:"Tabagisme actif 30 paquets-années, douleur en partie reproduite par la palpation mais aussi déclenchée par la marche rapide, avec dyspnée."},{kind:"exam",prompt:"Que conclure de l'examen de la paroi thoracique ?",options:[{id:"a",label:"La reproduction partielle à la palpation, associée à une gêne persistante à l'effort, ne permet pas d'exclure une cause cardiaque",correct:!0,critical:!0},{id:"b",label:"Amplitude de rotation thoracique"},{id:"c",label:"L'auscultation pulmonaire seule suffit à exclure une cause cardiaque",critical:!0}],reveal:"La douleur est partiellement reproduite à la palpation, mais la dyspnée et la gêne à l'effort persistent indépendamment de la mobilisation : dissociation incompatible avec une origine pariétale pure."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Traiter la paroi thoracique par techniques articulatoires",critical:!0},{id:"b",label:"Orienter en urgence vers un avis médical (ECG, troponine) avant toute prise en charge manuelle",correct:!0,critical:!0},{id:"c",label:"Surveiller sans avis médical et réévaluer dans une semaine",critical:!0}],reveal:"Douleur thoracique avec facteurs de risque cardiovasculaires et dissociation effort/palpation : suspicion de syndrome coronarien, avis médical urgent avant tout traitement manuel."}],discriminators:["Reproduction partielle seulement de la douleur à la palpation : ne suffit pas à exclure une cause cardiaque si elle persiste aussi à l'effort.","Dyspnée associée à l'effort, indépendante de la mobilisation du tronc."],redFlags:["Douleur thoracique déclenchée par l'effort chez un patient à facteurs de risque cardiovasculaires.","Dyspnée associée à la douleur thoracique."],differential:["Douleur pariétale costale isolée (syndrome de Tietze, dysfonction costo-vertébrale).","Névralgie intercostale.","Reflux gastro-œsophagien."],pitfalls:["Clôture prématurée du raisonnement dès qu'un signe soutient l'hypothèse bénigne, sans tester l'hypothèse grave.","Confondre reproduction partielle de la douleur à la palpation et exclusion complète d'une origine viscérale."],reasoning:"La reproduction partielle de la douleur par la palpation est souvent interprétée à tort comme une preuve d'origine pariétale. Ici, la persistance d'une gêne et d'une dyspnée à l'effort, indépendamment de la mobilisation, associée à des facteurs de risque cardiovasculaires, maintient l'hypothèse cardiaque active : elle doit être testée médicalement avant tout traitement manuel.",relatedIds:["4.3-MG-01","4.3-KN-02"],sources:["NICE-CG95"]},{id:"CASE-36",ue:"4.3",title:"Douleur d'épaule non mécanique chez un fumeur avec amaigrissement",neutralTitle:"Douleur d'épaule atypique chez un homme de 63 ans, fumeur",priority:"A+",vignette:"Homme 63 ans, tabagique 40 paquets-années, douleur d'épaule et de bras gauche évoluant depuis 6 semaines, non clairement mécanique, associée à une perte de poids de 4 kg non expliquée et une fatigue inhabituelle.",objective:"Ne pas traiter d'emblée comme une tendinopathie une douleur d'épaule dont le contexte évoque une cause systémique.",steps:[{kind:"anamnesis",prompt:"Quels éléments anamnestiques sont prioritaires ?",options:[{id:"a",label:"Amaigrissement involontaire, sudations nocturnes, altération de l'état général",correct:!0,critical:!0},{id:"b",label:"Antécédents tabagiques quantifiés",correct:!0,critical:!0},{id:"c",label:"Type de sport pratiqué"}],reveal:"Perte de poids confirmée non volontaire, tabagisme 40 paquets-années, pas de traumatisme."},{kind:"exam",prompt:"Quel constat d'examen oriente le raisonnement ?",options:[{id:"a",label:"Douleur non reproduite par les mobilisations spécifiques ni par les tests de conflit sous-acromial",correct:!0,critical:!0},{id:"b",label:"Recherche d'une adénopathie sus-claviculaire ou d'un syndrome de Claude Bernard-Horner associés",correct:!0,critical:!0},{id:"c",label:"Force isolée de la coiffe des rotateurs"}],reveal:"Douleur non reproduite mécaniquement, présence d'une discrète adénopathie sus-claviculaire homolatérale."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Traiter la coiffe des rotateurs par exercices excentriques",critical:!0},{id:"b",label:"Orienter vers le médecin traitant pour investigation du profil oncologique (voie rapide)",correct:!0,critical:!0},{id:"c",label:"Surveiller un mois avant réorientation",critical:!0}],reveal:"Douleur non mécanique + amaigrissement + tabagisme + adénopathie : suspicion de tumeur de l'apex pulmonaire, orientation médicale pour investigation."}],discriminators:["Douleur non reproduite par les manœuvres spécifiques de l'épaule.","Amaigrissement involontaire associé, hors contexte digestif évident.","Adénopathie sus-claviculaire homolatérale."],redFlags:["Douleur d'épaule d'allure non mécanique chez un fumeur de plus de 50 ans.","Perte de poids involontaire associée."],differential:["Tendinopathie de la coiffe des rotateurs.","Capsulite rétractile.","Radiculopathie cervicale C5-C6."],pitfalls:["Traiter d'emblée une douleur d'épaule comme mécanique sans avoir exclu les red flags systémiques (biais de disponibilité).","Négliger l'examen des aires ganglionnaires devant une douleur du membre supérieur."],reasoning:"La fréquence des tendinopathies de coiffe ne doit pas faire écarter d'emblée une cause systémique : l'absence de reproduction mécanique de la douleur, associée à l'amaigrissement, au tabagisme et à l'adénopathie sus-claviculaire, réoriente le raisonnement vers une hypothèse oncologique nécessitant une investigation médicale avant tout traitement.",relatedIds:["4.3-KN-02","4.3-MG-01"],sources:["NICE-NG12"]},{id:"CASE-37",ue:"4.3",title:"Confusion aiguë inhabituelle en cours de suivi",neutralTitle:"Confusion aiguë inhabituelle chez une femme de 82 ans en cours de suivi",priority:"A+",vignette:"Femme 82 ans, suivie pour lombalgie chronique, se présente pour sa séance habituelle. Sa fille remarque qu'elle est anormalement confuse depuis ce matin, avec un discours incohérent par moments, alors qu'elle est habituellement bien orientée.",objective:"Reconnaître un delirium aigu chez une personne âgée et suspendre la prise en charge prévue au profit d'une orientation médicale.",steps:[{kind:"anamnesis",prompt:"Quels éléments anamnestiques sont prioritaires ?",options:[{id:"a",label:"Mode d'installation (aigu ou progressif) et fluctuation dans la journée",correct:!0,critical:!0},{id:"b",label:"Cause déclenchante récente possible (infection, nouveau médicament, déshydratation, rétention urinaire)",correct:!0,critical:!0},{id:"c",label:"Ancienneté de la lombalgie chronique elle-même"}],reveal:"Confusion apparue en quelques heures ce matin, fluctuante, contexte de fièvre depuis hier."},{kind:"exam",prompt:"Que rechercher pour objectiver la situation ?",options:[{id:"a",label:"Évaluation rapide de l'attention et de l'orientation (ex. outil 4AT)",correct:!0,critical:!0},{id:"b",label:"Recherche de signes infectieux associés (fièvre, tachycardie)",correct:!0,critical:!0},{id:"c",label:"Poursuivre l'évaluation ostéopathique de la lombalgie comme prévu",critical:!0}],reveal:"Confusion fluctuante avec inattention et fièvre : tableau compatible avec un delirium probablement d'origine infectieuse."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Poursuivre la séance prévue en adaptant simplement le traitement",critical:!0},{id:"b",label:"Orienter en urgence vers une évaluation médicale",correct:!0,critical:!0},{id:"c",label:"Renvoyer à domicile avec conseil de repos",critical:!0}],reveal:"Une confusion aiguë fluctuante d'apparition récente chez une personne âgée fébrile est un delirium jusqu'à preuve du contraire, nécessitant une évaluation médicale urgente pour en rechercher la cause."}],discriminators:["Installation aiguë (quelques heures) et fluctuation dans la journée, à l'opposé d'un trouble cognitif chronique stable.","Fièvre associée à la confusion."],redFlags:["Confusion aiguë d'apparition récente chez une personne âgée.","Fièvre associée à un changement brutal de l'état mental."],differential:["Trouble neurocognitif majeur préexistant (démarrage progressif, pas de fluctuation aiguë).","Effet indésirable médicamenteux récent.","Trouble anxieux situationnel."],pitfalls:["Poursuivre une prise en charge planifiée par habitude, sans réévaluer l'état clinique du jour (clôture prématurée).","Attribuer la confusion au grand âge sans rechercher de cause aiguë réversible."],reasoning:"Le motif de consultation initial (suivi de lombalgie) ne doit pas empêcher de générer une nouvelle hypothèse dominante lorsque l'état clinique change en séance : une confusion aiguë fébrile et fluctuante chez une personne âgée impose l'hypothèse de delirium et une orientation médicale immédiate, avant toute poursuite du plan de traitement initial.",relatedIds:["4.3-DX-01","4.3-MG-01"],sources:["NICE-CG103","BELLELLI-4AT-2014"]},{id:"CASE-38",ue:"4.3",title:"Douleur testiculaire brutale chez un adolescent sportif",neutralTitle:"Douleur testiculaire brutale chez un adolescent sportif de 14 ans",priority:"A+",vignette:"Garçon 14 ans, sportif, consulte pour une douleur testiculaire droite brutale apparue il y a 3 heures pendant l'entraînement, avec nausées associées. Il attribue cela à un coup reçu au ballon.",objective:"Ne pas attribuer une douleur testiculaire aiguë au seul traumatisme rapporté, et dépister une torsion testiculaire.",steps:[{kind:"anamnesis",prompt:"Quels éléments anamnestiques sont prioritaires ?",options:[{id:"a",label:"Délai et brutalité d'apparition de la douleur, présence de nausées ou vomissements",correct:!0,critical:!0},{id:"b",label:"Antécédent d'épisodes similaires résolutifs spontanément",correct:!0,critical:!0},{id:"c",label:"Habitudes alimentaires récentes"}],reveal:"Douleur brutale il y a 3h, nausées associées, un épisode similaire résolu spontanément il y a deux semaines."},{kind:"exam",prompt:"Quel constat d'examen retiens-tu ?",options:[{id:"a",label:"Testicule ascensionné et horizontalisé, réflexe crémastérien aboli du côté douloureux",correct:!0,critical:!0},{id:"b",label:"Amplitude de mobilité lombaire"},{id:"c",label:"Force musculaire des membres inférieurs"}],reveal:"Testicule ascensionné, horizontalisé, réflexe crémastérien aboli à droite : signes évocateurs de torsion."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Traiter par techniques viscérales abdominales",critical:!0},{id:"b",label:"Orienter en extrême urgence vers les urgences chirurgicales",correct:!0,critical:!0},{id:"c",label:"Surveiller et revoir en fin de journée",critical:!0}],reveal:"Douleur testiculaire brutale, réflexe crémastérien aboli et antécédent d'épisode intermittent : forte suspicion de torsion testiculaire, urgence chirurgicale à référer immédiatement, le délai de prise en charge conditionnant directement la viabilité testiculaire."}],discriminators:["Brutalité et intensité de la douleur, disproportionnées par rapport au traumatisme rapporté.","Antécédent d'épisode douloureux similaire résolutif spontanément : évoque une torsion intermittente.","Réflexe crémastérien aboli du côté douloureux."],redFlags:["Douleur testiculaire aiguë de moins de 6 heures, quel que soit le contexte rapporté.","Réflexe crémastérien aboli."],differential:["Contusion testiculaire post-traumatique simple.","Torsion d'hydatide testiculaire (douleur souvent plus progressive, point douloureux localisé au pôle supérieur).","Épididymite aiguë (contexte infectieux, installation plus progressive)."],pitfalls:["Accepter l'explication traumatique fournie par le patient sans rechercher activement les signes de torsion (biais de confirmation).","Sous-estimer un antécédent d'épisode douloureux bref et résolutif spontanément, évocateur de torsion intermittente."],reasoning:"L'explication traumatique proposée par le patient est plausible mais ne doit pas clore le raisonnement : la brutalité de la douleur, l'antécédent d'épisode similaire et l'abolition du réflexe crémastérien font de la torsion testiculaire l'hypothèse dominante à écarter en urgence absolue.",relatedIds:["4.3-MG-01"],sources:["NCBI-TESTICULAR-TORSION","NCBI-ACUTE-SCROTUM"]},{id:"CASE-39",ue:"4.3",title:"Céphalée en coup de tonnerre pendant une séance cervicale",neutralTitle:"Céphalée brutale pendant une séance cervicale chez une femme de 39 ans",priority:"A+",vignette:"Femme 39 ans, céphalées cervicogènes habituelles connues, décrit aujourd'hui une céphalée d'intensité maximale d'emblée, apparue en quelques secondes pendant l'échauffement cervical, très différente de ses céphalées habituelles.",objective:"Interrompre la séance devant une céphalée en coup de tonnerre plutôt que de la traiter comme une céphalée cervicogène habituelle.",steps:[{kind:"anamnesis",prompt:"Quels éléments anamnestiques sont prioritaires ?",options:[{id:"a",label:"Mode d'installation (brutal, en coup de tonnerre) et intensité maximale d'emblée",correct:!0,critical:!0},{id:"b",label:"Comparaison avec les céphalées habituelles de la patiente",correct:!0,critical:!0},{id:"c",label:"Fréquence habituelle des céphalées sur l'année"}],reveal:"Céphalée en coup de tonnerre, intensité maximale en moins d'une minute, totalement différente des céphalées habituelles."},{kind:"exam",prompt:"Que recherches-tu associé à la céphalée ?",options:[{id:"a",label:"Signes neurologiques associés (raideur de nuque, troubles visuels, déficit focal)",correct:!0,critical:!0},{id:"b",label:"Amplitude cervicale habituelle avant de poursuivre la manipulation prévue",critical:!0},{id:"c",label:"Tension musculaire palpée des trapèzes"}],reveal:"Légère raideur de nuque associée, pas de déficit focal net pour l'instant."},{kind:"decision",prompt:"Quelle est la conduite appropriée ?",options:[{id:"a",label:"Poursuivre la séance en évitant simplement les manipulations à haute vélocité",critical:!0},{id:"b",label:"Interrompre la séance et orienter en urgence vers les urgences pour exclure une hémorragie sous-arachnoïdienne",correct:!0,critical:!0},{id:"c",label:"Traiter par relaxation musculaire et revoir en fin de semaine",critical:!0}],reveal:"Une céphalée en coup de tonnerre est une hémorragie sous-arachnoïdienne jusqu'à preuve du contraire : contre-indication absolue à toute manipulation, urgence médicale immédiate."}],discriminators:["Intensité maximale atteinte en quelques secondes à une minute, à l'opposé d'une céphalée cervicogène progressive.","Céphalée décrite comme radicalement différente des céphalées habituelles de la patiente."],redFlags:["Céphalée en coup de tonnerre (intensité maximale d'emblée).","Raideur de nuque associée à une céphalée brutale."],differential:["Céphalée cervicogène habituelle de la patiente.","Céphalée de tension aiguë.","Migraine inhabituellement sévère."],pitfalls:["Rattacher une céphalée nouvelle au contexte cervical connu du patient par habitude clinique (biais de disponibilité).","Poursuivre une séance de manipulation cervicale malgré un signal d'alerte neurologique nouveau."],reasoning:"Le contexte cervical connu de la patiente ne doit pas faire assimiler cette céphalée à ses céphalées habituelles : l'installation en coup de tonnerre et le changement radical de caractère imposent l'hypothèse d'hémorragie sous-arachnoïdienne, avec interruption immédiate de toute manipulation et orientation d'urgence.",relatedIds:["4.3-MG-01","5.3-RF-01"],sources:["NICE-CG150","NCBI-HVLA-CONTRA"]},{id:"CASE-40",ue:"5.3",title:"Lombalgie mécanique sans signal d'alerte : décision de traiter",neutralTitle:"Lombalgie aiguë chez un homme de 34 ans après un mouvement",priority:"A+",vignette:"Homme 34 ans, lombalgie basse depuis 4 jours après un mouvement de flexion-rotation au travail, sans irradiation, sans trouble neurologique, amélioration progressive à la marche.",objective:"Appliquer la grille de décision du diagnostic d'opportunité pour justifier un traitement direct.",steps:[{kind:"anamnesis",prompt:"Que vérifies-tu en priorité ?",options:[{id:"a",label:"Red flags classiques (âge, antécédent de cancer, traumatisme, fièvre, troubles sphinctériens)",correct:!0,critical:!0},{id:"b",label:"Absence de douleur nocturne isolée et d'altération de l'état général",correct:!0,critical:!0},{id:"c",label:"Type de chaussures portées habituellement"}],reveal:"Aucun red flag retrouvé, douleur mécanique typique, bon état général."},{kind:"exam",prompt:"Que confirmes-tu à l'examen ?",options:[{id:"a",label:"Reproduction mécanique de la douleur par le mouvement et la charge",correct:!0,critical:!0},{id:"b",label:"Examen neurologique des membres inférieurs normal",correct:!0,critical:!0},{id:"c",label:"Souplesse des ischio-jambiers isolée"}],reveal:"Douleur reproduite par la flexion, examen neurologique normal."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Traiter directement par prise en charge ostéopathique, avec filet de sécurité",correct:!0,critical:!0},{id:"b",label:"Orienter systématiquement vers un médecin avant tout traitement",critical:!0},{id:"c",label:"Surveiller sans traiter",critical:!0}],reveal:"Absence de red flag et présentation mécanique cohérente à l'examen : le diagnostic d'opportunité autorise une prise en charge ostéopathique directe, avec filet de sécurité sur les signes qui imposeraient une reconsultation."}],discriminators:["Absence de tout red flag à l'anamnèse et à l'examen.","Douleur mécanique reproduite de façon cohérente par le mouvement et la charge, examen neurologique normal."],redFlags:["Douleur nocturne non mécanique, non calmée par le repos : à rechercher systématiquement même en présentation apparemment bénigne.","Trouble sphinctérien ou déficit neurologique progressif : à réévaluer à chaque séance, y compris après une décision initiale de traiter."],differential:["Lombalgie mécanique commune, retenue ici.","Dysfonction sacro-iliaque isolée.","Contracture musculaire paravertébrale réactionnelle."],pitfalls:["Orienter par excès de prudence alors que la grille de décision autorise un traitement direct en l'absence de signal d'alerte, ce qui retarde une prise en charge appropriée.","Omettre le filet de sécurité sous prétexte que la présentation initiale est rassurante."],reasoning:"L'absence de tout red flag et la cohérence mécanique de la douleur permettent de conclure directement à la décision « traiter » de la grille du diagnostic d'opportunité, à condition d'accompagner ce traitement d'un filet de sécurité explicite en cas d'évolution défavorable.",relatedIds:["5.3-MG-01","5.3-MG-02"],sources:["NICE-NG59"]},{id:"CASE-41",ue:"5.3",title:"Douleur dorsale chez une patiente ostéoporotique : décision de surveiller",neutralTitle:"Douleur dorsale chez une femme de 71 ans, ostéoporose connue",priority:"A+",vignette:"Femme 71 ans, ostéoporose diagnostiquée et traitée, douleur dorsale mécanique modérée après un effort de jardinage, sans red flag associé. Elle demande une manipulation « comme d'habitude ».",objective:"Distinguer une contre-indication technique relative d'un signal d'alerte imposant une orientation médicale.",steps:[{kind:"anamnesis",prompt:"Que vérifies-tu en priorité ?",options:[{id:"a",label:"Absence de red flag (traumatisme franc, douleur nocturne, altération de l'état général)",correct:!0,critical:!0},{id:"b",label:"Statut osseux connu et traitements en cours (biphosphonates, anticoagulants)",correct:!0,critical:!0},{id:"c",label:"Marque de son traitement antiostéoporotique"}],reveal:"Pas de red flag, ostéoporose connue et traitée, pas d'anticoagulant."},{kind:"exam",prompt:"Que retiens-tu de l'examen ?",options:[{id:"a",label:"Douleur mécanique confirmée",correct:!0,critical:!0},{id:"b",label:"Zone douloureuse compatible avec une manipulation HVLA compte tenu de la fragilité osseuse connue",correct:!0,critical:!0},{id:"c",label:"Amplitude de rotation cervicale, non concernée ici"}],reveal:"Douleur mécanique confirmée, zone dorsale jugée à risque fracturaire en HVLA compte tenu de l'ostéoporose."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Traiter par manipulation à haute vélocité comme demandé",critical:!0},{id:"b",label:"Surveiller/adapter : traiter par techniques douces en évitant le HVLA sur la zone fragile, avec réévaluation rapprochée",correct:!0,critical:!0},{id:"c",label:"Orienter vers un médecin avant tout traitement, alors qu'aucun red flag n'est présent",critical:!0}],reveal:"Absence de red flag mais contre-indication technique relative (ostéoporose) : la décision est d'adapter le traitement, pas d'orienter ni de refuser tout soin."}],discriminators:["Absence de red flag mais présence d'une contre-indication technique connue (ostéoporose).","Demande explicite de la patiente pour une technique non adaptée à sa situation."],redFlags:["Fragilité osseuse connue rendant une technique habituelle inappropriée sur la zone douloureuse."],differential:["Tassement vertébral ostéoporotique aigu (à exclure si douleur brutale ou disproportionnée).","Dysfonction costo-vertébrale mécanique simple."],pitfalls:["Accéder à la demande du patient (« comme d'habitude ») sans reconsidérer la technique au regard du statut osseux.","Confondre contre-indication technique relative et signal d'alerte nécessitant une orientation médicale."],reasoning:"L'absence de red flag ne signifie pas absence de précaution : la contre-indication relative au HVLA liée à l'ostéoporose impose d'adapter la technique plutôt que d'orienter, la grille de décision distinguant clairement « surveiller/adapter » d'« orienter ».",relatedIds:["5.3-RF-01","5.3-MG-01"],sources:["NCBI-OSTEOPOROSIS-FEMALES","NCBI-HVLA-CONTRA"]},{id:"CASE-42",ue:"5.3",title:"Lombalgie progressive avec amaigrissement : décision d'orienter",neutralTitle:"Lombalgie progressive avec amaigrissement chez une femme de 58 ans",priority:"A+",vignette:"Femme 58 ans, lombalgie progressive depuis 6 semaines, sans traumatisme, avec une perte de poids de 5 kg non expliquée sur 2 mois. Pas de déficit neurologique, pas de fièvre.",objective:"Reconnaître un signal d'alerte non urgent justifiant une orientation médicale sans caractère d'urgence immédiate.",steps:[{kind:"anamnesis",prompt:"Que précises-tu en priorité ?",options:[{id:"a",label:"Caractère involontaire et chronologie de la perte de poids",correct:!0,critical:!0},{id:"b",label:"Antécédents oncologiques personnels ou familiaux",correct:!0,critical:!0},{id:"c",label:"Type de literie utilisée"}],reveal:"Perte de poids involontaire confirmée, pas d'antécédent oncologique connu."},{kind:"exam",prompt:"Que retiens-tu de l'examen ?",options:[{id:"a",label:"Absence de déficit neurologique et de fièvre",correct:!0,critical:!0},{id:"b",label:"Douleur non systématiquement soulagée par le repos",correct:!0,critical:!0},{id:"c",label:"Amplitude lombaire globale"}],reveal:"Pas de déficit neurologique ni de fièvre, douleur progressive peu soulagée par le repos."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Orienter vers le médecin traitant pour investigation du profil oncologique, sans urgence immédiate",correct:!0,critical:!0},{id:"b",label:"Orienter en urgence vitale vers les urgences",critical:!0},{id:"c",label:"Traiter directement sans orientation",critical:!0}],reveal:"Lombalgie progressive avec amaigrissement involontaire, sans déficit ni fièvre : signal d'alerte à investiguer, orientation médicale dans un délai raisonnable, sans caractère d'urgence vitale."}],discriminators:["Amaigrissement involontaire associé à une douleur progressive de plus de 4 à 6 semaines.","Absence de déficit neurologique ou de signe infectieux qui aurait imposé une orientation plus urgente."],redFlags:["Perte de poids involontaire associée à une lombalgie progressive."],differential:["Lombalgie mécanique commune (moins probable compte tenu de l'amaigrissement).","Pathologie inflammatoire rachidienne.","Cause extra-rachidienne (digestive, rénale) à explorer médicalement."],pitfalls:["Sur-réagir en orientant en urgence vitale un signal d'alerte qui relève d'une investigation programmée.","Sous-réagir en traitant directement sans tenir compte du contexte systémique."],reasoning:"Le signal d'alerte (amaigrissement involontaire) est réel mais son évolution sur plusieurs semaines, sans déficit ni fièvre, correspond à la catégorie « orienter » de la grille : une investigation médicale est nécessaire, mais sans caractère d'urgence immédiate.",relatedIds:["5.3-MG-01"],sources:["NICE-NG12","NICE-NG59"]},{id:"CASE-43",ue:"5.3",title:"Mollet chaud et gonflé après immobilisation : décision d'orienter rapidement",neutralTitle:"Mollet chaud et gonflé après immobilisation chez un homme de 66 ans",priority:"A+",vignette:"Homme 66 ans, suivi pour gonalgie, immobilisé 3 semaines après une chirurgie du genou, consulte pour un mollet chaud, gonflé et douloureux apparu depuis 2 jours, sans traumatisme.",objective:"Suspecter une thrombose veineuse profonde et orienter rapidement sans manipuler la zone.",steps:[{kind:"anamnesis",prompt:"Que précises-tu en priorité ?",options:[{id:"a",label:"Facteurs de risque thromboembolique (chirurgie récente, immobilisation)",correct:!0,critical:!0},{id:"b",label:"Présence de douleur thoracique ou de dyspnée associées",correct:!0,critical:!0},{id:"c",label:"Type de chaussage porté depuis la chirurgie"}],reveal:"Chirurgie du genou et immobilisation récentes, pas de douleur thoracique ni de dyspnée."},{kind:"exam",prompt:"Que retiens-tu de l'examen ?",options:[{id:"a",label:"Mollet chaud, gonflé, douloureux, unilatéral",correct:!0,critical:!0},{id:"b",label:"Amplitude de flexion du genou opéré"},{id:"c",label:"Absence de signe respiratoire associé",correct:!0,critical:!0}],reveal:"Mollet unilatéral chaud et gonflé, pas de signe respiratoire associé pour l'instant."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Masser et mobiliser le mollet pour le détendre",critical:!0},{id:"b",label:"Orienter rapidement (le jour même) pour recherche de thrombose veineuse profonde",correct:!0,critical:!0},{id:"c",label:"Surveiller une semaine sans orienter",critical:!0}],reveal:"Mollet chaud, gonflé et douloureux après immobilisation : suspicion de thrombose veineuse profonde. Orientation rapide pour confirmation et traitement, sans manipulation de la zone (risque d'embolisation)."}],discriminators:["Contexte de chirurgie et d'immobilisation récentes, facteur de risque thromboembolique majeur.","Caractère unilatéral et inflammatoire du mollet, sans traumatisme rapporté."],redFlags:["Mollet unilatéral chaud, gonflé et douloureux après immobilisation ou chirurgie récente.","Douleur thoracique ou dyspnée associée, qui signerait une possible embolie pulmonaire et imposerait une urgence vitale."],differential:["Hématome post-chirurgical.","Kyste poplité rompu.","Cellulite du mollet (contexte infectieux, moins probable ici)."],pitfalls:["Masser ou mobiliser une zone suspecte de thrombose, avec un risque de migration embolique.","Sous-estimer le facteur de risque « chirurgie et immobilisation récentes » au profit d'une explication mécanique."],reasoning:"Le contexte périopératoire et l'aspect unilatéral inflammatoire du mollet imposent l'hypothèse de thrombose veineuse profonde. En l'absence de signe respiratoire associé, la décision est une orientation rapide (même jour) plutôt qu'une urgence vitale, mais toute manipulation de la zone est proscrite dans l'intervalle.",relatedIds:["5.3-MG-01","5.3-RF-01"],sources:["NCBI-DVT"]},{id:"CASE-44",ue:"5.3",title:"Douleur abdominale aiguë fébrile : décision d'urgence vitale",neutralTitle:"Douleur abdominale aiguë fébrile chez une femme de 44 ans",priority:"A+",vignette:"Femme 44 ans, douleur abdominale intense d'apparition brutale il y a 4 heures, initialement périombilicale puis localisée en fosse iliaque droite, avec fièvre à 38,5°C et défense abdominale.",objective:"Reconnaître un abdomen chirurgical aigu et interrompre toute prise en charge manuelle.",steps:[{kind:"anamnesis",prompt:"Que précises-tu en priorité ?",options:[{id:"a",label:"Chronologie et migration de la douleur, fièvre associée",correct:!0,critical:!0},{id:"b",label:"Présence de nausées, vomissements, arrêt du transit",correct:!0,critical:!0},{id:"c",label:"Habitudes alimentaires de la semaine"}],reveal:"Douleur migrée en fosse iliaque droite en 4 heures, fièvre, nausées associées."},{kind:"exam",prompt:"Que retiens-tu de l'examen ?",options:[{id:"a",label:"Défense abdominale localisée",correct:!0,critical:!0},{id:"b",label:"Fièvre objectivée à 38,5°C",correct:!0,critical:!0},{id:"c",label:"Tester la mobilité lombaire"}],reveal:"Défense abdominale en fosse iliaque droite confirmée, fièvre objectivée."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Traiter par techniques viscérales abdominales",critical:!0},{id:"b",label:"Interrompre la séance et orienter immédiatement vers les urgences",correct:!0,critical:!0},{id:"c",label:"Orienter dans la semaine vers le médecin traitant",critical:!0}],reveal:"Douleur abdominale migratrice, fièvre et défense localisée évoquent un abdomen chirurgical aigu (ex. appendicite compliquée) : urgence vitale, orientation immédiate vers les urgences, aucune manœuvre abdominale."}],discriminators:["Migration typique de la douleur (périombilicale puis fosse iliaque droite) en quelques heures.","Défense abdominale localisée associée à la fièvre."],redFlags:["Défense abdominale.","Fièvre associée à une douleur abdominale aiguë."],differential:["Douleur digestive fonctionnelle (exclue par la défense et la fièvre).","Colique néphrétique droite (douleur habituellement plus latéralisée, sans défense franche).","Pathologie gynécologique aiguë (à explorer médicalement)."],pitfalls:["Tenter une approche viscérale manuelle devant une douleur abdominale aiguë fébrile avec défense, retardant une prise en charge chirurgicale.","Sous-estimer une défense localisée en l'attribuant à une simple contracture pariétale."],reasoning:"La combinaison douleur migratrice, fièvre et défense abdominale localisée signe un tableau d'abdomen chirurgical aigu : la décision est une urgence vitale, avec interruption immédiate de toute manœuvre et orientation sans délai vers les urgences.",relatedIds:["5.3-MG-01"],sources:["NCBI-ACUTE-ABDOMEN"]},{id:"CASE-45",ue:"5.3",title:"Céphalée fébrile avec raideur de nuque et purpura : décision d'urgence vitale",neutralTitle:"Céphalée fébrile avec raideur de nuque chez un étudiant de 20 ans",priority:"A+",vignette:"Étudiant 20 ans, céphalées intenses depuis 6 heures, fièvre à 39°C, raideur de nuque, photophobie, et apparition d'un discret purpura sur les jambes.",objective:"Reconnaître les signes évocateurs de méningite/sepsis à méningocoque et déclencher un appel d'urgence immédiat.",steps:[{kind:"anamnesis",prompt:"Que précises-tu en priorité ?",options:[{id:"a",label:"Chronologie et sévérité de la céphalée, fièvre associée",correct:!0,critical:!0},{id:"b",label:"Apparition récente de taches cutanées et leur évolution",correct:!0,critical:!0},{id:"c",label:"Qualité du sommeil des derniers jours"}],reveal:"Céphalée sévère depuis 6h, fièvre à 39°C, purpura apparu dans la dernière heure."},{kind:"exam",prompt:"Que recherches-tu à l'examen ?",options:[{id:"a",label:"Raideur de nuque et photophobie",correct:!0,critical:!0},{id:"b",label:"Aspect du purpura : lésions ne s'effaçant pas à la vitropression",correct:!0,critical:!0},{id:"c",label:"Amplitude cervicale en rotation"}],reveal:"Raideur de nuque et photophobie confirmées, purpura ne s'effaçant pas à la vitropression."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Orienter dans la semaine vers le médecin traitant",critical:!0},{id:"b",label:"Appeler immédiatement les urgences, suspicion de méningite/sepsis à méningocoque",correct:!0,critical:!0},{id:"c",label:"Traiter la raideur de nuque par relâchement musculaire",critical:!0}],reveal:"Céphalée fébrile, raideur de nuque, photophobie et purpura ne s'effaçant pas à la vitropression : signes évocateurs de méningite bactérienne/sepsis à méningocoque, urgence vitale, appel immédiat des secours."}],discriminators:["Purpura ne s'effaçant pas à la vitropression, associé à une fièvre et une céphalée sévère.","Triade fièvre, céphalée, raideur de nuque en moins de 24 heures."],redFlags:["Purpura ne s'effaçant pas à la vitropression.","Raideur de nuque fébrile avec photophobie."],differential:["Céphalée de tension sévère (exclue par la fièvre et le purpura).","Migraine avec aura atypique.","Virose fébrile banale (exclue par le purpura et la raideur de nuque)."],pitfalls:["Traiter la raideur de nuque comme une simple contracture cervicale sans tenir compte du contexte fébrile et cutané.","Attendre l'aggravation du purpura avant d'agir, alors que le pronostic dépend de la rapidité de la prise en charge."],reasoning:"La triade fièvre-céphalée-raideur de nuque, associée à un purpura ne s'effaçant pas à la vitropression, impose l'hypothèse de méningite bactérienne ou de sepsis à méningocoque : urgence vitale absolue, appel immédiat des secours sans aucune tentative de traitement manuel.",relatedIds:["5.3-MG-01"],sources:["NICE-NG240","NCBI-PURPURA-FULMINANS"]},{id:"CASE-46",ue:"5.11",title:"Migraineuse sous contraception œstroprogestative demandant une manipulation cervicale",neutralTitle:"Demande de manipulation cervicale chez une femme de 29 ans migraineuse",priority:"A+",vignette:"Femme 29 ans, migraineuse connue, sous contraception œstroprogestative, cervicalgie depuis une entorse cervicale mineure il y a 5 jours. Demande explicitement une « manipulation » cervicale qui l'a soulagée par le passé.",objective:"Appliquer le dépistage IFOMPT des facteurs de risque vasculaire cervical avant de décider de la technique.",steps:[{kind:"anamnesis",prompt:"Quels éléments faut-il rechercher en priorité ?",options:[{id:"a",label:"Cumul de facteurs de risque de dissection artérielle : traumatisme récent, migraine, contraception œstroprogestative",correct:!0,critical:!0},{id:"b",label:"Signes actifs d'ischémie vertébro-basilaire (5D et 3N)",correct:!0,critical:!0},{id:"c",label:"Marque de la contraception utilisée"}],reveal:"Trois facteurs de risque cumulés (traumatisme cervical récent, migraine, contraception œstroprogestative), aucun signe actif d'ischémie retrouvé."},{kind:"exam",prompt:"Que faire des anciens tests positionnels cervicaux soutenus dans cette situation ?",options:[{id:"a",label:"Les considérer comme insuffisants seuls pour autoriser la technique, cadre IFOMPT 2020",correct:!0,critical:!0},{id:"b",label:"Les réaliser comme seule condition suffisante avant manipulation"},{id:"c",label:"Réévaluer l'examen neurologique des membres supérieurs et de la coordination",correct:!0}],reveal:"Examen neurologique normal ; les tests positionnels isolés ne suffisent pas à eux seuls à autoriser la technique compte tenu du cumul de facteurs de risque."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Procéder avec prudence : technique alternative non structurelle et information renforcée sur le risque rare",correct:!0,critical:!0},{id:"b",label:"Réaliser la manipulation demandée sans adaptation",critical:!0},{id:"c",label:"Orienter en urgence sans proposer aucune prise en charge",critical:!0}],reveal:"Le cumul de facteurs de risque sans signe actif conduit à procéder avec prudence : technique alternative non structurelle et information spécifique sur le risque rare de dissection, avec documentation du consentement."}],discriminators:["Cumul de plusieurs facteurs de risque de dissection artérielle sans signe actif d'ischémie.","Absence de signe FAST/5D-3N à l'examen, qui distingue la prudence de l'orientation en urgence."],redFlags:["Apparition en cours de séance d'un signe de la règle des 5D et 3N : arrêt immédiat et orientation en urgence."],differential:["Cervicalgie post-traumatique mécanique simple, sans risque vasculaire particulier.","Migraine isolée sans lien avec le geste cervical envisagé."],pitfalls:["Céder à la demande explicite du patient pour une technique qu'il a appréciée par le passé, sans réévaluer le risque actuel.","Considérer qu'un test positionnel cervical rassurant suffit seul à autoriser la technique."],reasoning:"Le cadre IFOMPT 2020 invite à raisonner sur l'ensemble du tableau (facteurs de risque, présentation, examen) plutôt que sur un test positionnel isolé : ici, l'absence de signe actif permet une prise en charge, mais le cumul de facteurs de risque conduit à la prudence, à une technique alternative et à une information renforcée. L'absence de signe n'exclut pas une pathologie vasculaire.",relatedIds:["5.11-EX-01","5.11-CR-01"],sources:["IFOMPT-CERVICAL2020"]},{id:"CASE-47",ue:"5.11",title:"Patient anticoagulé avec antécédent de tassement vertébral ostéoporotique",neutralTitle:"Lombalgie mécanique chez un homme de 74 ans anticoagulé",priority:"A",vignette:"Homme 74 ans sous anticoagulant oral pour fibrillation auriculaire, antécédent de tassement vertébral L1 ostéoporotique il y a 2 ans, lombalgie mécanique actuelle sans signe neurologique.",objective:"Distinguer contre-indication absolue et relative et adapter la technique en conséquence.",steps:[{kind:"anamnesis",prompt:"Quels éléments pèsent sur la décision technique ?",options:[{id:"a",label:"Anticoagulation orale et antécédent de tassement ostéoporotique",correct:!0,critical:!0},{id:"b",label:"Absence de saignement actif ou de trouble de coagulation non contrôlé",correct:!0},{id:"c",label:"Couleur des selles récentes, sans lien avec la situation"}],reveal:"Anticoagulation stable sans saignement actif, tassement ancien et non évolutif."},{kind:"exam",prompt:"Que rechercher pour qualifier le niveau de contre-indication ?",options:[{id:"a",label:"Signe de fracture ou tassement récent (douleur localisée sévère, aggravation brutale)",correct:!0,critical:!0},{id:"b",label:"Examen neurologique des membres inférieurs",correct:!0},{id:"c",label:"Mobilité de l'épaule controlatérale"}],reveal:"Aucun signe de fracture récente, examen neurologique normal : contre-indications relatives, pas absolues."},{kind:"decision",prompt:"Quelle conduite technique retenir ?",options:[{id:"a",label:"Adapter par une technique de moindre amplitude, non structurelle sur le segment fragilisé",correct:!0,critical:!0},{id:"b",label:"Réaliser une technique à haute vélocité standard sans adaptation",critical:!0},{id:"c",label:"Refuser toute prise en charge et orienter systématiquement",critical:!0}],reveal:"L'anticoagulation stable et l'ostéoporose ancienne sans signe actuel sont des contre-indications relatives : elles imposent une adaptation technique, pas un refus de prise en charge ni une manipulation standard."}],discriminators:["Absence de saignement actif et de signe de tassement récent, qui distingue la contre-indication relative de l'absolue."],redFlags:["Douleur rachidienne d'aggravation brutale ou nouveau déficit neurologique : réévaluer immédiatement le niveau de contre-indication."],differential:["Lombalgie mécanique commune.","Récidive de tassement vertébral ostéoporotique."],pitfalls:["Traiter l'anticoagulation et l'ostéoporose ancienne comme des contre-indications absolues et refuser toute prise en charge par excès de prudence.","Réaliser une technique standard sans adaptation malgré le cumul de facteurs de fragilité."],reasoning:"Le cumul de deux contre-indications relatives (anticoagulation stable, ostéoporose ancienne sans signe actuel) impose une adaptation technique plutôt qu'un refus de traitement ou une manipulation non adaptée.",relatedIds:["5.11-MG-01"],sources:["NCBI-ANTICOAG-SAFETY","NCBI-OSTEOPOROSIS-FEMALES"]},{id:"CASE-48",ue:"5.11",title:"Vertige et diplopie apparaissant en cours de mobilisation cervicale",neutralTitle:"Vertige et vision double en cours de mobilisation cervicale chez une femme de 41 ans",priority:"A+",vignette:"Femme 41 ans, en cours de mobilisation cervicale douce, décrit brutalement un vertige rotatoire associé à une vision double transitoire.",objective:"Réagir immédiatement à l'apparition d'un signe actif d'ischémie vertébro-basilaire en cours de séance.",steps:[{kind:"exam",prompt:"Que faire immédiatement ?",options:[{id:"a",label:"Arrêter immédiatement la technique en cours",correct:!0,critical:!0},{id:"b",label:"Terminer le mouvement en cours avant de réagir",critical:!0},{id:"c",label:"Rechercher les autres signes de la règle des 5D et 3N",correct:!0,critical:!0}],reveal:"Technique arrêtée immédiatement ; dysarthrie légère associée retrouvée à la recherche systématique."},{kind:"decision",prompt:"Quelle orientation retenir ?",options:[{id:"a",label:"Orientation en urgence (appel des secours), suspicion d'ischémie vertébro-basilaire",correct:!0,critical:!0},{id:"b",label:"Reprendre la séance après quelques minutes de repos si les symptômes cèdent",critical:!0},{id:"c",label:"Programmer une consultation médicale dans la semaine",critical:!0}],reveal:"L'association vertige-diplopie-dysarthrie en cours de mobilisation cervicale impose une orientation en urgence, même en cas de régression partielle des symptômes."}],discriminators:["Apparition des symptômes pendant le geste cervical lui-même, contexte causal évident.","Association de plusieurs signes de la règle des 5D et 3N."],redFlags:["Vertige, diplopie et dysarthrie associés en cours de mobilisation cervicale : arrêt et orientation en urgence, sans attendre une régression complète."],differential:["Vertige positionnel bénin isolé, sans signe associé.","Malaise vagal réactionnel à la manipulation."],pitfalls:["Reprendre le traitement après régression partielle des symptômes sans orientation médicale.","Ne rechercher qu'un seul signe (vertige) sans compléter par les autres critères des 5D et 3N."],reasoning:"L'apparition en cours de geste cervical d'un vertige associé à une diplopie et une dysarthrie constitue un signe actif d'ischémie vertébro-basilaire : la conduite impose l'arrêt immédiat et une orientation en urgence, indépendamment de l'évolution ultérieure des symptômes.",relatedIds:["5.11-EX-01","5.11-MG-02","2.9-KN-02"],sources:["IFOMPT-CERVICAL2020"]},{id:"CASE-49",ue:"5.11",title:"Défaut d'information avant une manipulation cervicale : que corriger",neutralTitle:"Interrogation après une manipulation cervicale sans information préalable",priority:"A",vignette:"Un patient ayant reçu une manipulation cervicale sans qu'aucun facteur de risque n'ait été recherché ni qu'aucune information sur les risques n'ait été donnée s'interroge, après coup, sur la légitimité de la démarche.",objective:"Identifier les manquements au processus de consentement éclairé et la correction appropriée.",steps:[{kind:"anamnesis",prompt:"Qu'aurait dû comporter la démarche avant la technique ?",options:[{id:"a",label:"Dépistage des facteurs de risque de dissection artérielle",correct:!0,critical:!0},{id:"b",label:"Information sur la nature de la technique, les bénéfices, les alternatives et le risque rare identifié le cas échéant",correct:!0,critical:!0},{id:"c",label:"Un délai d'attente fixe avant toute manipulation, indépendant du contexte"}],reveal:"Ni dépistage des facteurs de risque ni information spécifique n'avaient été réalisés avant la technique."},{kind:"decision",prompt:"Quelle conduite corrective adopter maintenant ?",options:[{id:"a",label:"Reprendre le dépistage, informer rétroactivement le patient et documenter l'échange",correct:!0,critical:!0},{id:"b",label:"Ne rien faire puisque la technique a déjà été réalisée sans complication",critical:!0},{id:"c",label:"Éviter le sujet pour ne pas inquiéter le patient",critical:!0}],reveal:"Le manquement doit être corrigé activement : dépistage complet, information transparente et documentation, indépendamment de l'absence de complication."}],discriminators:["Absence de dépistage des facteurs de risque avant une technique cervicale à risque.","Absence d'information spécifique et de documentation du consentement."],redFlags:["Réalisation d'une technique cervicale structurelle sans dépistage préalable des facteurs de risque de dissection artérielle : à corriger systématiquement, même rétrospectivement."],differential:["Manipulation réalisée avec information complète et dépistage documenté, situation conforme."],pitfalls:["Considérer qu'une absence de complication rend le défaut d'information et de dépistage sans conséquence."],reasoning:"Un manquement au processus de dépistage et d'information avant une technique cervicale constitue une faute déontologique indépendamment de la survenue d'une complication ; la correction impose un dépistage rétroactif, une information transparente et une documentation rigoureuse.",relatedIds:["5.11-CR-01","5.11-EX-01"],sources:["FSO-DEONTO"]},{id:"CASE-50",ue:"5.11",title:"Aggravation et paresthésies le lendemain d'une technique lombaire",neutralTitle:"Aggravation et fourmillements le lendemain d'une technique lombaire",priority:"A",vignette:"Un patient traité la veille pour une lombalgie mécanique appelle le cabinet en signalant une douleur nettement aggravée et des fourmillements nouveaux dans la jambe.",objective:"Appliquer la conduite à tenir devant un événement indésirable rapporté après une séance.",steps:[{kind:"anamnesis",prompt:"Que faut-il évaluer en priorité par téléphone ?",options:[{id:"a",label:"Caractère et évolution des paresthésies, présence d'un trouble sphinctérien ou d'une anesthésie en selle",correct:!0,critical:!0},{id:"b",label:"Chronologie précise par rapport à la séance",correct:!0},{id:"c",label:"Marque du matelas utilisé la nuit précédente"}],reveal:"Paresthésies limitées à un trajet radiculaire, sans trouble sphinctérien ni anesthésie en selle."},{kind:"decision",prompt:"Quelle conduite adopter ?",options:[{id:"a",label:"Convoquer le patient en consultation rapprochée pour réévaluation clinique complète, sans attendre le prochain rendez-vous prévu",correct:!0,critical:!0},{id:"b",label:"Rassurer par téléphone sans nouvelle évaluation clinique",critical:!0},{id:"c",label:"Orienter systématiquement aux urgences sans réévaluation clinique préalable",critical:!0}],reveal:"En l'absence de trouble sphinctérien, une réévaluation clinique rapprochée en cabinet est appropriée avant d'envisager une orientation ; l'documentation de l'événement est indispensable."}],discriminators:["Absence de trouble sphinctérien ou d'anesthésie en selle, qui distingue la réévaluation rapprochée de l'urgence."],redFlags:["Apparition secondaire d'un trouble sphinctérien ou d'une anesthésie en selle : orientation en urgence immédiate."],differential:["Réaction post-traitement bénigne et transitoire.","Radiculopathie évolutive nécessitant réévaluation."],pitfalls:["Rassurer par téléphone sans nouvelle évaluation clinique en présence de symptômes neurologiques nouveaux.","Ne pas documenter l'appel et la décision prise."],reasoning:"Un symptôme neurologique nouveau après une séance impose une réévaluation clinique rapprochée et une documentation rigoureuse ; l'absence de trouble sphinctérien oriente vers une réévaluation en cabinet plutôt qu'une urgence immédiate.",relatedIds:["5.11-MG-02"],sources:["SAFETYNET-BJGP2019"]},{id:"CASE-51",ue:"5.11",title:"Refus d'orientation malgré un amaigrissement inexpliqué associé à une lombalgie",neutralTitle:"Refus d'orientation chez un homme de 68 ans avec amaigrissement inexpliqué",priority:"A",vignette:"Homme 68 ans, lombalgie depuis 2 mois avec amaigrissement inexpliqué de 6 kg, refuse catégoriquement de consulter son médecin traitant malgré l'explication du motif.",objective:"Appliquer la conduite à tenir face à un refus d'orientation médicale malgré un red flag identifié.",steps:[{kind:"anamnesis",prompt:"Que faut-il vérifier avant d'accepter le refus ?",options:[{id:"a",label:"Que le patient comprend réellement le motif de l'orientation et les conséquences d'un retard",correct:!0,critical:!0},{id:"b",label:"Les raisons concrètes du refus (peur, accès aux soins, expérience antérieure)",correct:!0},{id:"c",label:"La marque de vêtements portés par le patient"}],reveal:"Le patient comprend le motif mais refuse par crainte d'un diagnostic grave ; refus réellement informé."},{kind:"decision",prompt:"Quelle conduite adopter ?",options:[{id:"a",label:"Documenter le refus informé, renforcer le filet de sécurité avec critères concrets, poursuivre le suivi et réoffrir l'orientation",correct:!0,critical:!0},{id:"b",label:"Refuser toute nouvelle séance tant que le patient n'accepte pas l'orientation",critical:!0},{id:"c",label:"Ne plus aborder le sujet pour ne pas indisposer le patient",critical:!0}],reveal:"Le refus informé doit être documenté sans pour autant clore le dossier : le filet de sécurité est renforcé et l'orientation réoffert à chaque séance tant que le motif persiste."}],discriminators:["Refus réellement informé versus incompréhension du motif de l'orientation."],redFlags:["Amaigrissement inexpliqué associé à une lombalgie chez un patient de plus de 50 ans, à réévaluer à chaque séance."],differential:["Lombalgie mécanique commune avec perte de poids volontaire expliquée (à exclure ici, amaigrissement inexpliqué)."],pitfalls:["Considérer un refus initial comme définitif et ne plus reproposer l'orientation aux séances suivantes.","Abandonner le suivi du patient au prétexte de son refus."],reasoning:"Un refus informé n'éteint pas le devoir d'orientation : la documentation rigoureuse, le renforcement du filet de sécurité et la ré-proposition de l'orientation à chaque séance restent la conduite appropriée tant que le red flag persiste.",relatedIds:["5.11-MG-03","5.11-KN-01"],sources:["FSO-DEONTO"]},{id:"CASE-52",ue:"5.12",title:"Effondrement en salle d'attente : arrêt cardio-respiratoire",neutralTitle:"Effondrement soudain en salle d'attente",priority:"A+",vignette:"Un patient s'effondre dans la salle d'attente. Il ne répond pas aux stimulations verbales. Sa respiration est absente, avec quelques gasps espacés.",objective:"Appliquer sans délai la séquence de réanimation cardio-pulmonaire de base.",steps:[{kind:"anamnesis",prompt:"Comment interpréter les gasps espacés observés ?",options:[{id:"a",label:"Comme une respiration agonique, équivalente à une absence de respiration efficace",correct:!0,critical:!0},{id:"b",label:"Comme une respiration normale qui autorise à attendre avant d'agir",critical:!0},{id:"c",label:"Comme un signe qu'il ne s'agit pas d'un arrêt cardiaque",critical:!0}],reveal:"Les gasps agoniques ne sont pas une respiration efficace : ils doivent être traités comme une absence de respiration, en faveur d'un arrêt cardio-respiratoire."},{kind:"decision",prompt:"Quelle séquence appliquer ?",options:[{id:"a",label:"Alerter les secours immédiatement (haut-parleur) puis débuter les compressions thoraciques 30:2 et utiliser un DAE dès disponibilité",correct:!0,critical:!0},{id:"b",label:"Attendre l'arrivée des secours sans débuter la réanimation",critical:!0},{id:"c",label:"Réaliser uniquement les insufflations sans compressions thoraciques",critical:!0}],reveal:"L'alerte immédiate suivie sans délai des compressions thoraciques 30:2 et de l'utilisation du DAE dès qu'il est disponible constitue la conduite correcte."}],discriminators:["Reconnaissance de la respiration agonique comme équivalente à une absence de respiration."],redFlags:["Toute respiration anormale chez un patient inconscient doit faire suspecter un arrêt cardio-respiratoire."],differential:["Syncope simple avec reprise rapide de conscience et respiration normale, à exclure ici par l'absence de réponse et de respiration efficace."],pitfalls:["Confondre les gasps agoniques avec une respiration normale et différer l'alerte et la réanimation.","Retarder l'utilisation du DAE en attendant son arrivée pour débuter les compressions."],reasoning:"La respiration agonique chez un patient inconscient doit être traitée comme une absence de respiration : la séquence alerte immédiate, compressions thoraciques 30:2 et défibrillation dès disponibilité doit être appliquée sans délai.",relatedIds:["5.12-MG-01"],sources:["ERC-BLS2021"]},{id:"CASE-53",ue:"5.12",title:"Asymétrie faciale et trouble de la parole en cours de consultation",neutralTitle:"Trouble brutal de la parole et du visage chez un patient de 61 ans",priority:"A+",vignette:"En cours d'anamnèse, un patient de 61 ans présente brutalement un affaissement de la commissure labiale droite et un discours devenu incompréhensible.",objective:"Appliquer le score FAST et la conduite à tenir devant un AVC suspecté.",steps:[{kind:"exam",prompt:"Que rechercher immédiatement ?",options:[{id:"a",label:"Les autres critères FAST : faiblesse d'un bras, heure de début des symptômes",correct:!0,critical:!0},{id:"b",label:"Un antécédent de migraine chez ce patient"},{id:"c",label:"Une éventuelle amélioration en attendant quelques minutes",critical:!0}],reveal:"Faiblesse du bras droit associée retrouvée ; début des symptômes il y a 20 minutes."},{kind:"decision",prompt:"Quelle conduite adopter ?",options:[{id:"a",label:"Appeler les secours immédiatement en précisant l'heure de début des symptômes",correct:!0,critical:!0},{id:"b",label:"Attendre une éventuelle régression spontanée avant d'appeler",critical:!0},{id:"c",label:"Proposer une technique de mobilisation cervicale pour soulager les tensions",critical:!0}],reveal:"Le score FAST positif avec heure de début connue impose un appel immédiat aux secours, sans attendre de régression ni tenter de traiter."}],discriminators:["Association de plusieurs critères FAST d'apparition brutale."],redFlags:["Tout déficit neurologique focal brutal, même transitoire, impose une alerte immédiate."],differential:["Paralysie faciale périphérique isolée (sans atteinte du bras ni du langage), à réévaluer mais moins probable ici du fait du tableau complet."],pitfalls:["Attendre une régression spontanée avant d'alerter, ce qui retarde l'accès à un traitement de reperfusion temps-dépendant.","Tenter une prise en charge ostéopathique avant l'évaluation médicale."],reasoning:"Le tableau associant asymétrie faciale, faiblesse d'un bras et trouble du langage d'apparition brutale constitue un score FAST positif : l'heure de début doit être notée précisément et les secours alertés sans délai.",relatedIds:["5.12-RF-01"],sources:["NICE-NG128"]},{id:"CASE-54",ue:"5.12",title:"Urticaire et gêne respiratoire après application d'une huile essentielle",neutralTitle:"Réaction cutanée et respiratoire après application d'une huile essentielle",priority:"A+",vignette:"Quelques minutes après l'application d'une huile essentielle en massage, une patiente développe une urticaire généralisée, un œdème des lèvres et une gêne respiratoire avec sibilants audibles.",objective:"Reconnaître une anaphylaxie et appliquer la conduite à tenir en urgence.",steps:[{kind:"anamnesis",prompt:"Quels éléments confirment la gravité du tableau ?",options:[{id:"a",label:"Association d'une atteinte cutanéo-muqueuse et d'une atteinte respiratoire d'apparition rapide",correct:!0,critical:!0},{id:"b",label:"Délai de quelques minutes entre l'exposition et les symptômes",correct:!0},{id:"c",label:"Antécédent d'allergie alimentaire sans lien avec le produit appliqué"}],reveal:"Tableau compatible avec une anaphylaxie de grade sévère (atteinte respiratoire associée)."},{kind:"decision",prompt:"Quelle conduite immédiate adopter ?",options:[{id:"a",label:"Appeler les secours et administrer l'adrénaline intramusculaire sans délai si disponible",correct:!0,critical:!0},{id:"b",label:"Attendre l'évolution avant d'appeler les secours",critical:!0},{id:"c",label:"Administrer uniquement un antihistaminique et surveiller",critical:!0}],reveal:"L'adrénaline intramusculaire est le traitement de première intention devant une anaphylaxie avec atteinte respiratoire ; l'appel aux secours est immédiat, sans attendre l'évolution."}],discriminators:["Atteinte respiratoire associée à l'atteinte cutanéo-muqueuse, qui signe la gravité et la nécessité de l'adrénaline."],redFlags:["Toute détresse respiratoire ou signe cardiovasculaire associé à une réaction cutanée après exposition à un allergène potentiel."],differential:["Urticaire allergique isolée sans atteinte respiratoire ni cardiovasculaire, de gravité moindre."],pitfalls:["Traiter uniquement par antihistaminique une anaphylaxie avec atteinte respiratoire, retardant le traitement de première intention.","Attendre l'aggravation avant d'appeler les secours."],reasoning:"L'association rapide d'une atteinte cutanéo-muqueuse et d'une détresse respiratoire après exposition à un allergène définit une anaphylaxie sévère : l'adrénaline intramusculaire immédiate et l'appel aux secours sont la conduite prioritaire.",relatedIds:["5.12-RF-02"],sources:["WAO-ANAPHYLAXIS20"]},{id:"CASE-55",ue:"5.12",title:"Aggravation en cours de suivi vers une rétention urinaire",neutralTitle:"Aggravation en cours de suivi chez un patient traité pour lombosciatique",priority:"A+",vignette:"Un patient suivi depuis 3 séances pour une lombosciatique signale, à la 4e séance, une difficulté nouvelle à uriner apparue depuis la veille, avec une sciatique désormais bilatérale.",objective:"Reconnaître un syndrome de la queue de cheval évolutif au cours du suivi et agir sans délai.",steps:[{kind:"anamnesis",prompt:"Quels éléments rechercher activement ?",options:[{id:"a",label:"Anesthésie en selle, incontinence fécale, dysfonction sexuelle récente",correct:!0,critical:!0},{id:"b",label:"Caractère bilatéral et évolutif de la sciatique",correct:!0,critical:!0},{id:"c",label:"Amélioration ressentie lors des séances précédentes"}],reveal:"Anesthésie en selle débutante confirmée, sciatique bilatérale d'aggravation rapide."},{kind:"decision",prompt:"Quelle conduite adopter ?",options:[{id:"a",label:"Orientation immédiate aux urgences, sans attendre ni compléter le traitement en cours",correct:!0,critical:!0},{id:"b",label:"Poursuivre le traitement ostéopathique déjà engagé avec bonne évolution antérieure",critical:!0},{id:"c",label:"Programmer une consultation médicale dans les prochains jours",critical:!0}],reveal:"L'apparition d'une rétention urinaire, d'une anesthésie en selle et d'une sciatique bilatérale évolutive impose une orientation immédiate aux urgences, quel que soit le bénéfice perçu du traitement en cours."}],discriminators:["Apparition secondaire de signes de la queue de cheval au cours d'un suivi jusque-là favorable."],redFlags:["Toute apparition secondaire de trouble sphinctérien ou d'anesthésie en selle en cours de suivi, même après une évolution initialement favorable."],differential:["Lombosciatique mécanique en cours d'amélioration, écartée ici par l'apparition de signes de la queue de cheval."],pitfalls:["Poursuivre un traitement en cours par confiance dans l'évolution antérieure favorable, malgré l'apparition d'un red flag franc.","Différer l'orientation pour compléter le traitement engagé."],reasoning:"Une évolution favorable antérieure ne protège pas contre l'apparition secondaire d'un syndrome de la queue de cheval : tout nouveau signe sphinctérien ou d'anesthésie en selle impose une orientation immédiate aux urgences.",relatedIds:["5.12-RF-03","5.3-KN-01","1.9-KN-09","2.8-DX-03"],sources:["NCBI-CAUDA-EQUINA"]},{id:"CASE-56",ue:"5.12",title:"Malaise après une technique chez un patient anxieux",neutralTitle:"Malaise après une technique chez un patient anxieux",priority:"A",vignette:"Un patient anxieux à l'idée d'une technique cervicale présente, juste après le geste, une pâleur, des sueurs et une sensation de malaise, avec récupération rapide en position allongée.",objective:"Distinguer un malaise vagal réactionnel d'une urgence cardiaque et agir en conséquence.",steps:[{kind:"exam",prompt:"Quels éléments orientent vers un malaise vagal plutôt qu'une urgence cardiaque ?",options:[{id:"a",label:"Contexte anxiogène évident, prodrome typique, récupération rapide et complète en position allongée",correct:!0,critical:!0},{id:"b",label:"Absence de douleur thoracique et de palpitations associées",correct:!0},{id:"c",label:"Antécédent familial de cardiopathie, sans lien avec l'épisode actuel"}],reveal:"Tableau typique de malaise vagal réactionnel : contexte anxiogène, prodrome, récupération rapide et complète."},{kind:"decision",prompt:"Quelle conduite adopter ?",options:[{id:"a",label:"Allonger jambes surélevées, rassurer, surveiller la récupération avant de reprendre",correct:!0,critical:!0},{id:"b",label:"Appeler les secours d'emblée sans réévaluation clinique",critical:!0},{id:"c",label:"Remettre le patient debout rapidement pour vérifier sa récupération",critical:!0}],reveal:"Le tableau typique de malaise vagal autorise une prise en charge simple (position allongée, réassurance, surveillance) sans appel systématique aux secours, à condition d'une récupération complète."}],discriminators:["Récupération rapide et complète en position allongée, absence de douleur thoracique ou de palpitations."],redFlags:["Récupération incomplète, douleur thoracique associée ou récidive du malaise : réévaluer comme une possible urgence cardiaque."],differential:["Urgence cardiaque (trouble du rythme, syndrome coronarien aigu), écartée ici par la récupération complète et le contexte typique."],pitfalls:["Remettre le patient debout précocement avant confirmation d'une récupération complète, avec risque de récidive du malaise.","Banaliser un malaise atypique (récupération incomplète) en le qualifiant à tort de vagal."],reasoning:"Le contexte anxiogène, le prodrome typique et la récupération rapide et complète en position allongée signent un malaise vagal réactionnel bénin, ne nécessitant pas d'appel aux secours mais une surveillance avant reprise de l'activité.",relatedIds:["5.12-MG-02","2.6-RF-07"],sources:["NICE-CG95"]},{id:"CASE-57",ue:"5.12",title:"Trouble de conscience brutal chez un patient diabétique connu",neutralTitle:"Trouble de conscience brutal chez un patient diabétique connu",priority:"A",vignette:"Un patient diabétique de type 1 connu présente en salle d'attente une confusion brutale, une sudation profuse et un tremblement, sans déficit focal net.",objective:"Distinguer une hypoglycémie sévère d'un AVC chez un patient diabétique et agir rapidement.",steps:[{kind:"anamnesis",prompt:"Quel élément vérifier en priorité chez ce patient diabétique connu ?",options:[{id:"a",label:"La glycémie capillaire si un lecteur est disponible, et l'horaire du dernier repas/insuline",correct:!0,critical:!0},{id:"b",label:"La présence d'une asymétrie faciale ou d'un déficit moteur focal (score FAST)",correct:!0,critical:!0},{id:"c",label:"La marque du dernier repas consommé"}],reveal:"Glycémie capillaire basse, absence de déficit focal franc à l'examen : tableau évocateur d'une hypoglycémie plutôt que d'un AVC."},{kind:"decision",prompt:"Quelle conduite adopter ?",options:[{id:"a",label:"Resucrage immédiat si conscient et capable de déglutir, avec surveillance de la récupération",correct:!0,critical:!0},{id:"b",label:"Appeler les secours uniquement, sans tenter de resucrage",critical:!0},{id:"c",label:"Considérer d'emblée un AVC et orienter sans vérifier la glycémie",critical:!0}],reveal:"Une hypoglycémie chez un patient conscient capable de déglutir se traite par resucrage immédiat, avec surveillance ; un déficit focal net ou une absence d'amélioration réoriente vers la suspicion d'AVC et l'appel aux secours."}],discriminators:["Glycémie capillaire basse et absence de déficit focal, contexte de diabète connu."],redFlags:["Absence d'amélioration après resucrage ou apparition d'un déficit focal franc : réorienter en urgence comme un AVC suspecté."],differential:["AVC ischémique, à réévoquer en l'absence d'amélioration après resucrage ou devant un déficit focal net."],pitfalls:["Traiter d'emblée comme un AVC sans vérifier une cause réversible et rapidement traitable comme l'hypoglycémie chez un patient diabétique connu.","Négliger la surveillance après resucrage en l'absence d'amélioration franche."],reasoning:"Chez un patient diabétique connu présentant une confusion brutale sans déficit focal net, la vérification de la glycémie capillaire oriente rapidement vers une cause réversible ; l'absence d'amélioration après resucrage ou un déficit focal impose de réévoquer un AVC et d'alerter les secours.",relatedIds:["5.12-RF-01"],sources:["NCBI-HYPOGLYCEMIA"]},{id:"CASE-58",ue:"4.3",title:"Lombalgie capricieuse chez un homme de 28 ans : deux hypothèses concurrentes",neutralTitle:"Lombalgie capricieuse chez un homme de 28 ans",priority:"A",vignette:"Homme 28 ans, lombalgie basse évoluant depuis 4 mois, d'installation progressive sans traumatisme. Pas de trouble neurologique. Il décrit une raideur matinale qu'il attribue au sommeil.",objective:"Maintenir deux hypothèses concurrentes ouvertes (lombalgie mécanique commune vs rachialgie inflammatoire débutante) et les trancher par un recueil ciblé plutôt que par la première impression.",steps:[{kind:"anamnesis",prompt:"Sur ces seuls éléments, que peux-tu conclure ?",options:[{id:"a",label:"Rien de définitif : l'âge, la chronicité et la raideur matinale sont compatibles avec plusieurs hypothèses, il faut préciser la raideur",correct:!0,critical:!0},{id:"b",label:"C'est certainement une lombalgie mécanique commune, la raideur matinale est banale après le sommeil",critical:!0},{id:"c",label:"L'absence de traumatisme exclut d'emblée toute cause inflammatoire"}],reveal:"À ce stade, les données sont insuffisantes pour trancher : la raideur matinale mérite d'être précisée (durée, effet du mouvement) avant toute conclusion."},{kind:"exam",prompt:"Que précises-tu en priorité sur cette raideur matinale ?",options:[{id:"a",label:"Sa durée précise et si elle s'améliore avec le mouvement ou au contraire avec le repos",correct:!0,critical:!0},{id:"b",label:"Si elle est present depuis plus de 3 mois avant l'âge de 40 ans",correct:!0,critical:!0},{id:"c",label:"La marque du matelas utilisé"}],reveal:"Raideur matinale de plus de 60 minutes, qui s'améliore nettement avec l'activité et ne s'améliore pas avec le repos ; début avant 40 ans, évolution insidieuse sur plus de 3 mois."},{kind:"anamnesis",prompt:"Ce nouvel élément change-t-il les hypothèses en présence ?",options:[{id:"a",label:"Oui : ce profil (âge < 40 ans, début insidieux, amélioration à l'exercice, absence d'amélioration au repos, raideur matinale prolongée) évoque une rachialgie inflammatoire débutante, à réévaluer activement",correct:!0,critical:!0},{id:"b",label:"Rechercher aussi une douleur fessière alternante et une atteinte articulaire périphérique associée (talalgie, arthrite)",correct:!0,critical:!0},{id:"c",label:"Non, une raideur matinale reste toujours banale quelle que soit sa durée"}],reveal:"Douleur fessière alternante rapportée les derniers mois, pas d'arthrite périphérique actuellement. Le profil reste compatible avec une origine inflammatoire débutante à investiguer."},{kind:"exam",prompt:"Que retiens-tu de l'examen clinique complémentaire ?",options:[{id:"a",label:"Limitation de la mobilité rachidienne globale, sans déficit neurologique ni red flag de gravité immédiate",correct:!0,critical:!0},{id:"b",label:"Absence de fièvre, d'amaigrissement et de trouble sphinctérien",correct:!0,critical:!0},{id:"c",label:"Force musculaire cotée isolément au membre supérieur"}],reveal:"Mobilité rachidienne globalement limitée, examen neurologique normal, pas de signe systémique de gravité immédiate."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Orienter vers le médecin traitant pour bilan d'un tableau évocateur de rachialgie inflammatoire débutante, sans caractère d'urgence, en expliquant le raisonnement au patient",correct:!0,critical:!0},{id:"b",label:"Traiter directement comme une lombalgie mécanique commune sans orientation, car il n'y a aucun red flag de gravité immédiate",critical:!0},{id:"c",label:"Orienter en urgence vers les urgences hospitalières",critical:!0}],reveal:"Le profil clinique (critères d'allure inflammatoire, âge, chronicité, atteinte fessière alternante) doit être investigué médicalement pour confirmer ou infirmer l'hypothèse, même en l'absence de tout red flag de gravité immédiate : ce n'est ni une urgence, ni une simple lombalgie mécanique à traiter sans autre avis."}],discriminators:["Raideur matinale de plus de 60 minutes améliorée par l'exercice et non par le repos, chez un patient de moins de 40 ans avec évolution insidieuse de plus de 3 mois.","Douleur fessière alternante associée, évocatrice d'une atteinte sacro-iliaque bilatérale ou alternante plutôt que d'une lombalgie mécanique isolée.","Absence de tout signe systémique ou neurologique de gravité immédiate, ce qui explique l'absence d'urgence malgré la nécessité d'un avis médical."],redFlags:["Aucun red flag de gravité immédiate identifié dans ce cas : la décision d'orienter repose ici sur un faisceau d'arguments évocateurs d'une pathologie inflammatoire, pas sur un signal d'alerte unique."],differential:["Rachialgie inflammatoire débutante (spondyloarthrite axiale), hypothèse retenue à investiguer.","Lombalgie mécanique commune, hypothèse initiale, affaiblie par le profil de la raideur matinale.","Dysfonction sacro-iliaque mécanique isolée."],pitfalls:["Conclure trop vite à une lombalgie mécanique banale sur la seule absence de traumatisme, sans caractériser précisément la raideur matinale.","Attendre l'apparition d'un red flag franc avant d'orienter, alors qu'un faisceau d'arguments cohérent suffit à justifier un avis médical programmé."],reasoning:"Ce cas illustre un raisonnement hypothético-déductif avec deux hypothèses concurrentes maintenues ouvertes jusqu'à un recueil ciblé : la caractérisation précise de la raideur matinale (durée, effet de l'exercice et du repos) fait basculer la probabilité vers une origine inflammatoire débutante, ce qui justifie une orientation programmée malgré l'absence de tout red flag de gravité immédiate.",relatedIds:["4.3-KN-01","4.3-KN-03","4.3-DX-02"],sources:["PUBMED-ASAS-IBP","JONES-CRM1992"]},{id:"CASE-59",ue:"5.3",title:"Cervicalgie subaiguë avec céphalées occipitales : décision de traiter après dépistage vasculaire",neutralTitle:"Cervicalgie avec céphalées occipitales chez une femme de 41 ans",priority:"A",vignette:"Femme 41 ans, cervicalgie basse-nuque subaiguë depuis 3 semaines, associée à des céphalées occipitales unilatérales du même côté, sans traumatisme récent. Une technique cervicale est envisagée.",objective:"Discriminer une céphalée cervicogénique bénigne d'un signal d'alerte, puis dépister le risque vasculaire cervical avant toute technique, sans surtraiter une présentation par ailleurs fréquente.",steps:[{kind:"anamnesis",prompt:"Que précises-tu pour caractériser la céphalée ?",options:[{id:"a",label:"Son mode d'apparition (brutal en coup de tonnerre ou progressif) et son caractère habituel ou inhabituel pour la patiente",correct:!0,critical:!0},{id:"b",label:"Le lien avec les mouvements et positions cervicales",correct:!0,critical:!0},{id:"c",label:"La marque du traversin utilisé"}],reveal:"Céphalée progressive, non inhabituelle en intensité, clairement majorée par certains mouvements et positions cervicales prolongées."},{kind:"anamnesis",prompt:"Une technique cervicale étant envisagée, que dépistes-tu avant tout geste ?",options:[{id:"a",label:"Les facteurs de risque de dissection artérielle cervicale (traumatisme récent, migraine, tabac, contraception œstroprogestative, trouble du tissu conjonctif)",correct:!0,critical:!0},{id:"b",label:"Les signes d'ischémie vertébro-basilaire actifs (vertige, diplopie, dysarthrie, dysphagie, drop attack)",correct:!0,critical:!0},{id:"c",label:"La couleur habituelle du teint de la patiente"}],reveal:"Aucun facteur de risque vasculaire identifié, aucun signe d'ischémie vertébro-basilaire actif."},{kind:"exam",prompt:"Que confirmes-tu à l'examen mécanique ?",options:[{id:"a",label:"Reproduction de la céphalée par la palpation ou la mobilisation cervicale haute du côté symptomatique",correct:!0,critical:!0},{id:"b",label:"Examen neurologique des membres supérieurs normal",correct:!0,critical:!0},{id:"c",label:"Souplesse isolée des ischio-jambiers"}],reveal:"Céphalée reproduite par la mobilisation cervicale haute homolatérale, examen neurologique normal."},{kind:"decision",prompt:"Quelle décision retenir ?",options:[{id:"a",label:"Traiter directement, dépistage vasculaire négatif et présentation mécaniquement cohérente, avec filet de sécurité explicite",correct:!0,critical:!0},{id:"b",label:"Orienter systématiquement vers un médecin avant tout traitement en raison de la céphalée",critical:!0},{id:"c",label:"Différer toute prise en charge par excès de prudence malgré un dépistage négatif",critical:!0}],reveal:"Le dépistage vasculaire négatif associé à une reproduction mécanique cohérente de la céphalée par l'examen cervical autorise une prise en charge directe, avec un filet de sécurité portant spécifiquement sur les signes d'ischémie vertébro-basilaire."}],discriminators:["Céphalée progressive et habituelle en intensité, nettement reproduite par la mobilisation cervicale mécanique, plutôt que brutale ou inhabituelle.","Dépistage vasculaire cervical (facteurs de risque et signes actifs) strictement négatif avant toute décision de traiter."],redFlags:["Céphalée en coup de tonnerre, inhabituelle ou d'intensité maximale d'emblée : aurait imposé une orientation en urgence plutôt qu'un traitement direct.","Tout signe d'ischémie vertébro-basilaire actif (vertige, diplopie, dysarthrie) aurait imposé de différer la technique et d'orienter."],differential:["Céphalée cervicogénique mécanique, retenue ici.","Céphalée primaire (migraine, céphalée de tension) sans composante cervicale mécanique dominante.","Signe précoce d'une atteinte vasculaire cervicale, écarté par le dépistage négatif."],pitfalls:["Traiter une céphalée cervicale sans dépistage vasculaire systématique au seul motif qu'elle paraît mécanique.","Orienter par excès de prudence une céphalée cervicogénique typique alors que le dépistage est négatif et la reproduction mécanique cohérente."],reasoning:"La présentation est mécaniquement cohérente (céphalée reproduite par la mobilisation cervicale) et le dépistage vasculaire selon le cadre IFOMPT ne retrouve pas d'argument pour une hypothèse vasculaire (ce qui ne l'exclut pas totalement : l'évolution reste surveillée) : ces deux éléments, évalués avant toute décision, permettent de traiter directement une présentation par ailleurs fréquente, sans céder ni au sous-diagnostic ni à l'orientation systématique par excès de prudence.",relatedIds:["5.3-MG-01","5.11-EX-01"],sources:["IFOMPT-CERVICAL2020","NICE-NG59"]},{id:"CASE-60",ue:"5.11",title:"Cervicalgie mécanique chez un patient anticoagulé et ostéoporotique demandant une manipulation",neutralTitle:"Cervicalgie mécanique chez un homme de 67 ans anticoagulé et ostéoporotique",priority:"A+",vignette:"Homme 67 ans, fibrillation auriculaire sous anticoagulant oral, ostéoporose connue sans antécédent de fracture ni tassement. Cervicalgie mécanique typique depuis 10 jours. Il demande explicitement « la manipulation qui craque » qu'il avait reçue il y a plusieurs années.",objective:"Prioriser plusieurs comorbidités relatives, dépister le risque vasculaire, choisir une technique adaptée et documenter un consentement éclairé, sans renoncer par excès de prudence ni céder à la demande du patient sans évaluation.",steps:[{kind:"anamnesis",prompt:"Sur la seule demande initiale du patient, que fais-tu ?",options:[{id:"a",label:"Tu recueilles d'abord une anamnèse complète avant de discuter du choix de technique, sans t'engager sur la demande initiale",correct:!0,critical:!0},{id:"b",label:"Tu acceptes de reproduire la technique demandée, le patient l'ayant déjà reçue sans problème par le passé",critical:!0},{id:"c",label:"Tu refuses d'emblée toute technique structurelle sans évaluation, par principe de précaution",critical:!0}],reveal:"Ni acceptation ni refus immédiat ne sont justifiés avant un recueil complet : l'anamnèse et l'examen doivent précéder toute décision de technique."},{kind:"anamnesis",prompt:"Que précises-tu sur ses comorbidités ?",options:[{id:"a",label:"Le type d'anticoagulant, l'observance, et l'absence de signe de saignement actif",correct:!0,critical:!0},{id:"b",label:"L'ancienneté de l'ostéoporose et l'absence de fracture ou de tassement vertébral connu",correct:!0,critical:!0},{id:"c",label:"La marque de son oreiller"}],reveal:"Anticoagulant bien conduit, sans signe de saignement actif ; ostéoporose connue mais sans fracture ni tassement, densitométrie ancienne non aggravée récemment."},{kind:"exam",prompt:"Une technique cervicale étant envisagée, que dépistes-tu et que confirmes-tu à l'examen ?",options:[{id:"a",label:"Les facteurs de risque et signes actifs de dissection artérielle cervicale (cadre IFOMPT)",correct:!0,critical:!0},{id:"b",label:"La reproduction mécanique cohérente de la douleur, examen neurologique normal",correct:!0,critical:!0},{id:"c",label:"La force de préhension isolée de la main dominante"}],reveal:"Dépistage vasculaire négatif, douleur reproduite mécaniquement, examen neurologique normal."},{kind:"decision",prompt:"Aucune contre-indication absolue n'est identifiée sur la zone. Quelle conduite retenir sur le choix de la technique ?",options:[{id:"a",label:"Pondérer les deux facteurs relatifs (anticoagulation sans saignement actif, ostéoporose modérée sans fracture) et choisir une technique de moindre amplitude plutôt que la technique à haute vélocité initialement demandée",correct:!0,critical:!0},{id:"b",label:"Renoncer à toute prise en charge manuelle et orienter systématiquement, le cumul des deux facteurs relatifs suffisant à interdire toute technique",critical:!0},{id:"c",label:"Réaliser la technique à haute vélocité demandée telle quelle, aucun facteur n'étant à lui seul une contre-indication absolue",critical:!0}],reveal:"En l'absence de contre-indication absolue, les facteurs relatifs se pondèrent entre eux pour adapter la technique (moindre amplitude, non structurelle) plutôt que pour l'exclure totalement ou l'appliquer sans adaptation."},{kind:"decision",prompt:"Comment conclus-tu la séance sur le plan de l'information ?",options:[{id:"a",label:"Tu expliques au patient pourquoi la technique diffère de celle demandée, recueille son consentement éclairé pour la technique adaptée, et documentes le raisonnement dans le dossier",correct:!0,critical:!0},{id:"b",label:"Tu réalises la technique adaptée sans en expliquer la raison, pour ne pas inquiéter le patient",critical:!0},{id:"c",label:"Tu notes seulement que le patient a été traité, sans détailler les facteurs pesés",critical:!0}],reveal:"L'information du patient sur le raisonnement, le consentement éclairé pour la technique effectivement réalisée, et la traçabilité écrite des facteurs pesés font partie intégrante d'une conduite à tenir appropriée."}],discriminators:["Deux facteurs relatifs présents simultanément (anticoagulation sans saignement actif, ostéoporose modérée sans fracture), aucun n'étant à lui seul une contre-indication absolue.","Dépistage vasculaire cervical négatif malgré la demande explicite d'une technique à haute vélocité par le patient.","Écart entre la technique demandée par le patient et la technique cliniquement appropriée, nécessitant une explication et un consentement spécifiques."],redFlags:["Tout signe de saignement actif sous anticoagulant ou tout antécédent récent de fracture/tassement aurait constitué une contre-indication à réévaluer avant toute technique.","Tout signe actif d'ischémie vertébro-basilaire au dépistage aurait imposé de différer la technique indépendamment des autres facteurs."],differential:["Cervicalgie mécanique commune avec comorbidités relatives à adapter, retenue ici.","Contre-indication absolue si un des facteurs avait été plus sévère (saignement actif, fracture récente).","Risque vasculaire cervical, écarté par le dépistage négatif."],pitfalls:["Céder à la demande explicite du patient pour une technique précédemment reçue sans réévaluer les comorbidités actuelles.","Additionner mentalement deux facteurs relatifs jusqu'à un refus systématique de toute prise en charge, privant le patient d'un bénéfice réel accessible par une technique adaptée.","Adapter la technique sans expliquer au patient pourquoi, ce qui nuit à la relation de confiance et au consentement éclairé."],reasoning:"Aucun facteur présent n'est une contre-indication absolue, mais deux facteurs relatifs coexistent : la conduite appropriée les pondère ensemble pour adapter la technique plutôt que de renoncer à toute prise en charge ou d'ignorer le risque cumulé, et complète la décision par une information et une traçabilité explicites, conformément au cadre déontologique.",relatedIds:["5.11-MG-04","5.11-MG-01","5.11-CR-02","5.11-EX-01"],sources:["NCBI-ANTICOAG-SAFETY","NCBI-SECONDARY-OSTEOPOROSIS","IFOMPT-CERVICAL2020","FSO-DEONTO"]},{id:"CASE-61",ue:"5.12",title:"Fatigue et inconfort épigastrique chez un patient diabétique âgé : de l'apparence bénigne à l'urgence cardiaque",neutralTitle:"Fatigue et inconfort épigastrique chez un homme de 74 ans diabétique",priority:"A+",vignette:"Homme 74 ans, diabétique de type 2 et hypertendu connu, consulte pour une fatigue inhabituelle depuis la veille avec un inconfort épigastrique modéré. Il attribue cela à un repas copieux. Pas de douleur thoracique rapportée.",objective:"Ne pas écarter une cause cardiaque du seul fait de l'absence de douleur thoracique typique chez un patient à risque, et prioriser l'orientation en urgence dès que les éléments s'accumulent.",steps:[{kind:"anamnesis",prompt:"Sur ces seuls éléments, que retiens-tu ?",options:[{id:"a",label:"Le terrain (diabète, hypertension, âge) impose de garder une cause cardiaque parmi les hypothèses malgré l'absence de douleur thoracique",correct:!0,critical:!0},{id:"b",label:"L'absence de douleur thoracique rend une cause digestive bénigne la plus probable, sans autre vérification",critical:!0},{id:"c",label:"Rien à faire de particulier, il s'agit probablement d'une fatigue liée au repas comme le patient le pense",critical:!0}],reveal:"Chez un patient âgé et diabétique, l'absence de douleur thoracique ne permet pas d'écarter une cause cardiaque : la neuropathie autonome peut masquer la douleur typique."},{kind:"anamnesis",prompt:"Que précises-tu ensuite ?",options:[{id:"a",label:"L'évolution du symptôme à l'effort et au repos, et l'apparition d'une dyspnée associée",correct:!0,critical:!0},{id:"b",label:"Les antécédents cardiovasculaires familiaux et personnels, le tabagisme",correct:!0,critical:!0},{id:"c",label:"Le contenu exact du repas suspecté"}],reveal:"Le patient rapporte, en y repensant, un léger essoufflement en montant les escaliers ce matin, inhabituel pour lui. Antécédent familial d'infarctus chez son frère. Pas de tabagisme."},{kind:"exam",prompt:"Que recherches-tu à l'examen ?",options:[{id:"a",label:"Fréquence cardiaque, pression artérielle, coloration et sueurs, signes de détresse",correct:!0,critical:!0},{id:"b",label:"Reproduction ou non de l'inconfort par la palpation abdominale ou la mobilisation",correct:!0,critical:!0},{id:"c",label:"Amplitude articulaire isolée de l'épaule"}],reveal:"Discrète tachycardie, pâleur légère, sueurs discrètes non expliquées par la température ambiante. L'inconfort n'est pas reproduit par la palpation abdominale ni par la mobilisation."},{kind:"decision",prompt:"Quelle décision retenir à ce stade ?",options:[{id:"a",label:"Suspecter une cause cardiaque devant ce faisceau d'arguments (terrain, dyspnée d'effort inhabituelle, signes discrets de mauvaise tolérance, inconfort non reproduit mécaniquement) et orienter en urgence",correct:!0,critical:!0},{id:"b",label:"Rassurer le patient et proposer une simple surveillance à domicile avec reconsultation si aggravation",critical:!0},{id:"c",label:"Traiter l'inconfort comme une dysfonction ostéopathique digestive fonctionnelle",critical:!0}],reveal:"Le faisceau d'arguments (terrain à risque, symptôme atypique mais évolutif, signes discrets de mauvaise tolérance, absence de reproduction mécanique) impose une orientation en urgence pour explorer une cause cardiaque, sans attendre l'apparition d'une douleur thoracique franche."},{kind:"decision",prompt:"Comment procèdes-tu concrètement à l'orientation ?",options:[{id:"a",label:"Tu appelles ou fais appeler les secours d'urgence sans délai, informes le patient simplement des raisons, et restes avec lui jusqu'à leur arrivée en réévaluant en continu",correct:!0,critical:!0},{id:"b",label:"Tu conseilles au patient de se rendre par ses propres moyens à une consultation médicale dans les prochains jours",critical:!0},{id:"c",label:"Tu attends la fin de la séance prévue avant d'agir, le patient ne semblant pas en détresse aiguë",critical:!0}],reveal:"Devant une suspicion de syndrome coronarien aigu, l'appel immédiat des secours d'urgence est la conduite appropriée, avec réévaluation continue du patient jusqu'à leur arrivée."}],discriminators:["Terrain à risque cardiovasculaire (âge, diabète, hypertension, antécédent familial) associé à un symptôme atypique évolutif plutôt que stable.","Apparition d'une dyspnée d'effort inhabituelle, non recherchée spontanément par le patient mais retrouvée à l'interrogatoire dirigé.","Signes discrets de mauvaise tolérance à l'examen (tachycardie, pâleur, sueurs) malgré l'absence de douleur thoracique.","Absence de reproduction mécanique de l'inconfort, qui affaiblit l'hypothèse digestive spontanément avancée par le patient."],redFlags:["Dyspnée d'effort inhabituelle chez un patient à risque cardiovasculaire, même isolée.","Signes discrets de mauvaise tolérance hémodynamique (tachycardie, pâleur, sueurs) sans cause évidente."],differential:["Syndrome coronarien aigu à présentation atypique, hypothèse retenue et prioritaire compte tenu du terrain.","Cause digestive bénigne, hypothèse initiale du patient, affaiblie par l'absence de reproduction mécanique et les signes associés.","Fatigue simple liée au repas, écartée par l'accumulation d'arguments discordants."],pitfalls:["Accepter l'explication spontanée et rassurante du patient (repas copieux) sans interrogatoire dirigé sur les symptômes cardiovasculaires.","Attendre l'apparition d'une douleur thoracique franche avant d'agir chez un patient à risque, alors que la présentation atypique est elle-même l'alerte.","Retarder l'appel des secours pour terminer une séance en cours alors qu'une suspicion d'urgence vitale est posée."],reasoning:"Chez un patient âgé et diabétique, l'absence de douleur thoracique typique ne permet pas d'écarter une cause cardiaque : c'est l'accumulation d'arguments discordants avec l'hypothèse bénigne initiale (dyspnée d'effort, signes discrets de mauvaise tolérance, absence de reproduction mécanique) qui doit faire basculer la décision vers une orientation en urgence, sans attendre un symptôme plus typique.",relatedIds:["5.12-DX-01","5.12-MG-03","5.12-MG-02"],sources:["OCHIAI-MI-ATYPICAL-ELDERLY","NICE-CG95","ERC-BLS2021"]},{id:"CASE-62",ue:"7.3",title:"Réévaluation après échec de soins",neutralTitle:"Lombalgie sans amélioration après plusieurs séances",priority:"A+",vignette:"Patient suivi pour une lombalgie : après plusieurs consultations, aucune amélioration notable. Il demande s'il faut continuer.",objective:"Réévaluer la démarche sans poursuivre à l'identique : reconsidérer l'hypothèse et le diagnostic différentiel, revoir les signes d'alarme, discuter l'incertitude et décider avec le patient de poursuivre, adapter, co-gérer ou orienter.",steps:[{kind:"anamnesis",prompt:"Après plusieurs séances sans amélioration, que fais-tu en premier à cette consultation ?",options:[{id:"a",label:"Réévaluer l'hypothèse de travail et rechercher des symptômes nouveaux ou modifiés",correct:!0},{id:"b",label:"Refaire le même traitement en espérant un effet"},{id:"c",label:"Attribuer l'absence d'amélioration à l'observance du patient sans réexaminer l'évaluation initiale"}],reveal:"NICE NG59 1.1.1 : penser à d'autres diagnostics lors de l'examen ou de la réévaluation, en particulier en cas de symptômes nouveaux ou modifiés. Répéter le même traitement sans revoir l'hypothèse est un piège."},{kind:"options",prompt:"Que reconsidères-tu ? (plusieurs réponses)",options:[{id:"a",label:"Un autre diagnostic que celui retenu au départ",correct:!0},{id:"b",label:"Les causes spécifiques (cancer, infection, traumatisme, maladie inflammatoire comme la spondyloarthrite)",correct:!0},{id:"c",label:"Si le traitement poursuivi est encore justifié ou doit être adapté (exercice, auto-prise en charge)",correct:!0},{id:"d",label:"Le nombre de séances officiel au-delà duquel il faut s'arrêter"}],reveal:"NICE NG59 1.1.1 (autres diagnostics, exclure les causes spécifiques), 1.2.1 et 1.2.7 (information et auto-prise en charge ; thérapie manuelle seulement dans un ensemble incluant l'exercice). Aucune source lue ne fixe un nombre de séances : ne pas en inventer un."},{kind:"exam",prompt:"Que fais-tu des signes d'alarme ?",options:[{id:"a",label:"Les revoir de façon explicite, surtout si des symptômes ont changé ou sont apparus",correct:!0},{id:"b",label:"Les considérer comme écartés puisqu'ils ont été recherchés à la première consultation",critical:!0},{id:"c",label:"Ne les rechercher que si le patient l'exige"}],reveal:"Les signes d'alarme se revoient à la réévaluation : un symptôme nouveau ou modifié peut changer l'hypothèse. Si une pathologie grave est suspectée, orienter selon les recommandations concernées (NICE NG59 1.1.1)."},{kind:"options",prompt:"Comment communiques-tu avec le patient ? (plusieurs réponses)",options:[{id:"a",label:"Dire que la démarche est réévaluée et expliquer pourquoi",correct:!0},{id:"b",label:"Discuter les options (poursuivre en modifiant, orienter, arrêter) en tenant compte de ses préférences",correct:!0},{id:"c",label:"Expliquer qu'aucune règle ne fixe un nombre de séances : la suite repose sur la réévaluation et sur ses préférences",correct:!0},{id:"d",label:"Lui garantir que le traitement finira par fonctionner"}],reveal:"Décision partagée : informations sur les options, préférences du patient, discussion de la suite (Elwyn et al., 2012). Documenter le raisonnement. Le filet de sécurité inclut des rendez-vous de réévaluation en temps utile (Jones et al., 2019)."},{kind:"decision",prompt:"Quelle est ta décision à ce stade ?",options:[{id:"a",label:"Réévaluer hypothèse, différentiel et signes d'alarme, puis décider avec le patient : adapter la prise en charge, co-gérer ou orienter",correct:!0,critical:!0},{id:"b",label:"Poursuivre à l'identique jusqu'à un nombre de séances fixé d'avance",critical:!0},{id:"c",label:"Arrêter les soins sans réévaluation ni orientation",critical:!0},{id:"d",label:"Orienter en urgence de façon systématique, sans nouveau signe d'alarme"}],reveal:"Ne pas poursuivre à l'identique par défaut : réévaluer l'hypothèse, le différentiel et les signes d'alarme, puis décider avec le patient s'il faut adapter, co-gérer ou orienter. Aucun nombre de séances n'est sourcé."}],discriminators:["Absence de changement après plusieurs consultations.","Symptômes nouveaux ou modifiés à rechercher à la réévaluation (NICE NG59 1.1.1).","Aucun nombre de séances sourcé : la décision repose sur la réévaluation, pas sur un seuil."],redFlags:["Symptôme nouveau ou modifié : penser à d'autres diagnostics et exclure les causes spécifiques (cancer, infection, traumatisme, maladie inflammatoire)."],differential:["Hypothèse de travail initiale à reconsidérer.","Cause spécifique (cancer, infection, traumatisme, spondyloarthrite) non reconnue au départ."],pitfalls:["Répéter le même traitement en espérant un effet, sans revoir l'hypothèse ni les signes d'alarme.","Attribuer l'absence d'amélioration à l'observance du patient sans réexaminer l'évaluation initiale.","Fixer de mémoire un nombre de séances avant réévaluation : aucune source lue n'en fixe (SOURCE_REQUIRED)."],reasoning:"Absence d'amélioration → réévaluer l'hypothèse de travail, le diagnostic différentiel et les signes d'alarme (symptômes nouveaux ou modifiés) → vérifier que la poursuite est justifiée (thérapie manuelle seulement avec exercice, auto-prise en charge) → décider avec le patient d'adapter, de co-gérer ou d'orienter. Application pédagogique : NICE NG59 est propre à la lombalgie au Royaume-Uni, son extension à d'autres régions ou pays est une extrapolation, et aucun nombre de séances n'est sourcé.",relatedIds:["7.3-CR-02","7.3-CR-01","7.3-KN-02","7.3-MG-03"],sources:["NICE-NG59","JONES-2019","ELWYN-2012"]}],a=i,r=new Map(a.map(e=>[e.id,e]));export{r as a,a as c};
